-- =====================================================================
-- BASELINE MIGRATION — live production schema snapshot
-- =====================================================================
-- Generated: 2026-08-13 from the linked project (ref cserfvellsliylifjkos,
--   "GamerVault", Postgres 17) via pg_dump --schema-only, using the exact
--   flag + sed pipeline the Supabase CLI's `db dump` produces (idempotent
--   CREATE ... IF NOT EXISTS / CREATE OR REPLACE forms).
--
-- WHY THIS EXISTS:
--   The project accumulated ~190 hand-authored .sql files in
--   supabase/migrations/ that were applied by hand via the Supabase SQL
--   Editor over months. Their filename versions collided badly (135 files
--   sharing only 47 distinct YYYYMMDD prefixes) and 33 had no timestamp at
--   all, so the CLI could never track them and `supabase db push` wanted to
--   replay everything against production. Those files are preserved read-only
--   in supabase/migrations_archive/ for historical reference.
--
--   This single file is the new baseline. It is timestamped 20260101000000
--   so it always sorts before any future migration. It is marked as already
--   applied on the remote (schema_migrations) via `migration repair`, so it
--   is NOT re-run against production. It only executes on a genuinely fresh
--   database (e.g. a new clone / local dev), where its idempotent statements
--   recreate the full public schema.
--
-- DO NOT edit this file to make schema changes. Add a NEW migration instead.
-- =====================================================================





SET statement_timeout = 0;
SET lock_timeout = 0;
SET idle_in_transaction_session_timeout = 0;
SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
SELECT pg_catalog.set_config('search_path', '', false);
SET check_function_bodies = false;
SET xmloption = content;
SET client_min_messages = warning;
SET row_security = off;


CREATE EXTENSION IF NOT EXISTS "pg_cron" WITH SCHEMA "pg_catalog";






COMMENT ON SCHEMA "public" IS 'standard public schema';



CREATE EXTENSION IF NOT EXISTS "pg_stat_statements" WITH SCHEMA "extensions";






CREATE EXTENSION IF NOT EXISTS "pgcrypto" WITH SCHEMA "extensions";






CREATE EXTENSION IF NOT EXISTS "supabase_vault" WITH SCHEMA "vault";






CREATE EXTENSION IF NOT EXISTS "uuid-ossp" WITH SCHEMA "extensions";






