CREATE OR REPLACE FUNCTION "public"."adopt_me_confidence_for"("listings" integer) RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select case
    when listings >= 25 then 'highly_accurate'
    when listings >= 10 then 'high'
    when listings >= 3  then 'medium'
    else 'low'
  end
$$;


ALTER FUNCTION "public"."adopt_me_confidence_for"("listings" integer) OWNER TO "postgres";


