CREATE OR REPLACE FUNCTION "public"."approve_listing"("listing_id" "uuid", "admin_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  seller_id_var uuid;
  current_approved_count integer;
BEGIN
  -- Get the seller_id
  SELECT seller_id INTO seller_id_var
  FROM public.listings
  WHERE id = listing_id;

  -- Update the listing
  UPDATE public.listings
  SET
    status = 'active',
    approved_by = admin_id,
    approved_at = now(),
    rejected_by = NULL,
    rejected_at = NULL,
    rejection_reason = NULL
  WHERE id = listing_id;

  -- Get current approved count
  SELECT COALESCE(
    (SELECT COUNT(*)
     FROM public.listings
     WHERE seller_id = seller_id_var
       AND status = 'active'
       AND approved_by IS NOT NULL),
    0
  ) INTO current_approved_count;

  RAISE NOTICE 'Listing % approved. Seller % now has % approved listings',
    listing_id, seller_id_var, current_approved_count;
END;
$$;


ALTER FUNCTION "public"."approve_listing"("listing_id" "uuid", "admin_id" "uuid") OWNER TO "postgres";


