CREATE OR REPLACE FUNCTION "public"."calculate_reapply_cooldown"("rejection_count_param" integer) RETURNS interval
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
BEGIN
  RETURN CASE
    WHEN rejection_count_param = 0 THEN interval '7 days'    -- First rejection: 7 days
    WHEN rejection_count_param = 1 THEN interval '30 days'   -- Second rejection: 30 days
    WHEN rejection_count_param = 2 THEN interval '90 days'   -- Third rejection: 90 days
    ELSE interval '999 years'  -- 4+ rejections: permanent ban (requires appeal)
  END;
END;
$$;


ALTER FUNCTION "public"."calculate_reapply_cooldown"("rejection_count_param" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."calculate_reapply_cooldown"("rejection_count_param" integer) IS 'Calculates cooldown period: 1st=7d, 2nd=30d, 3rd=90d, 4+=permanent';



CREATE OR REPLACE FUNCTION "public"."calculate_withdrawal_fee"("p_amount" numeric, "p_method_id" "uuid") RETURNS TABLE("fee_amount" numeric, "net_amount" numeric, "fee_percentage" numeric, "fee_fixed" numeric)
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_method withdrawal_methods%ROWTYPE;
  v_fee DECIMAL;
BEGIN
  -- Get method details
  SELECT * INTO v_method FROM withdrawal_methods WHERE id = p_method_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Withdrawal method not found';
  END IF;

  -- Calculate fee
  v_fee := (p_amount * v_method.fee_percentage / 100) + v_method.fee_fixed;

  -- Return calculated values
  RETURN QUERY SELECT
    v_fee,
    p_amount - v_fee,
    v_method.fee_percentage,
    v_method.fee_fixed;
END;
$$;


ALTER FUNCTION "public"."calculate_withdrawal_fee"("p_amount" numeric, "p_method_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."calculate_withdrawal_fee"("p_amount" numeric, "p_method_id" "uuid") IS 'Calculates withdrawal fee based on amount and method';



CREATE OR REPLACE FUNCTION "public"."can_edit_review"("review_id_param" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  review_record RECORD;
  user_id UUID;
BEGIN
  user_id := auth.uid();

  IF user_id IS NULL THEN
    RETURN false;
  END IF;

  SELECT
    reviewer_id,
    created_at,
    last_edited_at
  INTO review_record
  FROM reviews
  WHERE id = review_id_param;

  IF NOT FOUND THEN
    RETURN false;
  END IF;

  -- Check if user is the reviewer
  IF review_record.reviewer_id != user_id THEN
    RETURN false;
  END IF;

  -- Check if within 30-day window
  IF review_record.created_at < NOW() - INTERVAL '30 days' THEN
    RETURN false;
  END IF;

  -- Check if 24 hours have passed since last edit
  IF review_record.last_edited_at IS NOT NULL AND
     review_record.last_edited_at > NOW() - INTERVAL '24 hours' THEN
    RETURN false;
  END IF;

  RETURN true;
END;
$$;


ALTER FUNCTION "public"."can_edit_review"("review_id_param" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."can_edit_review"("review_id_param" "uuid") IS 'Check if current user can edit a specific review (30-day window, 24-hour frequency)';



CREATE OR REPLACE FUNCTION "public"."can_seller_reapply"("user_id_param" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  latest_app record;
  result jsonb;
BEGIN
  -- Get latest application
  SELECT * INTO latest_app
  FROM public.seller_applications
  WHERE user_id = user_id_param
  ORDER BY created_at DESC
  LIMIT 1;

  IF NOT FOUND THEN
    -- No application exists, can apply
    RETURN jsonb_build_object(
      'can_reapply', true,
      'reason', 'no_application'
    );
  END IF;

  -- Check various scenarios
  IF latest_app.status = 'approved' THEN
    RETURN jsonb_build_object(
      'can_reapply', false,
      'reason', 'already_approved',
      'message', 'You are already an approved seller'
    );
  END IF;

  IF latest_app.status IN ('pending', 'under_review') THEN
    RETURN jsonb_build_object(
      'can_reapply', false,
      'reason', 'pending_review',
      'message', 'Your application is currently under review'
    );
  END IF;

  IF latest_app.status = 'withdrawn' THEN
    -- Can reapply immediately after withdrawal
    RETURN jsonb_build_object(
      'can_reapply', true,
      'reason', 'withdrawn',
      'withdrawal_count', latest_app.withdrawal_count
    );
  END IF;

  IF latest_app.status = 'rejected' THEN
    IF latest_app.can_reapply_at IS NULL OR now() >= latest_app.can_reapply_at THEN
      -- Cooldown period has passed
      RETURN jsonb_build_object(
        'can_reapply', true,
        'reason', 'cooldown_expired',
        'rejection_count', latest_app.rejection_count
      );
    ELSE
      -- Still in cooldown period
      RETURN jsonb_build_object(
        'can_reapply', false,
        'reason', 'in_cooldown',
        'can_reapply_at', latest_app.can_reapply_at,
        'seconds_remaining', EXTRACT(EPOCH FROM (latest_app.can_reapply_at - now())),
        'rejection_count', latest_app.rejection_count,
        'rejection_reason', latest_app.rejection_reason,
        'rejection_category', latest_app.rejection_category,
        'is_permanent_ban', latest_app.rejection_count >= 4
      );
    END IF;
  END IF;

  -- Default: can reapply
  RETURN jsonb_build_object('can_reapply', true, 'reason', 'default');
END;
$$;


ALTER FUNCTION "public"."can_seller_reapply"("user_id_param" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."can_seller_reapply"("user_id_param" "uuid") IS 'Checks if seller can reapply based on current status and cooldown periods';



