CREATE OR REPLACE FUNCTION "public"."check_listing_moderation"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  -- IMPORTANT: Skip ALL checks if this is an admin approval
  -- An admin approval is when approved_by is being set to a non-null value
  IF NEW.approved_by IS NOT NULL THEN
    -- Admin is approving, allow the status change without interference
    RETURN NEW;
  END IF;

  -- Only check for new listings or status changes to 'active'
  IF (TG_OP = 'INSERT' OR (TG_OP = 'UPDATE' AND OLD.status != 'active')) AND NEW.status = 'active' THEN
    -- Check if seller needs moderation
    IF check_seller_needs_moderation(NEW.seller_id) THEN
      NEW.status = 'pending_approval';
      RAISE NOTICE 'Listing set to pending_approval for seller: %', NEW.seller_id;
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."check_listing_moderation"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_seller_needs_moderation"("seller_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_tier                  TEXT;
  v_pre_moderation_count  INTEGER;
  v_approved_count        INTEGER;
BEGIN
  SELECT seller_tier INTO v_tier
  FROM public.profiles
  WHERE id = seller_id;

  IF v_tier IS NULL THEN v_tier := 'unverified'; END IF;

  SELECT pre_moderation_listings INTO v_pre_moderation_count
  FROM public.seller_tier_config
  WHERE tier = v_tier;

  -- Unknown tier ⇒ behave like unverified.
  IF v_pre_moderation_count IS NULL THEN v_pre_moderation_count := 5; END IF;
  IF v_pre_moderation_count = 0 THEN RETURN FALSE; END IF;

  SELECT COUNT(*) INTO v_approved_count
  FROM public.listings
  WHERE listings.seller_id = check_seller_needs_moderation.seller_id
    AND listings.status IN ('active', 'sold', 'archived')
    AND listings.approved_at IS NOT NULL;

  RETURN v_approved_count < v_pre_moderation_count;
END;
$$;


ALTER FUNCTION "public"."check_seller_needs_moderation"("seller_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_seller_tier_eligibility"("p_user_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_profile          RECORD;
  v_total_sales      INTEGER;
  v_completion_rate  NUMERIC;
  v_account_age_days INTEGER;
  v_tier_config      RECORD;
  v_best_tier        TEXT := 'unverified';
BEGIN
  SELECT seller_rating, seller_tier, created_at
  INTO v_profile
  FROM public.profiles
  WHERE id = p_user_id;

  IF NOT FOUND THEN
    RETURN 'unverified';
  END IF;

  -- Completed sales
  SELECT COUNT(*) INTO v_total_sales
  FROM public.orders
  WHERE seller_id = p_user_id AND status = 'completed';

  -- Completion rate = completed / (all non-cancelled orders)
  SELECT
    CASE
      WHEN COUNT(*) = 0 THEN 100.0
      ELSE (COUNT(*) FILTER (WHERE status = 'completed') * 100.0 / COUNT(*))
    END
  INTO v_completion_rate
  FROM public.orders
  WHERE seller_id = p_user_id
    AND status NOT IN ('cancelled', 'refunded');

  -- Account age
  v_account_age_days := EXTRACT(DAY FROM NOW() - v_profile.created_at)::INTEGER;

  -- Walk tiers from highest to lowest, return first match
  FOR v_tier_config IN
    SELECT * FROM public.seller_tier_config ORDER BY sort_order DESC
  LOOP
    IF v_total_sales >= v_tier_config.min_sales
      AND (v_tier_config.min_rating IS NULL
           OR COALESCE(v_profile.seller_rating, 0) >= v_tier_config.min_rating)
      AND v_account_age_days >= v_tier_config.min_age_days
      AND (v_tier_config.min_completion_rate IS NULL
           OR v_completion_rate >= v_tier_config.min_completion_rate)
    THEN
      v_best_tier := v_tier_config.tier;
      EXIT;
    END IF;
  END LOOP;

  RETURN v_best_tier;
END;
$$;


ALTER FUNCTION "public"."check_seller_tier_eligibility"("p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."checkout_wallet_hold_minor"("p_order_id" "uuid") RETURNS bigint
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
  SELECT COALESCE(SUM(le.amount_minor), 0)::BIGINT
  FROM ledger_transactions lt
  JOIN ledger_entries le ON le.transaction_id = lt.id
  JOIN ledger_accounts la ON la.id = le.account_id
  WHERE lt.idempotency_key = 'checkout_wallet:' || p_order_id::text
    AND la.kind = 'escrow_held'
    AND le.direction = 'credit';
$$;


