CREATE OR REPLACE FUNCTION "public"."cleanup_old_audit_logs"("days_to_keep" integer DEFAULT 90) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  deleted_count INTEGER;
BEGIN
  DELETE FROM public.audit_logs
  WHERE created_at < NOW() - (days_to_keep || ' days')::INTERVAL
  AND action NOT IN ('admin_action', 'user_role_changed'); -- Keep critical logs longer

  GET DIAGNOSTICS deleted_count = ROW_COUNT;

  RETURN deleted_count;
END;
$$;


ALTER FUNCTION "public"."cleanup_old_audit_logs"("days_to_keep" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cleanup_old_audit_logs"("days_to_keep" integer) IS 'Cleanup function for GDPR compliance. Call with number of days to retain. Default: 90 days.';



CREATE OR REPLACE FUNCTION "public"."compute_audit_changes"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  -- Compute diff between old_data and new_data
  IF NEW.old_data IS NOT NULL AND NEW.new_data IS NOT NULL THEN
    NEW.changes = jsonb_object_agg(
      key,
      jsonb_build_object(
        'old', NEW.old_data -> key,
        'new', NEW.new_data -> key
      )
    )
    FROM (
      SELECT key
      FROM jsonb_each(NEW.old_data)
      WHERE NEW.old_data -> key IS DISTINCT FROM NEW.new_data -> key
    ) AS diff_keys;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."compute_audit_changes"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."decrypt_delivery_data"("p_encrypted_data" "text", "p_decryption_key" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  decrypted_data TEXT;
BEGIN
  -- Decrypt using AES-256
  decrypted_data := convert_from(
    decrypt(
      decode(p_encrypted_data, 'base64'),
      p_decryption_key::bytea,
      'aes'
    ),
    'utf8'
  );

  RETURN decrypted_data;
END;
$$;


ALTER FUNCTION "public"."decrypt_delivery_data"("p_encrypted_data" "text", "p_decryption_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."encrypt_delivery_data"("p_data" "text", "p_encryption_key" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  encrypted_data TEXT;
BEGIN
  -- Use AES-256 encryption with pgcrypto
  encrypted_data := encode(
    encrypt(
      p_data::bytea,
      p_encryption_key::bytea,
      'aes'
    ),
    'base64'
  );

  RETURN encrypted_data;
END;
$$;


ALTER FUNCTION "public"."encrypt_delivery_data"("p_data" "text", "p_encryption_key" "text") OWNER TO "postgres";


