CREATE OR REPLACE FUNCTION "public"."generate_referral_code"("p_username" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  new_code TEXT;
  attempts INT := 0;
BEGIN
  LOOP
    new_code := UPPER(
      SUBSTRING(REGEXP_REPLACE(COALESCE(p_username, 'USR'), '[^a-zA-Z0-9]', '', 'g') || 'USR', 1, 3) ||
      SUBSTRING(ENCODE(gen_random_bytes(4), 'hex'), 1, 6)
    );
    EXIT WHEN NOT EXISTS (
      SELECT 1 FROM public.profiles WHERE referral_code = new_code
    );
    attempts := attempts + 1;
    IF attempts > 10 THEN
      -- Pure-random fallback after repeated collisions
      new_code := UPPER(SUBSTRING(ENCODE(gen_random_bytes(5), 'hex'), 1, 8));
      EXIT;
    END IF;
  END LOOP;
  RETURN new_code;
END;
$$;


ALTER FUNCTION "public"."generate_referral_code"("p_username" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_referral_code_for_new_user"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
BEGIN
  IF NEW.referral_code IS NULL THEN
    NEW.referral_code := public.generate_referral_code(NEW.username);
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."generate_referral_code_for_new_user"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_shop_slug"("name" "text") RETURNS "text"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  base_slug TEXT;
  final_slug TEXT;
  counter INTEGER := 0;
BEGIN
  -- Convert to lowercase, replace spaces/special chars with hyphens
  base_slug := lower(regexp_replace(name, '[^a-zA-Z0-9]+', '-', 'g'));

  -- Remove leading/trailing hyphens
  base_slug := trim(both '-' from base_slug);

  -- Start with base slug
  final_slug := base_slug;

  -- Check for uniqueness and append number if needed
  WHILE EXISTS (SELECT 1 FROM profiles WHERE shop_slug = final_slug) LOOP
    counter := counter + 1;
    final_slug := base_slug || '-' || counter;
  END LOOP;

  RETURN final_slug;
END;
$$;


ALTER FUNCTION "public"."generate_shop_slug"("name" "text") OWNER TO "postgres";


