    "quantity" integer DEFAULT 1,
    "status" "text" DEFAULT 'active'::"text",
    "images" "text"[] DEFAULT '{}'::"text"[],
    "delivery_time" "text" DEFAULT '1-24 hours'::"text",
    "delivery_method" "text" DEFAULT 'manual'::"text",
