CREATE OR REPLACE FUNCTION "public"."get_my_permissions"() RETURNS "text"[]
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    AS $$
DECLARE perms TEXT[];
BEGIN
  SELECT ARRAY_AGG(rp.permission) INTO perms
  FROM admin_roles ar JOIN role_permissions rp ON ar.role = rp.role
  WHERE ar.user_id = auth.uid() AND ar.is_active = true;
  RETURN COALESCE(perms, ARRAY[]::TEXT[]);
END;
$$;


