COMMENT ON TABLE "public"."orders" IS 'Orders table with REPLICA IDENTITY FULL enabled for real-time subscriptions. Broadcasts INSERT, UPDATE, and DELETE events to subscribed clients.';



COMMENT ON COLUMN "public"."orders"."completed_at" IS 'Timestamp when order reached completed state. Set automatically by trigger.';



