COMMENT ON COLUMN "public"."orders"."auto_release_at" IS 'Timestamp when funds will be automatically released to seller if no action taken';



COMMENT ON COLUMN "public"."orders"."release_method" IS 'How the escrow was released: auto (48h timer), buyer_confirmed (early confirmation), admin (manual), dispute_resolved';



COMMENT ON COLUMN "public"."orders"."vaultshield_level" IS 'Buyer-chosen VaultShield tier (standard / enhanced / premium). Set by application at checkout.';



COMMENT ON COLUMN "public"."orders"."delivery_evidence_required" IS 'Whether seller must upload screenshot/video proof of delivery';



COMMENT ON COLUMN "public"."orders"."delivery_evidence_urls" IS 'Array of URLs to delivery evidence files (screenshots, videos) stored in Supabase Storage';



COMMENT ON COLUMN "public"."orders"."buyer_confirmed_at" IS 'When buyer manually confirmed delivery (early release)';



COMMENT ON COLUMN "public"."orders"."seller_marked_delivered_at" IS 'When seller clicked "Mark as Delivered" (starts auto-release timer)';



COMMENT ON COLUMN "public"."orders"."delivering_at" IS 'Timestamp when seller marked order as being delivered/processed';



COMMENT ON COLUMN "public"."orders"."is_guest_order" IS 'TRUE if the order was placed without a persistent account (guest checkout).';



COMMENT ON COLUMN "public"."orders"."chat_active_until" IS 'Chat remains active until this time. Set to 7 days after order completion. Admins can override for disputes.';



COMMENT ON COLUMN "public"."orders"."vaultshield_tier_fee_rate" IS 'Buyer-paid tier upgrade fee rate: 0 for Standard, 2 for Enhanced (+2%), 5 for Premium (+5%).';



COMMENT ON COLUMN "public"."orders"."vaultshield_tier_fee" IS 'Dollar amount charged for tier upgrade = subtotal * (tier_fee_rate / 100).';



COMMENT ON COLUMN "public"."orders"."warranty_expires_at" IS 'When the VaultShield warranty expires: +48h (Standard), +7d (Enhanced), +30d (Premium).';



COMMENT ON COLUMN "public"."orders"."cancelled_at" IS 'Timestamp when order reached cancelled state. Set automatically by trigger.';



COMMENT ON COLUMN "public"."orders"."version" IS 'Optimistic lock version. Increment on every status change. App must read+write with version check.';



COMMENT ON COLUMN "public"."orders"."wallet_amount_used" IS 'Amount of wallet balance used for this order (reduces Stripe charge)';



COMMENT ON COLUMN "public"."orders"."currency" IS 'ISO currency of the order. Historical orders backfilled to USD; new orders default EUR (CoinGate settlement currency). Used by safedrop_transition for ledger postings.';



COMMENT ON COLUMN "public"."orders"."checkout_url" IS 'CoinGate hosted payment URL for the current pending charge; reused when the buyer re-enters checkout.';



COMMENT ON COLUMN "public"."orders"."payment_expires_at" IS 'When the stored checkout_url stops being payable (~CoinGate invoice expiry). Past this, the pending order is superseded on re-checkout.';



