CREATE OR REPLACE FUNCTION "public"."handle_listing_quantity_change"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  -- Auto-mark as sold when quantity reaches 0 (no longer check is_unlimited)
  IF NEW.quantity = 0 AND OLD.quantity > 0 AND NEW.status = 'active' THEN
    NEW.status := 'sold';
  END IF;

  -- Auto-reactivate when restocked
  IF NEW.quantity > 0 AND OLD.quantity = 0 AND NEW.status = 'sold' THEN
    NEW.status := 'active';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."handle_listing_quantity_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."handle_new_user"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  username_value   TEXT;
  full_name_value  TEXT;
  avatar_url_value TEXT;
  is_guest_value   BOOLEAN;
  referral_value   TEXT;
BEGIN
  username_value := COALESCE(
    NEW.raw_user_meta_data->>'username',
    split_part(NEW.email, '@', 1),
    'user_' || substring(NEW.id::text, 1, 8)
  );
  full_name_value  := NEW.raw_user_meta_data->>'full_name';
  avatar_url_value := NEW.raw_user_meta_data->>'avatar_url';
  is_guest_value   := COALESCE((NEW.raw_user_meta_data->>'is_guest')::BOOLEAN, FALSE);

  -- Compute the code up front so the row is inserted already populated.
  BEGIN
    referral_value := public.generate_referral_code(username_value);
  EXCEPTION
    WHEN OTHERS THEN
      referral_value := NULL;  -- never let code generation block signup
      RAISE WARNING 'Referral code generation failed for user %: %', NEW.id, SQLERRM;
  END;

  BEGIN
    INSERT INTO public.profiles (
      id, username, full_name, avatar_url, email, is_guest, referral_code, created_at, updated_at
    )
    VALUES (
      NEW.id, username_value, full_name_value, avatar_url_value,
      NEW.email, is_guest_value, referral_value, NOW(), NOW()
    )
    ON CONFLICT (id) DO UPDATE
    SET
      email         = EXCLUDED.email,
      username      = COALESCE(EXCLUDED.username, profiles.username),
      full_name     = COALESCE(EXCLUDED.full_name, profiles.full_name),
      avatar_url    = COALESCE(EXCLUDED.avatar_url, profiles.avatar_url),
      is_guest      = EXCLUDED.is_guest,
      -- only fill the code on conflict if the existing row is missing one
      referral_code = COALESCE(profiles.referral_code, EXCLUDED.referral_code),
      updated_at    = NOW();
  EXCEPTION
    WHEN unique_violation THEN
      INSERT INTO public.profiles (
        id, username, full_name, avatar_url, email, is_guest, referral_code, created_at, updated_at
      )
      VALUES (
        NEW.id,
        username_value || '_' || substring(md5(random()::text), 1, 4),
        full_name_value, avatar_url_value, NEW.email, is_guest_value, referral_value, NOW(), NOW()
      )
      ON CONFLICT (id) DO UPDATE
      SET email = EXCLUDED.email,
          referral_code = COALESCE(profiles.referral_code, EXCLUDED.referral_code),
          updated_at = NOW();
    WHEN OTHERS THEN
      RAISE WARNING 'Error creating profile for user %: % (SQLSTATE: %)', NEW.id, SQLERRM, SQLSTATE;
  END;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."handle_new_user"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."handle_new_user"() IS 'Automatically creates profile on signup. Handles guest users and metadata extraction. Includes detailed logging for debugging.';



