CREATE OR REPLACE FUNCTION "public"."is_valid_order_transition"("old_status" "text", "new_status" "text") RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
BEGIN
  -- Terminal states — no transitions allowed (refunded is now terminal too)
  IF old_status IN ('completed', 'cancelled', 'refunded') THEN
    RETURN FALSE;
  END IF;

  -- Same status — allow (idempotent updates to other columns)
  IF old_status = new_status THEN
    RETURN TRUE;
  END IF;

  RETURN CASE old_status
    WHEN 'pending'    THEN new_status IN ('paid', 'cancelled')
    WHEN 'paid'       THEN new_status IN ('delivering', 'delivered', 'disputed', 'cancelled', 'refunded')
    WHEN 'delivering' THEN new_status IN ('delivered', 'disputed', 'cancelled', 'refunded')
    WHEN 'delivered'  THEN new_status IN ('completed', 'disputed', 'refunded')
    WHEN 'disputed'   THEN new_status IN ('completed', 'cancelled', 'refunded')
    ELSE FALSE
  END;
END;
$$;


ALTER FUNCTION "public"."is_valid_order_transition"("old_status" "text", "new_status" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."is_valid_order_transition"("old_status" "text", "new_status" "text") IS 'Returns TRUE if old_status → new_status is a permitted escrow state machine transition. Includes `refunded` (terminal) as of 20260628.';



CREATE OR REPLACE FUNCTION "public"."ledger_balance"("p_owner_type" "public"."ledger_owner_type", "p_owner_id" "uuid", "p_kind" "public"."ledger_account_kind", "p_currency" character) RETURNS bigint
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
  SELECT COALESCE(SUM(
    CASE WHEN le.direction = 'credit' THEN le.amount_minor ELSE -le.amount_minor END
  ), 0)::BIGINT
  FROM ledger_entries le
  JOIN ledger_accounts la ON la.id = le.account_id
  WHERE la.owner_type = p_owner_type
    AND COALESCE(la.owner_id, '00000000-0000-0000-0000-000000000000'::uuid)
        = COALESCE(p_owner_id, '00000000-0000-0000-0000-000000000000'::uuid)
    AND la.kind = p_kind
    AND la.currency = p_currency;
$$;


ALTER FUNCTION "public"."ledger_balance"("p_owner_type" "public"."ledger_owner_type", "p_owner_id" "uuid", "p_kind" "public"."ledger_account_kind", "p_currency" character) OWNER TO "postgres";


