CREATE OR REPLACE FUNCTION "public"."ledger_integrity_check"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_unbalanced JSONB;
  v_escrow_residue JSONB;
  v_stuck INT;
BEGIN
  -- 1. Every transaction balances to zero per currency (the core invariant).
  SELECT COALESCE(jsonb_agg(jsonb_build_object('transaction_id', t.transaction_id, 'currency', t.currency, 'net', t.net)), '[]'::jsonb)
    INTO v_unbalanced
  FROM (
    SELECT transaction_id, currency,
           SUM(CASE WHEN direction='credit' THEN amount_minor ELSE -amount_minor END) AS net
    FROM ledger_entries
    GROUP BY transaction_id, currency
    HAVING SUM(CASE WHEN direction='credit' THEN amount_minor ELSE -amount_minor END) <> 0
  ) t;

  -- 2. Completed/refunded orders should leave no escrow_held residue attributable
  --    to them (sum of that order's escrow_held entries nets to zero).
  SELECT COALESCE(jsonb_agg(jsonb_build_object('order_id', x.order_id, 'currency', x.currency, 'residue', x.residue)), '[]'::jsonb)
    INTO v_escrow_residue
  FROM (
    SELECT lt.order_id, le.currency,
           SUM(CASE WHEN le.direction='credit' THEN le.amount_minor ELSE -le.amount_minor END) AS residue
    FROM ledger_entries le
    JOIN ledger_accounts la ON la.id = le.account_id AND la.kind = 'escrow_held'
    JOIN ledger_transactions lt ON lt.id = le.transaction_id
    JOIN orders o ON o.id = lt.order_id AND o.status IN ('completed','refunded','cancelled')
    GROUP BY lt.order_id, le.currency
    HAVING SUM(CASE WHEN le.direction='credit' THEN le.amount_minor ELSE -le.amount_minor END) <> 0
  ) x;

  -- 3. Orders stuck in a non-terminal state too long (here: paid/delivered > 30d).
  SELECT COUNT(*) INTO v_stuck
  FROM orders
  WHERE status IN ('paid','delivering','delivered','disputed')
    AND created_at < NOW() - INTERVAL '30 days';

  RETURN jsonb_build_object(
    'ok', (jsonb_array_length(v_unbalanced) = 0 AND jsonb_array_length(v_escrow_residue) = 0 AND v_stuck = 0),
    'unbalanced_transactions', v_unbalanced,
    'escrow_residue_on_terminal_orders', v_escrow_residue,
    'stuck_nonterminal_orders', v_stuck,
    'checked_at', NOW()
  );
END;
$$;


ALTER FUNCTION "public"."ledger_integrity_check"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ledger_resolve_account"("p_owner_type" "public"."ledger_owner_type", "p_owner_id" "uuid", "p_kind" "public"."ledger_account_kind", "p_currency" character) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_id UUID;
BEGIN
  SELECT id INTO v_id
  FROM ledger_accounts
  WHERE owner_type = p_owner_type
    AND COALESCE(owner_id, '00000000-0000-0000-0000-000000000000'::uuid)
        = COALESCE(p_owner_id, '00000000-0000-0000-0000-000000000000'::uuid)
    AND kind = p_kind
    AND currency = p_currency;

  IF v_id IS NULL THEN
    INSERT INTO ledger_accounts (owner_type, owner_id, kind, currency)
    VALUES (p_owner_type, p_owner_id, p_kind, p_currency)
    ON CONFLICT (owner_type, COALESCE(owner_id, '00000000-0000-0000-0000-000000000000'::uuid), kind, currency)
      DO NOTHING
    RETURNING id INTO v_id;

    -- If a concurrent call inserted it first, re-select.
    IF v_id IS NULL THEN
      SELECT id INTO v_id
      FROM ledger_accounts
      WHERE owner_type = p_owner_type
        AND COALESCE(owner_id, '00000000-0000-0000-0000-000000000000'::uuid)
            = COALESCE(p_owner_id, '00000000-0000-0000-0000-000000000000'::uuid)
        AND kind = p_kind
        AND currency = p_currency;
    END IF;
  END IF;

  RETURN v_id;
END;
$$;


ALTER FUNCTION "public"."ledger_resolve_account"("p_owner_type" "public"."ledger_owner_type", "p_owner_id" "uuid", "p_kind" "public"."ledger_account_kind", "p_currency" character) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ledger_test_cleanup"("p_prefix" "text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_count INT;
BEGIN
  -- Safety rail: refuse to run unless the prefix is clearly a test namespace.
  IF p_prefix IS NULL OR p_prefix NOT LIKE 'test:ledger:%' THEN
    RAISE EXCEPTION 'ledger_test_cleanup: prefix must start with "test:ledger:" (got %)', p_prefix
      USING ERRCODE = 'check_violation';
  END IF;

  ALTER TABLE ledger_entries      DISABLE TRIGGER trg_ledger_entries_immutable;
  ALTER TABLE ledger_transactions DISABLE TRIGGER trg_ledger_transactions_immutable;

  DELETE FROM ledger_entries
  WHERE transaction_id IN (SELECT id FROM ledger_transactions WHERE idempotency_key LIKE p_prefix);

  DELETE FROM ledger_transactions WHERE idempotency_key LIKE p_prefix;
  GET DIAGNOSTICS v_count = ROW_COUNT;

  ALTER TABLE ledger_entries      ENABLE TRIGGER trg_ledger_entries_immutable;
  ALTER TABLE ledger_transactions ENABLE TRIGGER trg_ledger_transactions_immutable;

  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."ledger_test_cleanup"("p_prefix" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ledger_test_cleanup_by_order"("p_order_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_count INT;
BEGIN
  ALTER TABLE ledger_entries      DISABLE TRIGGER trg_ledger_entries_immutable;
  ALTER TABLE ledger_transactions DISABLE TRIGGER trg_ledger_transactions_immutable;

  DELETE FROM ledger_entries
  WHERE transaction_id IN (SELECT id FROM ledger_transactions WHERE order_id = p_order_id);

  DELETE FROM ledger_transactions WHERE order_id = p_order_id;
  GET DIAGNOSTICS v_count = ROW_COUNT;

  ALTER TABLE ledger_entries      ENABLE TRIGGER trg_ledger_entries_immutable;
  ALTER TABLE ledger_transactions ENABLE TRIGGER trg_ledger_transactions_immutable;

  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."ledger_test_cleanup_by_order"("p_order_id" "uuid") OWNER TO "postgres";


