CREATE OR REPLACE FUNCTION "public"."log_profile_privilege_changes"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF OLD.role IS DISTINCT FROM NEW.role THEN
    INSERT INTO audit_logs (action, table_name, record_id, old_data, new_data, user_id, created_at)
    VALUES ('ROLE_CHANGE', 'profiles', NEW.id,
      jsonb_build_object('role', OLD.role),
      jsonb_build_object('role', NEW.role),
      auth.uid(), NOW());
  END IF;

  IF OLD.seller_tier IS DISTINCT FROM NEW.seller_tier THEN
    INSERT INTO audit_logs (action, table_name, record_id, old_data, new_data, user_id, created_at)
    VALUES ('TIER_CHANGE', 'profiles', NEW.id,
      jsonb_build_object('seller_tier', OLD.seller_tier),
      jsonb_build_object('seller_tier', NEW.seller_tier),
      auth.uid(), NOW());
  END IF;

  IF OLD.is_verified IS DISTINCT FROM NEW.is_verified THEN
    INSERT INTO audit_logs (action, table_name, record_id, old_data, new_data, user_id, created_at)
    VALUES ('VERIFICATION_CHANGE', 'profiles', NEW.id,
      jsonb_build_object('is_verified', OLD.is_verified),
      jsonb_build_object('is_verified', NEW.is_verified),
      auth.uid(), NOW());
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."log_profile_privilege_changes"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."log_seller_application_event"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
begin
  if (TG_OP = 'INSERT') then
    insert into seller_verification_logs (application_id, action, is_system_action, details)
    values (NEW.id, 'application_started', true, jsonb_build_object('seller_type', NEW.seller_type));
  elsif (TG_OP = 'UPDATE') then
    if (OLD.status != NEW.status) then
      if (NEW.status = 'approved') then
        insert into seller_verification_logs (application_id, action, performed_by, details)
        values (NEW.id, 'approved', NEW.reviewed_by, jsonb_build_object('reviewed_at', NEW.reviewed_at));
      elsif (NEW.status = 'rejected') then
        insert into seller_verification_logs (application_id, action, performed_by, details)
        values (NEW.id, 'rejected', NEW.reviewed_by, jsonb_build_object('reason', NEW.rejection_reason));
      elsif (NEW.status = 'info_requested') then
        insert into seller_verification_logs (application_id, action, performed_by, details)
        values (NEW.id, 'info_requested', NEW.reviewed_by, jsonb_build_object('notes', NEW.admin_notes));
      elsif (NEW.status = 'under_review') then
        insert into seller_verification_logs (application_id, action, performed_by, details)
        values (NEW.id, 'review_started', NEW.reviewed_by, jsonb_build_object('started_at', now()));
      end if;
    end if;

    if (OLD.submitted_at is null and NEW.submitted_at is not null) then
      insert into seller_verification_logs (application_id, action, is_system_action, details)
      values (NEW.id, 'submitted_for_review', true, jsonb_build_object('submitted_at', NEW.submitted_at));
    end if;
  end if;

  return NEW;
end;
$$;


ALTER FUNCTION "public"."log_seller_application_event"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mark_inactive_sellers_offline"() RETURNS "void"
