CREATE OR REPLACE FUNCTION "public"."sab_capture_price_history"("p_date" "date" DEFAULT (("now"() AT TIME ZONE 'utc'::"text"))::"date") RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  captured_count bigint;
begin
  insert into public.sab_price_history (
    brainrot_id,
    mutation_id,
    history_date,
    median_usd,
    low_usd,
    high_usd,
    listing_count,
    source_count,
    confidence_label,
    is_trade_ready,
    is_public_estimate,
    price_updated_at
  )
  select
    catalog.brainrot_id,
    catalog.mutation_id,
    p_date,
    catalog.market_value_usd,
    catalog.market_low_usd,
    catalog.market_high_usd,
    coalesce(catalog.external_sample_size, 0),
    coalesce(catalog.source_count, 0),
    coalesce(catalog.confidence_label, 'low'),
    coalesce(catalog.is_trade_ready, false),
    coalesce(catalog.is_public_estimate, false),
    catalog.price_updated_at
  from public.sab_public_price_catalog_rows() catalog
  where catalog.market_value_usd >= 1.00

  -- Idempotent: re-running the same day refreshes that day's values but never
  -- creates duplicates. Past days remain whatever they were first captured as
  -- unless the job re-runs on the same calendar day.
  on conflict (brainrot_id, mutation_id, history_date)
  do update set
    median_usd = excluded.median_usd,
    low_usd = excluded.low_usd,
    high_usd = excluded.high_usd,
    listing_count = excluded.listing_count,
    source_count = excluded.source_count,
    confidence_label = excluded.confidence_label,
    is_trade_ready = excluded.is_trade_ready,
    is_public_estimate = excluded.is_public_estimate,
    price_updated_at = excluded.price_updated_at,
    captured_at = now();

  get diagnostics captured_count = row_count;

  return captured_count;
end;
$$;


ALTER FUNCTION "public"."sab_capture_price_history"("p_date" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."sab_capture_price_history"("p_date" "date") IS 'Captures today''s public catalog into sab_price_history. Idempotent per calendar day. Called by the daily /api/cron/snapshot-sab-prices job.';



CREATE OR REPLACE FUNCTION "public"."sab_import_market_listings"("p_source_slug" "text", "p_listings" "jsonb") RETURNS TABLE("import_run_id" "uuid", "source_slug" "text", "records_seen" integer, "records_inserted" integer, "records_updated" integer, "records_flagged" integer, "error_count" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_source_id uuid;
  v_source_name text;
  v_run_id uuid;

  v_item jsonb;
  v_external_listing_id text;
  v_title text;
  v_listing_url text;
  v_listing_type text;
  v_listing_status text;
  v_currency text;

  v_listed_price numeric;
  v_shipping_price numeric;
  v_total_price_usd numeric;
  v_quantity integer;

  v_observed_at timestamptz;
  v_existing boolean;
  v_parse_status text;

  v_seen integer := 0;
  v_inserted integer := 0;
  v_updated integer := 0;
  v_flagged integer := 0;
  v_error_count integer := 0;

  v_errors jsonb := '[]'::jsonb;
begin
  if p_listings is null
    or jsonb_typeof(p_listings) <> 'array'
  then
    raise exception
      'p_listings must be a JSON array';
  end if;

  select
    source.id,
    source.name
  into
    v_source_id,
    v_source_name
  from public.sab_market_sources source
  where source.slug = lower(trim(p_source_slug))
  limit 1;

  if v_source_id is null then
    raise exception
      'Unknown marketplace source: %',
      p_source_slug;
  end if;

  insert into public.sab_import_runs (
    source_name,
    status,
    details
  )
  values (
    v_source_name,
    'running',
    jsonb_build_object(
      'source_slug',
      lower(trim(p_source_slug)),
      'requested_count',
      jsonb_array_length(p_listings),
      'import_type',
      'market_listing_json'
    )
  )
  returning id into v_run_id;

  begin
    for v_item in
      select value
      from jsonb_array_elements(p_listings)
    loop
      v_seen := v_seen + 1;

      begin
        v_external_listing_id :=
          nullif(
            trim(v_item ->> 'external_listing_id'),
            ''
          );

        v_title :=
          nullif(
            trim(v_item ->> 'title'),
            ''
          );

        v_listing_url :=
          nullif(
            trim(v_item ->> 'listing_url'),
            ''
          );

        if v_external_listing_id is null then
          raise exception
            'external_listing_id is required';
        end if;

        if v_title is null then
          raise exception
            'title is required';
        end if;

        v_listing_type := coalesce(
          nullif(
            trim(v_item ->> 'listing_type'),
            ''
          ),
          'active_listing'
        );

        v_listing_status := coalesce(
          nullif(
            trim(v_item ->> 'listing_status'),
            ''
          ),
          case
            when v_listing_type = 'completed_sale'
              then 'sold'
            else 'active'
          end
        );

        v_currency := upper(
          coalesce(
            nullif(
              trim(v_item ->> 'currency'),
              ''
            ),
            'USD'
          )
        );

        v_listed_price := nullif(
          trim(v_item ->> 'listed_price'),
          ''
        )::numeric;

        v_shipping_price := coalesce(
          nullif(
            trim(v_item ->> 'shipping_price'),
            ''
          )::numeric,
          0
        );

        v_quantity := greatest(
          1,
          coalesce(
            nullif(
              trim(v_item ->> 'quantity'),
              ''
            )::integer,
            1
          )
        );

        v_total_price_usd := coalesce(
          nullif(
            trim(v_item ->> 'total_price_usd'),
            ''
          )::numeric,
          coalesce(v_listed_price, 0)
            + coalesce(v_shipping_price, 0)
        );

        if v_total_price_usd <= 0 then
          raise exception
            'total_price_usd must be greater than zero';
        end if;

        v_observed_at := coalesce(
          nullif(
            trim(v_item ->> 'observed_at'),
            ''
          )::timestamptz,
          now()
        );

        select exists (
          select 1
          from public.sab_market_raw_listings listing
          where listing.source_id = v_source_id
            and listing.external_listing_id =
              v_external_listing_id
        )
        into v_existing;

        insert into public.sab_market_raw_listings (
          source_id,
          external_listing_id,
          listing_url,

          listing_type,
          listing_status,

          title,

          currency,
          listed_price,
          shipping_price,
          quantity,
          total_price_usd,

          observed_at,
          fetched_at,

          raw_payload
        )
        values (
          v_source_id,
          v_external_listing_id,
          v_listing_url,

          v_listing_type,
          v_listing_status,

          v_title,

          v_currency,
          v_listed_price,
          v_shipping_price,
          v_quantity,
          v_total_price_usd,

          v_observed_at,
          now(),

          v_item
        )

        on conflict (
          source_id,
          external_listing_id
        )
        do update set
          listing_url =
            excluded.listing_url,

          listing_type =
            excluded.listing_type,

          listing_status =
            excluded.listing_status,

          title =
            excluded.title,

          currency =
            excluded.currency,

          listed_price =
            excluded.listed_price,

          shipping_price =
            excluded.shipping_price,

          quantity =
            excluded.quantity,

          total_price_usd =
            excluded.total_price_usd,

          observed_at =
            excluded.observed_at,

          fetched_at =
            now(),

          raw_payload =
            excluded.raw_payload,

          updated_at =
            now()

        returning parse_status
        into v_parse_status;

        if v_existing then
          v_updated := v_updated + 1;
        else
          v_inserted := v_inserted + 1;
        end if;

        if coalesce(v_parse_status, 'unmatched')
          <> 'matched'
        then
          v_flagged := v_flagged + 1;
        end if;

      exception
        when others then
          v_error_count := v_error_count + 1;
          v_flagged := v_flagged + 1;

          v_errors := v_errors || jsonb_build_array(
            jsonb_build_object(
              'row_number',
              v_seen,
              'external_listing_id',
              v_item ->> 'external_listing_id',
              'error',
              sqlerrm
            )
          );
      end;
    end loop;

    update public.sab_import_runs
    set
      status = 'completed',
      pages_seen = 1,
      records_inserted = v_inserted,
      records_updated = v_updated,
      records_flagged = v_flagged,

      details = details || jsonb_build_object(
        'records_seen',
        v_seen,
        'error_count',
        v_error_count,
        'errors',
        v_errors
      ),

      completed_at = now()
    where id = v_run_id;

  exception
    when others then
      update public.sab_import_runs
      set
        status = 'failed',
        error_message = sqlerrm,
        details = details || jsonb_build_object(
          'records_seen',
          v_seen,
          'error_count',
          v_error_count,
          'errors',
          v_errors
        ),
        completed_at = now()
      where id = v_run_id;

      raise;
  end;

  return query
  select
    v_run_id,
    lower(trim(p_source_slug)),
    v_seen,
    v_inserted,
    v_updated,
    v_flagged,
    v_error_count;
end;
$$;


ALTER FUNCTION "public"."sab_import_market_listings"("p_source_slug" "text", "p_listings" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sab_normalize_market_text"("input_text" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE STRICT
    AS $$
  select trim(
    regexp_replace(
      lower(input_text),
      '[^a-z0-9]+',
      ' ',
      'g'
    )
  );
$$;


ALTER FUNCTION "public"."sab_normalize_market_text"("input_text" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sab_parse_market_title"("input_text" "text") RETURNS TABLE("normalized_text" "text", "brainrot_id" "uuid", "brainrot_name" "text", "brainrot_slug" "text", "mutation_id" "uuid", "mutation_name" "text", "mutation_slug" "text", "parse_status" "text", "parser_confidence" numeric, "matched_brainrot_alias" "text", "matched_mutation_alias" "text", "rejection_category" "text", "rejection_reason" "text")
    LANGUAGE "plpgsql" STABLE
    AS $$
declare
  v_normalized text;
  v_remaining text;

  v_rejection_category text;
  v_rejection_reason text;

  v_brainrot_id uuid;
  v_brainrot_alias text;
  v_brainrot_alias_length integer;
  v_brainrot_priority integer;
  v_brainrot_ties integer;
  v_brainrot_name text;
  v_brainrot_slug text;

  v_mutation_id uuid;
  v_mutation_alias text;
  v_mutation_alias_length integer;
  v_mutation_priority integer;
  v_mutation_ties integer;
  v_mutation_name text;
  v_mutation_slug text;

  v_confidence numeric;
begin
  v_normalized :=
    public.sab_normalize_market_text(
      coalesce(input_text, '')
    );

  if v_normalized = '' then
    return query
    select
      v_normalized,
      null::uuid,
      null::text,
      null::text,
      null::uuid,
      null::text,
      null::text,
      'rejected'::text,
      0.000::numeric,
      null::text,
      null::text,
      'unrelated'::text,
      'Listing title is empty'::text;

    return;
  end if;

  -- Reject bundles, accounts, inventories, services,
  -- and listings with unclear mutations.
  select
    pattern.category,
    pattern.reason
  into
    v_rejection_category,
    v_rejection_reason
  from public.sab_market_rejection_patterns pattern
  where pattern.is_active = true
    and (
      ' ' || v_normalized || ' '
      like
      '% ' || pattern.normalized_pattern || ' %'
    )
  order by
    pattern.priority desc,
    length(pattern.normalized_pattern) desc
  limit 1;

  if v_rejection_category is not null then
    return query
    select
      v_normalized,
      null::uuid,
      null::text,
      null::text,
      null::uuid,
      null::text,
      null::text,
      'rejected'::text,
      0.000::numeric,
      null::text,
      null::text,
      v_rejection_category,
      v_rejection_reason;

    return;
  end if;

  -- Find the strongest Brainrot match.
  with per_brainrot as (
    select distinct on (alias.brainrot_id)
      alias.brainrot_id,
      alias.normalized_alias,
      length(alias.normalized_alias) as alias_length,
      alias.priority
    from public.sab_brainrot_aliases alias
    where alias.is_active = true
      and (
        ' ' || v_normalized || ' '
        like
        '% ' || alias.normalized_alias || ' %'
      )
    order by
      alias.brainrot_id,
      length(alias.normalized_alias) desc,
      alias.priority desc
  )
  select
    candidate.brainrot_id,
    candidate.normalized_alias,
    candidate.alias_length,
    candidate.priority
  into
    v_brainrot_id,
    v_brainrot_alias,
    v_brainrot_alias_length,
    v_brainrot_priority
  from per_brainrot candidate
  order by
    candidate.alias_length desc,
    candidate.priority desc
  limit 1;

  if v_brainrot_id is null then
    return query
    select
      v_normalized,
      null::uuid,
      null::text,
      null::text,
      null::uuid,
      null::text,
      null::text,
      'unmatched'::text,
      0.000::numeric,
      null::text,
      null::text,
      null::text,
      'No Brainrot name was recognized'::text;

    return;
  end if;

  -- Check whether multiple Brainrots have the same
  -- strongest match.
  with per_brainrot as (
    select distinct on (alias.brainrot_id)
      alias.brainrot_id,
      length(alias.normalized_alias) as alias_length,
      alias.priority
    from public.sab_brainrot_aliases alias
    where alias.is_active = true
      and (
        ' ' || v_normalized || ' '
        like
        '% ' || alias.normalized_alias || ' %'
      )
    order by
      alias.brainrot_id,
      length(alias.normalized_alias) desc,
      alias.priority desc
  )
  select count(*)
  into v_brainrot_ties
  from per_brainrot candidate
  where candidate.alias_length =
      v_brainrot_alias_length
    and candidate.priority =
      v_brainrot_priority;

  if v_brainrot_ties > 1 then
    return query
    select
      v_normalized,
      null::uuid,
      null::text,
      null::text,
      null::uuid,
      null::text,
      null::text,
      'ambiguous'::text,
      0.300::numeric,
      v_brainrot_alias,
      null::text,
      null::text,
      'Multiple Brainrots matched equally'::text;

    return;
  end if;

  select
    brainrot.name,
    brainrot.slug
  into
    v_brainrot_name,
    v_brainrot_slug
  from public.sab_brainrots brainrot
  where brainrot.id = v_brainrot_id;

  -- Remove the matched Brainrot name before looking
  -- for mutation words. This prevents mutation words
  -- inside a Brainrot name from causing false matches.
  v_remaining :=
    public.sab_normalize_market_text(
      replace(
        ' ' || v_normalized || ' ',
        ' ' || v_brainrot_alias || ' ',
        ' '
      )
    );

  -- Find the strongest mutation match.
  with per_mutation as (
    select distinct on (alias.mutation_id)
      alias.mutation_id,
      alias.normalized_alias,
      length(alias.normalized_alias) as alias_length,
      alias.priority
    from public.sab_mutation_aliases alias
    where alias.is_active = true
      and (
        ' ' || v_remaining || ' '
        like
        '% ' || alias.normalized_alias || ' %'
      )
    order by
      alias.mutation_id,
      length(alias.normalized_alias) desc,
      alias.priority desc
  )
  select
    candidate.mutation_id,
    candidate.normalized_alias,
    candidate.alias_length,
    candidate.priority
  into
    v_mutation_id,
    v_mutation_alias,
    v_mutation_alias_length,
    v_mutation_priority
  from per_mutation candidate
  order by
    candidate.alias_length desc,
    candidate.priority desc
  limit 1;

  if v_mutation_id is not null then
    with per_mutation as (
      select distinct on (alias.mutation_id)
        alias.mutation_id,
        length(alias.normalized_alias) as alias_length,
        alias.priority
      from public.sab_mutation_aliases alias
      where alias.is_active = true
        and (
          ' ' || v_remaining || ' '
          like
          '% ' || alias.normalized_alias || ' %'
        )
      order by
        alias.mutation_id,
        length(alias.normalized_alias) desc,
        alias.priority desc
    )
    select count(*)
    into v_mutation_ties
    from per_mutation candidate
    where candidate.alias_length =
        v_mutation_alias_length
      and candidate.priority =
        v_mutation_priority;

    if v_mutation_ties > 1 then
      return query
      select
        v_normalized,
        v_brainrot_id,
        v_brainrot_name,
        v_brainrot_slug,
        null::uuid,
        null::text,
        null::text,
        'ambiguous'::text,
        0.500::numeric,
        v_brainrot_alias,
        null::text,
        'ambiguous_mutation'::text,
        'Multiple mutations matched equally'::text;

      return;
    end if;

    v_confidence := 0.980;
  else
    -- No mutation was stated, so use Default.
    select
      mutation.id,
      mutation.name,
      mutation.slug
    into
      v_mutation_id,
      v_mutation_name,
      v_mutation_slug
    from public.sab_mutations mutation
    where mutation.slug = 'default'
    limit 1;

    v_mutation_alias := null;
    v_confidence := 0.900;
  end if;

  if v_mutation_name is null then
    select
      mutation.name,
      mutation.slug
    into
      v_mutation_name,
      v_mutation_slug
    from public.sab_mutations mutation
    where mutation.id = v_mutation_id;
  end if;

  return query
  select
    v_normalized,
    v_brainrot_id,
    v_brainrot_name,
    v_brainrot_slug,
    v_mutation_id,
    v_mutation_name,
    v_mutation_slug,
    'matched'::text,
    v_confidence,
    v_brainrot_alias,
    v_mutation_alias,
    null::text,
    null::text;
end;
$$;


ALTER FUNCTION "public"."sab_parse_market_title"("input_text" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sab_parse_raw_listing_trigger"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  parsed record;
begin
  select *
  into parsed
  from public.sab_parse_market_title(new.title)
  limit 1;

  new.brainrot_id := parsed.brainrot_id;
  new.mutation_id := parsed.mutation_id;
  new.parse_status := parsed.parse_status;
  new.parser_confidence := parsed.parser_confidence;
  new.rejection_reason := parsed.rejection_reason;

  new.is_bundle := coalesce(
    parsed.rejection_category = 'bundle',
    false
  );

  new.is_account_listing := coalesce(
    parsed.rejection_category = 'account',
    false
  );

  new.is_inventory_listing := coalesce(
    parsed.rejection_category = 'inventory',
    false
  );

  new.updated_at := now();

  return new;
end;
$$;


ALTER FUNCTION "public"."sab_parse_raw_listing_trigger"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sab_public_price_catalog_rows"() RETURNS TABLE("brainrot_id" "uuid", "brainrot_name" "text", "brainrot_slug" "text", "rarity" "text", "image_url" "text", "mutation_id" "uuid", "mutation_name" "text", "mutation_slug" "text", "market_value_usd" numeric, "market_low_usd" numeric, "market_high_usd" numeric, "confidence_label" "text", "external_sample_size" integer, "source_count" integer, "price_updated_at" timestamp with time zone, "is_trade_ready" boolean, "is_public_estimate" boolean)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  with verified_prices as (
    select
      price.brainrot_id,
      price.mutation_id,
      price.market_value_usd::numeric(12, 2) as market_value_usd,
      coalesce(price.market_low_usd, price.market_value_usd)::numeric(12, 2) as market_low_usd,
      coalesce(price.market_high_usd, price.market_value_usd)::numeric(12, 2) as market_high_usd,
      coalesce(price.confidence_label, 'low')::text as confidence_label,
      coalesce(price.external_sample_size, 0)::integer as external_sample_size,
      price.price_updated_at::timestamptz as price_updated_at,
      price.is_trade_ready::boolean as is_trade_ready
    from public.sab_trade_price_catalog price
    where price.market_value_usd > 0
  ),

  marketplace_estimates as (
    select
      estimate.brainrot_id,
      estimate.mutation_id,
      estimate.estimate_usd::numeric(12, 2) as market_value_usd,
      coalesce(estimate.low_usd, estimate.estimate_usd)::numeric(12, 2) as market_low_usd,
      coalesce(estimate.high_usd, estimate.estimate_usd)::numeric(12, 2) as market_high_usd,
      case
        when estimate.total_sample_count >= 10 then 'high'
        when estimate.total_sample_count >= 5 then 'medium'
        else 'low'
      end::text as confidence_label,
      estimate.total_sample_count::integer as external_sample_size,
      estimate.source_count::integer as source_count,
      estimate.latest_observed_at::timestamptz as price_updated_at,
      estimate.is_trade_ready::boolean as is_trade_ready
    from public.sab_market_variant_price_estimates estimate
    where estimate.estimate_usd > 0
      and estimate.total_sample_count >= 1
  ),

  merged_prices as (
    select
      coalesce(estimate.brainrot_id, verified.brainrot_id) as brainrot_id,
      coalesce(estimate.mutation_id, verified.mutation_id) as mutation_id,

      -- PREFER PIPELINE A (the cluster-aware live estimate). Pipeline B
      -- (verified/wide-range) is a fallback only when there is no estimate.
      coalesce(estimate.market_value_usd, verified.market_value_usd)::numeric(12, 2)
        as market_value_usd,

      coalesce(
        estimate.market_low_usd,
        verified.market_low_usd,
        estimate.market_value_usd,
        verified.market_value_usd
      )::numeric(12, 2) as market_low_usd,

      coalesce(
        estimate.market_high_usd,
        verified.market_high_usd,
        estimate.market_value_usd,
        verified.market_value_usd
      )::numeric(12, 2) as market_high_usd,

      -- Confidence + sample size follow whichever value we chose: estimate
      -- first, verified as fallback.
      coalesce(estimate.confidence_label, verified.confidence_label, 'low')::text
        as confidence_label,

      coalesce(estimate.external_sample_size, verified.external_sample_size, 0)::integer
        as external_sample_size,

      coalesce(
        estimate.source_count,
        case when verified.brainrot_id is not null then 1 else 0 end
      )::integer as source_count,

      coalesce(
        greatest(verified.price_updated_at, estimate.price_updated_at),
        estimate.price_updated_at,
        verified.price_updated_at
      )::timestamptz as price_updated_at,

      (coalesce(estimate.is_trade_ready, false) or coalesce(verified.is_trade_ready, false))::boolean
        as is_trade_ready,

      (estimate.brainrot_id is not null)::boolean as is_public_estimate

    from marketplace_estimates estimate
    full join verified_prices verified
      on verified.brainrot_id = estimate.brainrot_id
     and verified.mutation_id = estimate.mutation_id
  )

  select
    brainrot.id::uuid as brainrot_id,
    brainrot.name::text as brainrot_name,
    brainrot.slug::text as brainrot_slug,
    brainrot.rarity::text as rarity,
    brainrot.image_url::text as image_url,
    mutation.id::uuid as mutation_id,
    mutation.name::text as mutation_name,
    mutation.slug::text as mutation_slug,
    merged.market_value_usd::numeric(12, 2) as market_value_usd,
    merged.market_low_usd::numeric(12, 2) as market_low_usd,
    merged.market_high_usd::numeric(12, 2) as market_high_usd,
    merged.confidence_label::text as confidence_label,
    merged.external_sample_size::integer as external_sample_size,
    merged.source_count::integer as source_count,
    merged.price_updated_at::timestamptz as price_updated_at,
    merged.is_trade_ready::boolean as is_trade_ready,
    merged.is_public_estimate::boolean as is_public_estimate
  from merged_prices merged
  join public.sab_brainrot_catalog brainrot
    on brainrot.id = merged.brainrot_id
  join public.sab_mutation_catalog mutation
    on mutation.id = merged.mutation_id
  where merged.market_value_usd > 0;
$$;


ALTER FUNCTION "public"."sab_public_price_catalog_rows"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sab_publish_market_estimates"() RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    SET "statement_timeout" TO '120s'
    AS $$
declare
  published_count bigint;
begin
  update public.sab_external_market_observations
    observation
  set
    is_active = false,
    updated_at = now()
  where observation.source_name =
      'Automated multi-market estimate'
    and observation.source_reference like
      'auto-multi-market:%'
    and not exists (
      select 1
      from public.sab_market_variant_price_estimates
        estimate
      where estimate.is_trade_ready = true
        and observation.source_reference =
          'auto-multi-market:'
          || estimate.brainrot_id::text
          || ':'
          || estimate.mutation_id::text
    );

  insert into public.sab_external_market_observations (
    brainrot_id,
    mutation_id,

    observation_type,

    source_name,
    source_reference,

    currency,

    price_usd,
    price_low_usd,
    price_high_usd,

    sample_size,
    confidence_score,

    observed_at,
    expires_at,

    is_verified,
    is_active,

    notes
  )
  select
    estimate.brainrot_id,
    estimate.mutation_id,

    'market_range',

    'Automated multi-market estimate',
    'auto-multi-market:'
      || estimate.brainrot_id::text
      || ':'
      || estimate.mutation_id::text,

    'USD',

    estimate.estimate_usd,
    estimate.low_usd,
    estimate.high_usd,

    estimate.total_sample_count,

    case estimate.confidence_label
      when 'high' then 0.850
      when 'medium' then 0.700
      when 'low' then 0.550
      else 0.400
    end,

    estimate.latest_observed_at,
    now() + interval '48 hours',

    false,
    true,

    format(
      'Automated estimate from %s marketplace(s) and %s valid listing(s)',
      estimate.source_count,
      estimate.total_sample_count
    )

  from public.sab_market_variant_price_estimates
    estimate

  where estimate.is_trade_ready = true
    and estimate.estimate_usd >= 1.00

  on conflict (
    source_name,
    source_reference
  )
  where source_reference is not null

  do update set
    observation_type =
      excluded.observation_type,

    price_usd =
      excluded.price_usd,

    price_low_usd =
      excluded.price_low_usd,

    price_high_usd =
      excluded.price_high_usd,

    sample_size =
      excluded.sample_size,

    confidence_score =
      excluded.confidence_score,

    observed_at =
      excluded.observed_at,

    expires_at =
      excluded.expires_at,

    is_active = true,

    notes =
      excluded.notes,

    updated_at = now();

  get diagnostics published_count = row_count;

  return published_count;
end;
$$;


ALTER FUNCTION "public"."sab_publish_market_estimates"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sab_recompute_tradeable"() RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  changed bigint;
begin
  update public.sab_brainrots b
  set is_tradeable = (
       exists (
         select 1 from public.sab_price_corrections c
         where c.brainrot_id = b.id
           and c.is_publishable
           and c.reason in ('reputable', 'trusted')
       )
    or b.popularity_rank is not null
  )
  where b.id is not null;
  get diagnostics changed = row_count;
  return changed;
end
$$;


ALTER FUNCTION "public"."sab_recompute_tradeable"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sab_refresh_price_display"() RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    SET "statement_timeout" TO '120s'
    AS $$
declare
  row_count bigint;
begin
  -- Full refresh: the corrected view is the source of truth and the row set is
  -- small (~3k). Delete-all + insert inside the function's transaction is atomic
  -- to readers (no partial state) and avoids per-row conflict handling.
  delete from public.sab_price_display;

  insert into public.sab_price_display (
    brainrot_id, brainrot_name, brainrot_slug, rarity, image_url,
    mutation_id, mutation_name, mutation_slug,
    market_value_usd, market_low_usd, market_high_usd,
    confidence_label, external_sample_size, source_count,
    price_updated_at, is_trade_ready, is_public_estimate,
    is_anchored, correction_reason, anchor_usd, cohort_size,
    cheapest_usd, average_usd, refreshed_at
  )
  select
    brainrot_id, brainrot_name, brainrot_slug, rarity, image_url,
    mutation_id, mutation_name, mutation_slug,
    market_value_usd, market_low_usd, market_high_usd,
    confidence_label, external_sample_size, source_count,
    price_updated_at, is_trade_ready, is_public_estimate,
    is_anchored, correction_reason, anchor_usd, cohort_size,
    cheapest_usd, average_usd, now()
  from public.sab_public_price_catalog_corrected;

  get diagnostics row_count = row_count;
  return row_count;
end;
$$;


ALTER FUNCTION "public"."sab_refresh_price_display"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sab_refresh_price_snapshots"("p_calculated_at" timestamp with time zone DEFAULT "now"()) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  inserted_rows integer;
begin
  with eligible_observations as (
    select
      o.brainrot_id,

      case
        when o.observation_type in (
          'active_listing',
          'dropmarket_listing'
        ) then 'listing'
        when o.observation_type in (
          'completed_sale',
          'dropmarket_sale'
        ) then 'sale'
      end as market_kind,

      coalesce(
        o.unit_price_usd,
        o.price_usd / nullif(o.quantity, 0)
      )::numeric as effective_unit_price,

      o.seller_identifier_hash,
      o.observed_at

    from public.sab_market_observations o
    where o.is_valid = true
      and coalesce(
        o.unit_price_usd,
        o.price_usd / nullif(o.quantity, 0)
      ) > 0

      and (
        (
          o.observation_type in (
            'active_listing',
            'dropmarket_listing'
          )
          and o.observed_at >= p_calculated_at - interval '24 hours'
        )
        or
        (
          o.observation_type in (
            'completed_sale',
            'dropmarket_sale'
          )
          and o.observed_at >= p_calculated_at - interval '90 days'
        )
      )
  ),

  market_statistics as (
    select
      b.id as brainrot_id,

      count(e.*) filter (
        where e.market_kind = 'listing'
      )::integer as active_listing_count,

      count(e.*) filter (
        where e.market_kind = 'sale'
      )::integer as completed_sale_count_90d,

      count(e.*) filter (
        where e.market_kind = 'sale'
          and e.observed_at >= p_calculated_at - interval '30 days'
      )::integer as completed_sale_count_30d,

      count(distinct e.seller_identifier_hash)::integer
        as unique_seller_count,

      min(e.effective_unit_price) filter (
        where e.market_kind = 'listing'
      ) as market_floor_usd,

      percentile_cont(0.25) within group (
        order by e.effective_unit_price
      ) filter (
        where e.market_kind = 'listing'
      ) as active_listing_p25,

      percentile_cont(0.50) within group (
        order by e.effective_unit_price
      ) filter (
        where e.market_kind = 'listing'
      ) as active_listing_median,

      percentile_cont(0.75) within group (
        order by e.effective_unit_price
      ) filter (
        where e.market_kind = 'listing'
      ) as active_listing_p75,

      percentile_cont(0.25) within group (
        order by e.effective_unit_price
      ) filter (
        where e.market_kind = 'sale'
          and e.observed_at >= p_calculated_at - interval '30 days'
      ) as sale_30d_p25,

      percentile_cont(0.50) within group (
        order by e.effective_unit_price
      ) filter (
        where e.market_kind = 'sale'
          and e.observed_at >= p_calculated_at - interval '30 days'
      ) as sale_30d_median,

      percentile_cont(0.75) within group (
        order by e.effective_unit_price
      ) filter (
        where e.market_kind = 'sale'
          and e.observed_at >= p_calculated_at - interval '30 days'
      ) as sale_30d_p75,

      percentile_cont(0.25) within group (
        order by e.effective_unit_price
      ) filter (
        where e.market_kind = 'sale'
      ) as sale_90d_p25,

      percentile_cont(0.50) within group (
        order by e.effective_unit_price
      ) filter (
        where e.market_kind = 'sale'
      ) as sale_90d_median,

      percentile_cont(0.75) within group (
        order by e.effective_unit_price
      ) filter (
        where e.market_kind = 'sale'
      ) as sale_90d_p75,

      min(e.effective_unit_price) as observed_low_usd,
      max(e.effective_unit_price) as observed_high_usd

    from public.sab_brainrots b
    left join eligible_observations e
      on e.brainrot_id = b.id

    where b.is_active = true
      and b.needs_review = false

    group by b.id
  ),

  calculated_prices as (
    select
      s.*,

      case
        when completed_sale_count_30d >= 3
          then sale_30d_p25
        when completed_sale_count_90d >= 3
          then sale_90d_p25
        when active_listing_count >= 3
          then active_listing_p25
      end as quick_sale_usd,

      case
        when completed_sale_count_30d >= 3
          then sale_30d_median
        when completed_sale_count_90d >= 3
          then sale_90d_median
        when active_listing_count >= 3
          then active_listing_median
      end as typical_sale_usd,

      case
        when completed_sale_count_30d >= 3
          then sale_30d_p75
        when completed_sale_count_90d >= 3
          then sale_90d_p75
        when active_listing_count >= 3
          then active_listing_p75
      end as patient_sale_usd,

      case
        when completed_sale_count_30d >= 10
         and unique_seller_count >= 5
          then 'high'

        when completed_sale_count_30d >= 5
          or completed_sale_count_90d >= 10
          then 'medium'

        when completed_sale_count_30d >= 3
          or completed_sale_count_90d >= 3
          or active_listing_count >= 3
          then 'low'

        else 'insufficient'
      end as confidence_label

    from market_statistics s
  )

  insert into public.sab_price_snapshots (
    brainrot_id,
    mutation_id,
    market_floor_usd,
    quick_sale_usd,
    typical_sale_usd,
    patient_sale_usd,
    observed_low_usd,
    observed_high_usd,
    active_listing_count,
    completed_sale_count,
    unique_seller_count,
    confidence_score,
    confidence_label,
    calculation_version,
    calculated_at
  )
  select
    brainrot_id,
    null,

    round(market_floor_usd::numeric, 2),
    round(quick_sale_usd::numeric, 2),
    round(typical_sale_usd::numeric, 2),
    round(patient_sale_usd::numeric, 2),
    round(observed_low_usd::numeric, 2),
    round(observed_high_usd::numeric, 2),

    active_listing_count,
    completed_sale_count_90d,
    unique_seller_count,

    case confidence_label
      when 'high' then 90
      when 'medium' then 70
      when 'low' then 40
      else 0
    end,

    confidence_label,
    'v1-base-market',
    p_calculated_at

  from calculated_prices;

  get diagnostics inserted_rows = row_count;

  return inserted_rows;
end;
$$;


ALTER FUNCTION "public"."sab_refresh_price_snapshots"("p_calculated_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sab_reparse_market_listings"("p_limit" integer DEFAULT 500) RETURNS TABLE("processed_count" bigint, "matched_count" bigint, "rejected_count" bigint, "ambiguous_count" bigint, "unmatched_count" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  return query
  with targets as (
    select listing.id
    from public.sab_market_raw_listings listing
    order by listing.fetched_at desc
    limit greatest(
      1,
      least(coalesce(p_limit, 500), 5000)
    )
  ),
  reparsed as (
    update public.sab_market_raw_listings listing
    set title = listing.title
    where listing.id in (
      select target.id
      from targets target
    )
    returning listing.parse_status
  )
  select
    count(*)::bigint,
    count(*) filter (
      where parse_status = 'matched'
    )::bigint,
    count(*) filter (
      where parse_status = 'rejected'
    )::bigint,
    count(*) filter (
      where parse_status = 'ambiguous'
    )::bigint,
    count(*) filter (
      where parse_status = 'unmatched'
    )::bigint
  from reparsed;
end;
$$;


ALTER FUNCTION "public"."sab_reparse_market_listings"("p_limit" integer) OWNER TO "postgres";


