    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
begin
  new.updated_at = now();
  return new;
end;
$$;


ALTER FUNCTION "public"."sab_set_updated_at"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sab_sync_dropmarket_market_observations"("p_observed_at" timestamp with time zone DEFAULT "now"()) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_imports_enabled boolean;
  v_live_data_start_at timestamptz;

  v_listings_invalidated integer := 0;
  v_sales_invalidated integer := 0;
  v_listings_upserted integer := 0;
  v_sales_upserted integer := 0;
begin
  select
    imports_enabled,
    live_data_start_at
  into
    v_imports_enabled,
    v_live_data_start_at
  from public.sab_market_sync_config
  where id = 1;

  if coalesce(v_imports_enabled, false) = false then
    return jsonb_build_object(
      'status', 'disabled',
      'listings_invalidated', 0,
      'sales_invalidated', 0,
      'listings_upserted', 0,
      'sales_upserted', 0
    );
  end if;

  if v_live_data_start_at is null then
    raise exception
      'SAB market imports cannot run without live_data_start_at';
  end if;


  update public.sab_market_observations market_row
  set
    is_valid = false,
    rejection_reason = 'listing_no_longer_active'
  where market_row.source_name = 'dropmarket'
    and market_row.source_listing_id like 'listing:%'
    and market_row.is_valid = true
    and not exists (
      select 1
      from public.listings listing

      cross join lateral (
        select value as brainrot_slug
        from jsonb_each_text(
          coalesce(listing.template_data, '{}'::jsonb)
        )
        where key like 'select-brainrot%'
        order by key
        limit 1
      ) extracted

      join public.sab_brainrots brainrot
        on brainrot.slug = extracted.brainrot_slug
       and brainrot.is_active = true
       and brainrot.needs_review = false

      where
        'listing:' || listing.id::text =
          market_row.source_listing_id
        and listing.game_id =
          '42bab5db-5d74-4bf4-b357-997a7ed42778'
        and listing.status = 'active'
        and listing.created_at >= v_live_data_start_at
        and upper(trim(listing.currency)) = 'USD'
        and listing.price > 0
    );

  get diagnostics v_listings_invalidated = row_count;


  with eligible_listings as (
    select
      listing.id as listing_id,
      brainrot.id as brainrot_id,
      extracted.brainrot_slug,
      listing.title,
      listing.price,
      listing.currency,
      listing.status,
      listing.created_at,
      listing.updated_at,
      listing.seller_id

    from public.listings listing

    cross join lateral (
      select value as brainrot_slug
      from jsonb_each_text(
        coalesce(listing.template_data, '{}'::jsonb)
      )
      where key like 'select-brainrot%'
      order by key
      limit 1
    ) extracted

    join public.sab_brainrots brainrot
      on brainrot.slug = extracted.brainrot_slug
     and brainrot.is_active = true
     and brainrot.needs_review = false

    where listing.game_id =
      '42bab5db-5d74-4bf4-b357-997a7ed42778'
      and listing.status = 'active'
      and listing.created_at >= v_live_data_start_at
      and upper(trim(listing.currency)) = 'USD'
      and listing.price > 0
  )

  insert into public.sab_market_observations (
    brainrot_id,
    mutation_id,
    source_name,
    source_listing_id,
    source_url,
    seller_identifier_hash,
    observation_type,
    price_usd,
    quantity,
    delivery_time_minutes,
    seller_rating,
    listing_created_at,
    observed_at,
    is_valid,
    rejection_reason,
    raw_payload
  )
  select
    brainrot_id,
    null,
    'dropmarket',
    'listing:' || listing_id::text,
    null,
    md5('dropmarket:' || seller_id::text),
    'dropmarket_listing',
    price,
    1,
    null,
    null,
    created_at,
    p_observed_at,
    true,
    null,
    jsonb_build_object(
      'listing_id', listing_id,
      'title', title,
      'status', status,
      'currency', trim(currency),
      'brainrot_slug', brainrot_slug,
      'listing_updated_at', updated_at
    )
  from eligible_listings

  on conflict (source_name, source_listing_id)
  where source_listing_id is not null
  do update set
    brainrot_id = excluded.brainrot_id,
    mutation_id = null,
    seller_identifier_hash =
      excluded.seller_identifier_hash,
    observation_type = excluded.observation_type,
    price_usd = excluded.price_usd,
    quantity = excluded.quantity,
    listing_created_at = excluded.listing_created_at,
    observed_at = excluded.observed_at,
    is_valid = true,
    rejection_reason = null,
    raw_payload = excluded.raw_payload;

  get diagnostics v_listings_upserted = row_count;


  update public.sab_market_observations market_row
  set
    is_valid = false,
    rejection_reason = 'sale_no_longer_completed'
  where market_row.source_name = 'dropmarket'
    and market_row.source_listing_id like 'order:%'
    and market_row.is_valid = true
    and not exists (
      select 1
      from public.orders customer_order

      join public.listings listing
        on listing.id = customer_order.listing_id

      cross join lateral (
        select value as brainrot_slug
        from jsonb_each_text(
          coalesce(listing.template_data, '{}'::jsonb)
        )
        where key like 'select-brainrot%'
        order by key
        limit 1
      ) extracted

      join public.sab_brainrots brainrot
        on brainrot.slug = extracted.brainrot_slug
       and brainrot.is_active = true
       and brainrot.needs_review = false

      where
        'order:' || customer_order.id::text =
          market_row.source_listing_id
        and listing.game_id =
          '42bab5db-5d74-4bf4-b357-997a7ed42778'
        and customer_order.status = 'completed'
        and customer_order.completed_at is not null
        and customer_order.completed_at >=
          v_live_data_start_at
        and listing.created_at >= v_live_data_start_at
        and upper(trim(customer_order.currency)) = 'USD'
        and customer_order.quantity > 0
        and customer_order.unit_price > 0
        and customer_order.subtotal > 0
    );

  get diagnostics v_sales_invalidated = row_count;


  with eligible_sales as (
    select
      customer_order.id as order_id,
      customer_order.listing_id,
      brainrot.id as brainrot_id,
      extracted.brainrot_slug,
      customer_order.status,
      customer_order.quantity,
      customer_order.unit_price,
      customer_order.subtotal,
      customer_order.currency,
      customer_order.completed_at,
      customer_order.seller_id,
      listing.title,
      listing.created_at as listing_created_at

    from public.orders customer_order

    join public.listings listing
      on listing.id = customer_order.listing_id

    cross join lateral (
      select value as brainrot_slug
      from jsonb_each_text(
        coalesce(listing.template_data, '{}'::jsonb)
      )
      where key like 'select-brainrot%'
      order by key
      limit 1
    ) extracted

    join public.sab_brainrots brainrot
      on brainrot.slug = extracted.brainrot_slug
     and brainrot.is_active = true
     and brainrot.needs_review = false

    where listing.game_id =
      '42bab5db-5d74-4bf4-b357-997a7ed42778'
      and customer_order.status = 'completed'
      and customer_order.completed_at is not null
      and customer_order.completed_at >=
        v_live_data_start_at
      and listing.created_at >= v_live_data_start_at
      and upper(trim(customer_order.currency)) = 'USD'
      and customer_order.quantity > 0
      and customer_order.unit_price > 0
      and customer_order.subtotal > 0
  )

  insert into public.sab_market_observations (
    brainrot_id,
    mutation_id,
    source_name,
    source_listing_id,
    source_url,
    seller_identifier_hash,
    observation_type,
    price_usd,
    quantity,
    delivery_time_minutes,
    seller_rating,
    listing_created_at,
    observed_at,
    is_valid,
    rejection_reason,
    raw_payload
  )
  select
    brainrot_id,
    null,
    'dropmarket',
    'order:' || order_id::text,
    null,
    md5('dropmarket:' || seller_id::text),
    'dropmarket_sale',
    subtotal,
    quantity,
    null,
    null,
    listing_created_at,
    completed_at,
    true,
    null,
    jsonb_build_object(
      'order_id', order_id,
      'listing_id', listing_id,
      'title', title,
      'status', status,
      'currency', trim(currency),
      'brainrot_slug', brainrot_slug,
      'completed_at', completed_at,
      'recorded_unit_price', unit_price
    )
  from eligible_sales

  on conflict (source_name, source_listing_id)
  where source_listing_id is not null
  do update set
    brainrot_id = excluded.brainrot_id,
    mutation_id = null,
    seller_identifier_hash =
      excluded.seller_identifier_hash,
    observation_type = excluded.observation_type,
    price_usd = excluded.price_usd,
    quantity = excluded.quantity,
    listing_created_at = excluded.listing_created_at,
    observed_at = excluded.observed_at,
    is_valid = true,
    rejection_reason = null,
    raw_payload = excluded.raw_payload;

  get diagnostics v_sales_upserted = row_count;


  return jsonb_build_object(
    'status', 'completed',
    'live_data_start_at', v_live_data_start_at,
    'listings_invalidated', v_listings_invalidated,
    'sales_invalidated', v_sales_invalidated,
    'listings_upserted', v_listings_upserted,
    'sales_upserted', v_sales_upserted
  );
end;
$$;


ALTER FUNCTION "public"."sab_sync_dropmarket_market_observations"("p_observed_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sab_sync_ended_at"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
begin
  if new.listing_status = 'active' then
    new.ended_at := null;
  elsif new.listing_status = 'ended' and new.ended_at is null then
    new.ended_at := now();
  end if;
  return new;
end
$$;


ALTER FUNCTION "public"."sab_sync_ended_at"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."sab_sync_ended_at"() IS 'Keeps sab_market_raw_listings.ended_at consistent with listing_status on every insert/update: active => NULL, ended => stamped. Fixes zombie rows that re-activated but kept a stale ended_at.';



CREATE OR REPLACE FUNCTION "public"."safedrop_target_status"("p_event" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT CASE p_event
    WHEN 'CHARGE_CONFIRMED'         THEN 'paid'
    WHEN 'SELLER_DELIVERING'        THEN 'delivering'
    WHEN 'SELLER_DELIVERED'         THEN 'delivered'
    WHEN 'BUYER_CONFIRMED'          THEN 'completed'
    WHEN 'AUTO_RELEASED'            THEN 'completed'
    WHEN 'BUYER_DISPUTED'           THEN 'disputed'
    WHEN 'DISPUTE_RESOLVED_SELLER'  THEN 'completed'
    WHEN 'DISPUTE_RESOLVED_BUYER'   THEN 'refunded'
    WHEN 'DISPUTE_PARTIAL'          THEN 'completed'
    WHEN 'REFUNDED'                 THEN 'refunded'
    WHEN 'CANCELLED'                THEN 'cancelled'
    ELSE NULL
  END;
$$;


ALTER FUNCTION "public"."safedrop_target_status"("p_event" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."safedrop_transition"("p_order_id" "uuid", "p_event" "text", "p_dedupe_key" "text" DEFAULT NULL::"text", "p_release_method" "text" DEFAULT NULL::"text", "p_refund_minor" bigint DEFAULT NULL::bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_order        RECORD;
  v_target       TEXT;
  v_currency     CHAR(3);
  v_gross_minor  BIGINT;
  v_fee_minor    BIGINT;
  v_seller_minor BIGINT;
  v_refund_minor BIGINT;
  v_wallet_minor BIGINT;
  v_charge_minor BIGINT;
  v_idem         TEXT;
  v_txn_id       UUID;
  v_entries      JSONB;
  v_new_escrow   TEXT;
BEGIN
  v_target := safedrop_target_status(p_event);
  IF v_target IS NULL THEN
    RAISE EXCEPTION 'safedrop_transition: unknown event %', p_event USING ERRCODE = 'check_violation';
  END IF;

  -- 1. LOCK the order row for the duration of the transaction.
  SELECT * INTO v_order FROM orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'safedrop_transition: order % not found', p_order_id USING ERRCODE = 'no_data_found';
  END IF;

  -- Idempotency: already at target → no-op (money is separately idempotent).
  IF v_order.status = v_target THEN
    RETURN jsonb_build_object('order_id', p_order_id, 'status', v_target, 'changed', false);
  END IF;

  -- 2. Validate the transition (same guard the trigger enforces).
  IF NOT is_valid_order_transition(v_order.status, v_target) THEN
    RAISE EXCEPTION 'safedrop_transition: illegal % -> % (event %)', v_order.status, v_target, p_event
      USING ERRCODE = 'check_violation';
  END IF;

  -- Amounts in integer minor units (exact NUMERIC * 100).
  v_currency     := UPPER(COALESCE(v_order.currency, 'EUR'));
  v_gross_minor  := (COALESCE(v_order.total_amount, 0) * 100)::BIGINT;
  v_seller_minor := (COALESCE(v_order.seller_payout, 0) * 100)::BIGINT;
  -- Platform take at release = gross − seller payout. orders.platform_fee is
  -- only the 2% marketplace line; the gross also carries the 5% processing
  -- fee and the per-category commission (minus promo) — deriving keeps the
  -- journal balanced for every real order.
  v_fee_minor    := v_gross_minor - v_seller_minor;

  v_entries := NULL;
  v_new_escrow := v_order.escrow_status;

  IF p_event = 'CHARGE_CONFIRMED' THEN
    -- Buyer paid: provider holds the cash; we record the escrow obligation.
    -- WALLET DEDUPE: any wallet-paid portion already credited escrow_held at
    -- checkout (spendWallet, key 'checkout_wallet:<order_id>') — only the
    -- remainder was charged at the provider.
    v_new_escrow := 'held';
    SELECT COALESCE(SUM(le.amount_minor), 0) INTO v_wallet_minor
    FROM ledger_transactions lt
    JOIN ledger_entries le ON le.transaction_id = lt.id
    JOIN ledger_accounts la ON la.id = le.account_id
    WHERE lt.idempotency_key = 'checkout_wallet:' || p_order_id::text
      AND la.kind = 'escrow_held'
      AND le.direction = 'credit';

    v_charge_minor := v_gross_minor - v_wallet_minor;
    IF v_charge_minor < 0 THEN
      RAISE EXCEPTION 'safedrop_transition: wallet credit (%) exceeds gross (%) for order %',
        v_wallet_minor, v_gross_minor, p_order_id USING ERRCODE = 'check_violation';
    END IF;
    IF v_charge_minor > 0 THEN
      v_entries := jsonb_build_array(
        jsonb_build_object('owner_type','provider','owner_id',NULL,'kind','provider_float','direction','debit','amount_minor',v_charge_minor,'currency',v_currency),
        jsonb_build_object('owner_type','platform','owner_id',NULL,'kind','escrow_held','direction','credit','amount_minor',v_charge_minor,'currency',v_currency)
      );
    END IF;

  ELSIF p_event IN ('BUYER_CONFIRMED','AUTO_RELEASED','DISPUTE_RESOLVED_SELLER') THEN
    -- Release: escrow_held -> platform take + seller_available.
    v_new_escrow := 'released';
    IF v_gross_minor > 0 THEN
      -- Guard: the derived platform take must be sane (journal must balance).
      IF v_seller_minor < 0 OR v_seller_minor > v_gross_minor THEN
        RAISE EXCEPTION 'safedrop_transition: release does not balance: seller(%) outside [0, gross(%)]',
          v_seller_minor, v_gross_minor USING ERRCODE = 'check_violation';
      END IF;
      v_entries := jsonb_build_array(
        jsonb_build_object('owner_type','platform','owner_id',NULL,'kind','escrow_held','direction','debit','amount_minor',v_gross_minor,'currency',v_currency)
      );
      IF v_fee_minor > 0 THEN
        v_entries := v_entries || jsonb_build_array(
          jsonb_build_object('owner_type','platform','owner_id',NULL,'kind','platform_commission','direction','credit','amount_minor',v_fee_minor,'currency',v_currency)
        );
      END IF;
      IF v_seller_minor > 0 THEN
        v_entries := v_entries || jsonb_build_array(
          jsonb_build_object('owner_type','seller','owner_id',v_order.seller_id::text,'kind','seller_available','direction','credit','amount_minor',v_seller_minor,'currency',v_currency)
        );
      END IF;
    END IF;

  ELSIF p_event = 'DISPUTE_PARTIAL' THEN
    -- Partial dispute resolution: buyer gets p_refund_minor back (the wallet
    -- credit rides on top, keyed 'wallet_refund:<order_id>:partial:<dispute_id>'),
    -- the seller keeps their payout minus the refund (floored at 0), and the
    -- platform take is only reduced when the refund exceeds the payout.
    v_new_escrow := 'released';
    IF p_refund_minor IS NULL OR p_refund_minor <= 0 OR p_refund_minor > v_gross_minor THEN
      RAISE EXCEPTION 'safedrop_transition: DISPUTE_PARTIAL refund (%) outside (0, gross(%)] for order %',
        p_refund_minor, v_gross_minor, p_order_id USING ERRCODE = 'check_violation';
    END IF;
    IF v_seller_minor < 0 OR v_seller_minor > v_gross_minor THEN
      RAISE EXCEPTION 'safedrop_transition: release does not balance: seller(%) outside [0, gross(%)]',
        v_seller_minor, v_gross_minor USING ERRCODE = 'check_violation';
    END IF;
    v_refund_minor := p_refund_minor;
    v_seller_minor := GREATEST(0, v_seller_minor - v_refund_minor);
    v_fee_minor    := v_gross_minor - v_refund_minor - v_seller_minor;
    v_entries := jsonb_build_array(
      jsonb_build_object('owner_type','platform','owner_id',NULL,'kind','escrow_held','direction','debit','amount_minor',v_gross_minor,'currency',v_currency),
      jsonb_build_object('owner_type','platform','owner_id',NULL,'kind','refunds','direction','credit','amount_minor',v_refund_minor,'currency',v_currency)
    );
    IF v_fee_minor > 0 THEN
      v_entries := v_entries || jsonb_build_array(
        jsonb_build_object('owner_type','platform','owner_id',NULL,'kind','platform_commission','direction','credit','amount_minor',v_fee_minor,'currency',v_currency)
      );
    END IF;
    IF v_seller_minor > 0 THEN
      v_entries := v_entries || jsonb_build_array(
        jsonb_build_object('owner_type','seller','owner_id',v_order.seller_id::text,'kind','seller_available','direction','credit','amount_minor',v_seller_minor,'currency',v_currency)
      );
    END IF;

  ELSIF p_event IN ('REFUNDED','DISPUTE_RESOLVED_BUYER') THEN
    -- Refund: escrow_held -> refunds (wallet credit rides on top via
    -- wallet_credit, keyed 'wallet_refund:<order_id>').
    v_new_escrow := 'refunded';
    IF v_gross_minor > 0 THEN
      v_entries := jsonb_build_array(
        jsonb_build_object('owner_type','platform','owner_id',NULL,'kind','escrow_held','direction','debit','amount_minor',v_gross_minor,'currency',v_currency),
        jsonb_build_object('owner_type','platform','owner_id',NULL,'kind','refunds','direction','credit','amount_minor',v_gross_minor,'currency',v_currency)
      );
    END IF;

  ELSIF p_event = 'CANCELLED' THEN
    -- Cancel before release: if funds were held, return them (escrow_held -> refunds).
    IF v_order.escrow_status = 'held' AND v_gross_minor > 0 THEN
      v_new_escrow := 'refunded';
      v_entries := jsonb_build_array(
        jsonb_build_object('owner_type','platform','owner_id',NULL,'kind','escrow_held','direction','debit','amount_minor',v_gross_minor,'currency',v_currency),
        jsonb_build_object('owner_type','platform','owner_id',NULL,'kind','refunds','direction','credit','amount_minor',v_gross_minor,'currency',v_currency)
      );
    END IF;

  -- SELLER_DELIVERING / SELLER_DELIVERED / BUYER_DISPUTED: status only, no money move.
  END IF;

  -- 3. Post the ledger journal (if any) FIRST, idempotently.
  IF v_entries IS NOT NULL THEN
    v_idem := 'order:' || p_order_id::text || ':' || p_event || COALESCE(':' || p_dedupe_key, '');
    v_txn_id := post_journal(v_idem, v_entries, p_event, p_order_id);
  END IF;

  -- 3b. Release events: keep the LEGACY profiles read-model in sync in the
  -- same transaction so seller-balance displays that still read profiles
  -- stay truthful. For DISPUTE_PARTIAL the seller receives the REDUCED share
  -- (v_seller_minor after the refund came out of the payout) while the full
  -- pending amount for the order clears.
  IF p_event IN ('BUYER_CONFIRMED','AUTO_RELEASED','DISPUTE_RESOLVED_SELLER','DISPUTE_PARTIAL')
     AND COALESCE(v_order.seller_payout, 0) > 0 THEN
    UPDATE profiles
      SET seller_balance    = COALESCE(seller_balance, 0) + (v_seller_minor::NUMERIC / 100),
          pending_balance   = GREATEST(0, COALESCE(pending_balance, 0) - v_order.seller_payout),
          lifetime_earnings = COALESCE(lifetime_earnings, 0) + (v_seller_minor::NUMERIC / 100)
      WHERE id = v_order.seller_id;
  END IF;

  -- 4. Flip the order status + escrow_status (+ release_method on release).
  UPDATE orders
    SET status = v_target,
        escrow_status = v_new_escrow,
        completed_at = CASE WHEN v_target IN ('completed','refunded') THEN COALESCE(completed_at, NOW()) ELSE completed_at END,
        release_method = CASE
          WHEN p_event IN ('BUYER_CONFIRMED','AUTO_RELEASED','DISPUTE_RESOLVED_SELLER','DISPUTE_PARTIAL')
            THEN COALESCE(p_release_method, release_method)
          ELSE release_method
        END
    WHERE id = p_order_id;

  RETURN jsonb_build_object(
    'order_id', p_order_id,
    'status', v_target,
    'escrow_status', v_new_escrow,
    'ledger_txn_id', v_txn_id,
    'changed', true
  );
END;
$$;


ALTER FUNCTION "public"."safedrop_transition"("p_order_id" "uuid", "p_event" "text", "p_dedupe_key" "text", "p_release_method" "text", "p_refund_minor" bigint) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."safedrop_transition"("p_order_id" "uuid", "p_event" "text", "p_dedupe_key" "text", "p_release_method" "text", "p_refund_minor" bigint) IS 'Money layer v3: atomic order transition + internal-ledger money move. Adds DISPUTE_PARTIAL: escrow_held(gross) → refunds(p_refund_minor) + platform take + reduced seller_available, so partial dispute refunds balance. Idempotent on (order, event[, dedupe]).';



CREATE OR REPLACE FUNCTION "public"."schedule_trustpilot_invitation"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  buyer_email text;
  days_delay integer := 7; -- Send invitation 7 days after completion
BEGIN
  -- Only proceed if order status changed to completed
  IF NEW.status = 'completed' AND (OLD.status IS NULL OR OLD.status != 'completed') THEN
    -- Get buyer email
    SELECT email INTO buyer_email
    FROM public.profiles
    WHERE id = NEW.buyer_id;

    -- Create invitation record
    INSERT INTO public.trustpilot_invitations (
      buyer_id,
      order_id,
      email,
      scheduled_for
    ) VALUES (
      NEW.buyer_id,
      NEW.id,
      buyer_email,
      now() + (days_delay || ' days')::interval
    )
    ON CONFLICT (order_id) DO NOTHING; -- Don't create duplicate invitations
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."schedule_trustpilot_invitation"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."seller_available_balance"("p_seller_id" "uuid", "p_currency" character) RETURNS bigint
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
  SELECT COALESCE(SUM(CASE WHEN le.direction='credit' THEN le.amount_minor ELSE -le.amount_minor END),0)::BIGINT
  FROM ledger_entries le
  JOIN ledger_accounts la ON la.id = le.account_id
  WHERE la.owner_type='seller' AND la.owner_id = p_seller_id AND la.kind='seller_available' AND la.currency = p_currency;
$$;


ALTER FUNCTION "public"."seller_available_balance"("p_seller_id" "uuid", "p_currency" character) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."seller_available_balance"("p_seller_id" "uuid", "p_currency" character) IS 'Money layer: derived seller available balance (sum of seller_available ledger entries). The withdrawal rail draws against this.';



CREATE OR REPLACE FUNCTION "public"."seller_is_in_payout_hold"("p_seller_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_completed_orders INTEGER;
  v_account_age_days INTEGER;
BEGIN
  -- Count completed orders
  SELECT COUNT(*) INTO v_completed_orders
  FROM orders
  WHERE seller_id = p_seller_id
    AND status = 'completed';

  -- Account age in days
  SELECT EXTRACT(DAY FROM NOW() - created_at)::INTEGER INTO v_account_age_days
  FROM profiles
  WHERE id = p_seller_id;

  -- Hold if < 3 completed orders OR < 14 days old
  RETURN (v_completed_orders < 3 OR v_account_age_days < 14);
END;
$$;


ALTER FUNCTION "public"."seller_is_in_payout_hold"("p_seller_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."seller_is_in_payout_hold"("p_seller_id" "uuid") IS 'P2.1: Returns TRUE if seller should have a 14-day hold on payouts (new account protection).';



CREATE OR REPLACE FUNCTION "public"."set_chat_active_until"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
  BEGIN
    -- When order status changes to 'completed', set chat_active_until to 7 days from now
    IF NEW.status = 'completed' AND (OLD.status IS NULL OR OLD.status != 'completed') THEN
      NEW.chat_active_until := NOW() + INTERVAL '7 days';
    END IF;

    RETURN NEW;
  END;
  $$;


ALTER FUNCTION "public"."set_chat_active_until"() OWNER TO "postgres";


