    LANGUAGE "plpgsql"
    AS $$
BEGIN
  NEW.first_response_deadline = NEW.created_at + INTERVAL '48 hours';
  NEW.resolution_deadline = NEW.created_at + INTERVAL '7 days';
  RETURN NEW;
END;
$$;


