CREATE OR REPLACE FUNCTION "public"."track_seller_activity"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  -- Update seller presence when they perform actions
  IF auth.uid() IS NOT NULL THEN
    INSERT INTO public.seller_presence (seller_id, is_online, last_active_at, last_seen_at)
    VALUES (auth.uid(), true, now(), now())
    ON CONFLICT (seller_id)
    DO UPDATE SET
      is_online = true,
      last_active_at = now(),
      last_seen_at = now(),
      updated_at = now();
  END IF;
  RETURN NEW;
END;
$$;


