CREATE OR REPLACE FUNCTION "public"."update_review_edit_tracking"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  -- Only update if content changed (not seller_response)
  IF (OLD.rating IS DISTINCT FROM NEW.rating) OR
     (OLD.comment IS DISTINCT FROM NEW.comment) OR
     (OLD.title IS DISTINCT FROM NEW.title) THEN

    -- Increment edit count
    NEW.edit_count = COALESCE(OLD.edit_count, 0) + 1;

    -- Update last edited timestamp
    NEW.last_edited_at = NOW();

    -- Insert into edit history
    INSERT INTO review_edit_history (
      review_id,
      editor_id,
      old_rating,
      new_rating,
      old_comment,
      new_comment,
      old_title,
      new_title
    ) VALUES (
      NEW.id,
      auth.uid(),
      OLD.rating,
      NEW.rating,
      OLD.comment,
      NEW.comment,
      OLD.title,
      NEW.title
    );
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."update_review_edit_tracking"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."update_review_edit_tracking"() IS 'Automatically track review edits and maintain edit history';



