CREATE OR REPLACE FUNCTION "public"."upgrade_all_seller_tiers"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_seller        RECORD;
  v_new_tier      TEXT;
  v_current_order INTEGER;
  v_new_order     INTEGER;
  v_count         INTEGER := 0;
BEGIN
  FOR v_seller IN
    SELECT id, seller_tier FROM public.profiles WHERE is_seller = true
  LOOP
    v_new_tier := check_seller_tier_eligibility(v_seller.id);

    SELECT COALESCE(sort_order, 0) INTO v_current_order
    FROM public.seller_tier_config
    WHERE tier = COALESCE(v_seller.seller_tier, 'unverified');

    SELECT COALESCE(sort_order, 0) INTO v_new_order
    FROM public.seller_tier_config
    WHERE tier = v_new_tier;

    -- Only apply if it's an upgrade
    IF v_new_order > v_current_order THEN
      UPDATE public.profiles SET seller_tier = v_new_tier WHERE id = v_seller.id;
      v_count := v_count + 1;
    END IF;
  END LOOP;

  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."upgrade_all_seller_tiers"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."user_wallet_balance"("p_user_id" "uuid", "p_currency" character) RETURNS bigint
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
  SELECT COALESCE(SUM(CASE WHEN le.direction='credit' THEN le.amount_minor ELSE -le.amount_minor END),0)::BIGINT
  FROM ledger_entries le
  JOIN ledger_accounts la ON la.id = le.account_id
  WHERE la.owner_type='buyer' AND la.owner_id = p_user_id AND la.kind='user_wallet' AND la.currency = p_currency;
$$;


