COMMENT ON FUNCTION "public"."user_wallet_balance"("p_user_id" "uuid", "p_currency" character) IS 'Money layer: derived buyer wallet balance (sum of user_wallet ledger entries). The wallet is now ledger-backed; wallet_balances float table is a legacy read-model, writes locked to service_role.';



CREATE OR REPLACE FUNCTION "public"."validate_banner_update"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- If trying to set custom banner_url, check if user is premium tier
  IF NEW.banner_url IS NOT NULL AND
     NEW.banner_url IS DISTINCT FROM OLD.banner_url AND
     NEW.seller_tier NOT IN ('platinum', 'diamond') THEN
    RAISE EXCEPTION 'Custom banners are only available for Platinum and Diamond sellers';
  END IF;

  -- If downgrading from premium tier, clear custom banner
  IF OLD.seller_tier IN ('platinum', 'diamond') AND
     NEW.seller_tier NOT IN ('platinum', 'diamond') THEN
    NEW.banner_url := NULL;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."validate_banner_update"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."validate_banner_update"() IS 'Ensure only premium sellers can upload custom banners';



CREATE OR REPLACE FUNCTION "public"."validate_order_status_transition"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  BEGIN
    IF OLD.status IS NOT DISTINCT FROM NEW.status THEN
      NEW.version := OLD.version + 1;
      RETURN NEW;
    END IF;

    IF NOT is_valid_order_transition(OLD.status, NEW.status) THEN
      RAISE EXCEPTION
        'Invalid order status transition: % to %. Order ID: %',
        OLD.status, NEW.status, OLD.id
        USING ERRCODE = 'check_violation';
    END IF;

    NEW.version := OLD.version + 1;

    IF NEW.status = 'completed' AND OLD.status != 'completed' THEN
      NEW.completed_at := COALESCE(NEW.completed_at, NOW());
    END IF;

    IF NEW.status = 'cancelled' AND OLD.status != 'cancelled' THEN
      NEW.cancelled_at := COALESCE(NEW.cancelled_at, NOW());
    END IF;

    INSERT INTO audit_logs (
      action, table_name, record_id, old_data, new_data, user_id, created_at
    ) VALUES (
      'ORDER_STATUS_CHANGE', 'orders', NEW.id,
      jsonb_build_object('status', OLD.status, 'version', OLD.version),
      jsonb_build_object('status', NEW.status, 'version', NEW.version),
      auth.uid(), NOW()
    );

    RETURN NEW;
  END;
  $$;


ALTER FUNCTION "public"."validate_order_status_transition"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."validate_order_status_transition"() IS 'P2.2: Enforces escrow state machine transitions. Blocks invalid status changes at DB level. Auto-increments version.';



CREATE OR REPLACE FUNCTION "public"."wallet_credit"("p_user_id" "uuid", "p_amount_minor" bigint, "p_currency" character, "p_counterparty" "public"."ledger_account_kind", "p_idempotency_key" "text", "p_event_ref" "text" DEFAULT NULL::"text", "p_order_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
BEGIN
  IF p_amount_minor <= 0 THEN
    RAISE EXCEPTION 'wallet_credit: amount must be > 0' USING ERRCODE='check_violation';
  END IF;
  RETURN post_journal(
    p_idempotency_key,
    jsonb_build_array(
      jsonb_build_object('owner_type','platform','owner_id',NULL,'kind',p_counterparty::text,'direction','debit','amount_minor',p_amount_minor,'currency',p_currency),
      jsonb_build_object('owner_type','buyer','owner_id',p_user_id::text,'kind','user_wallet','direction','credit','amount_minor',p_amount_minor,'currency',p_currency)
    ),
    COALESCE(p_event_ref,'WALLET_CREDIT'),
    p_order_id
  );
END;
$$;


ALTER FUNCTION "public"."wallet_credit"("p_user_id" "uuid", "p_amount_minor" bigint, "p_currency" character, "p_counterparty" "public"."ledger_account_kind", "p_idempotency_key" "text", "p_event_ref" "text", "p_order_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."wallet_spend"("p_user_id" "uuid", "p_amount_minor" bigint, "p_currency" character, "p_target" "public"."ledger_account_kind", "p_idempotency_key" "text", "p_event_ref" "text" DEFAULT NULL::"text", "p_order_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_bal BIGINT;
  v_existing UUID;
BEGIN
  IF p_amount_minor <= 0 THEN
    RAISE EXCEPTION 'wallet_spend: amount must be > 0' USING ERRCODE='check_violation';
  END IF;

  -- Idempotent: if already posted, return it without re-checking balance.
  SELECT id INTO v_existing FROM ledger_transactions WHERE idempotency_key = p_idempotency_key;
  IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;

  -- Balance guard (derived).
  SELECT user_wallet_balance(p_user_id, p_currency) INTO v_bal;
  IF v_bal < p_amount_minor THEN
    RAISE EXCEPTION 'wallet_spend: insufficient wallet balance (have %, need %)', v_bal, p_amount_minor
      USING ERRCODE='check_violation';
  END IF;

  RETURN post_journal(
    p_idempotency_key,
    jsonb_build_array(
      jsonb_build_object('owner_type','buyer','owner_id',p_user_id::text,'kind','user_wallet','direction','debit','amount_minor',p_amount_minor,'currency',p_currency),
      jsonb_build_object('owner_type','platform','owner_id',NULL,'kind',p_target::text,'direction','credit','amount_minor',p_amount_minor,'currency',p_currency)
    ),
    COALESCE(p_event_ref,'WALLET_SPEND'),
    p_order_id
  );
END;
$$;


ALTER FUNCTION "public"."wallet_spend"("p_user_id" "uuid", "p_amount_minor" bigint, "p_currency" character, "p_target" "public"."ledger_account_kind", "p_idempotency_key" "text", "p_event_ref" "text", "p_order_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."webhook_event_claim"("p_provider" "text", "p_provider_event_id" "text", "p_payload_hash" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_inserted UUID;
BEGIN
  INSERT INTO webhook_events (provider, provider_event_id, payload_hash)
  VALUES (p_provider, p_provider_event_id, p_payload_hash)
  ON CONFLICT (provider, provider_event_id) DO NOTHING
  RETURNING id INTO v_inserted;

  RETURN v_inserted IS NOT NULL;  -- TRUE = freshly claimed; FALSE = duplicate
END;
$$;


ALTER FUNCTION "public"."webhook_event_claim"("p_provider" "text", "p_provider_event_id" "text", "p_payload_hash" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."webhook_event_mark"("p_provider" "text", "p_provider_event_id" "text", "p_status" "public"."webhook_event_status", "p_result" "jsonb" DEFAULT NULL::"jsonb") RETURNS "void"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
  UPDATE webhook_events
     SET status = p_status,
         result = p_result,
         processed_at = CASE WHEN p_status = 'processed' THEN NOW() ELSE processed_at END
   WHERE provider = p_provider AND provider_event_id = p_provider_event_id;
$$;


