CREATE OR REPLACE FUNCTION "public"."withdraw_seller_application"("application_id_param" "uuid", "user_id_param" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  current_withdrawal_count integer;
  result jsonb;
BEGIN
  -- Get current withdrawal count
  SELECT withdrawal_count INTO current_withdrawal_count
  FROM public.seller_applications
  WHERE id = application_id_param AND user_id = user_id_param;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Application not found or unauthorized');
  END IF;

  -- Increment withdrawal count
  current_withdrawal_count := COALESCE(current_withdrawal_count, 0) + 1;

  -- Update application
  UPDATE public.seller_applications
  SET
    status = 'withdrawn',
    withdrawn_at = now(),
    withdrawal_count = current_withdrawal_count,
    updated_at = now()
  WHERE id = application_id_param;

  -- Check for spam (5+ withdrawals in 30 days)
  result := jsonb_build_object(
    'success', true,
    'withdrawal_count', current_withdrawal_count,
    'flagged_for_spam', current_withdrawal_count >= 5
  );

  RETURN result;
END;
$$;


ALTER FUNCTION "public"."withdraw_seller_application"("application_id_param" "uuid", "user_id_param" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."withdraw_seller_application"("application_id_param" "uuid", "user_id_param" "uuid") IS 'Allows seller to withdraw application, tracks withdrawal count for anti-spam';



CREATE OR REPLACE FUNCTION "public"."withdrawal_debit"("p_user_id" "uuid", "p_amount_minor" bigint, "p_idempotency_key" "text", "p_event_ref" "text" DEFAULT 'WITHDRAWAL_HOLD'::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_existing  UUID;
  v_remaining BIGINT;
  v_take      BIGINT;
  v_bal       BIGINT;
  v_entries   JSONB := '[]'::jsonb;
  v_clearing  JSONB := '[]'::jsonb;
  v_cur       CHAR(3);
  v_cur_total BIGINT;
  r RECORD;
BEGIN
  IF p_amount_minor <= 0 THEN
    RAISE EXCEPTION 'withdrawal_debit: amount must be > 0' USING ERRCODE='check_violation';
  END IF;

  -- Idempotent: already posted → return it.
  SELECT id INTO v_existing FROM ledger_transactions WHERE idempotency_key = p_idempotency_key;
  IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;

  v_remaining := p_amount_minor;

  FOR r IN
    SELECT * FROM (VALUES
      ('EUR'::CHAR(3), 'seller_available', 'seller'),
      ('EUR'::CHAR(3), 'user_wallet',      'buyer'),
      ('USD'::CHAR(3), 'seller_available', 'seller'),
      ('USD'::CHAR(3), 'user_wallet',      'buyer')
    ) AS s(currency, kind, owner_type)
  LOOP
    EXIT WHEN v_remaining <= 0;

    IF r.kind = 'seller_available' THEN
      v_bal := seller_available_balance(p_user_id, r.currency);
    ELSE
      v_bal := user_wallet_balance(p_user_id, r.currency);
    END IF;

    v_take := LEAST(v_bal, v_remaining);
    IF v_take > 0 THEN
      v_entries := v_entries || jsonb_build_array(
        jsonb_build_object('owner_type', r.owner_type, 'owner_id', p_user_id::text, 'kind', r.kind, 'direction', 'debit', 'amount_minor', v_take, 'currency', r.currency)
      );
      v_remaining := v_remaining - v_take;
    END IF;
  END LOOP;

  IF v_remaining > 0 THEN
    RAISE EXCEPTION 'withdrawal_debit: insufficient balance (short % minor units)', v_remaining
      USING ERRCODE='check_violation';
  END IF;

  -- Balance each currency with a payout_clearing credit.
  FOR v_cur, v_cur_total IN
    SELECT (e->>'currency')::CHAR(3), SUM((e->>'amount_minor')::BIGINT)
    FROM jsonb_array_elements(v_entries) e
    GROUP BY (e->>'currency')::CHAR(3)
  LOOP
    v_clearing := v_clearing || jsonb_build_array(
      jsonb_build_object('owner_type','platform','owner_id',NULL,'kind','payout_clearing','direction','credit','amount_minor',v_cur_total,'currency',v_cur)
    );
  END LOOP;

  RETURN post_journal(p_idempotency_key, v_entries || v_clearing, p_event_ref, NULL);
END;
$$;


ALTER FUNCTION "public"."withdrawal_debit"("p_user_id" "uuid", "p_amount_minor" bigint, "p_idempotency_key" "text", "p_event_ref" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."withdrawal_debit"("p_user_id" "uuid", "p_amount_minor" bigint, "p_idempotency_key" "text", "p_event_ref" "text") IS 'Money layer: holds withdrawal funds (seller_available/user_wallet → payout_clearing) at request creation, idempotent on the key. Prevents double-spending a pending withdrawal at checkout.';



CREATE OR REPLACE FUNCTION "public"."withdrawal_reversal"("p_request_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_hold_txn UUID;
  v_existing UUID;
  v_entries  JSONB := '[]'::jsonb;
  r RECORD;
BEGIN
  SELECT id INTO v_existing FROM ledger_transactions
  WHERE idempotency_key = 'withdrawal_reversal:' || p_request_id::text;
  IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;

  SELECT id INTO v_hold_txn FROM ledger_transactions
  WHERE idempotency_key = 'withdrawal:' || p_request_id::text;
  IF v_hold_txn IS NULL THEN RETURN NULL; END IF;

  FOR r IN
    SELECT la.owner_type, la.owner_id, la.kind, la.currency, le.direction, le.amount_minor
    FROM ledger_entries le
    JOIN ledger_accounts la ON la.id = le.account_id
    WHERE le.transaction_id = v_hold_txn
  LOOP
    v_entries := v_entries || jsonb_build_array(
      jsonb_build_object(
        'owner_type', r.owner_type,
        'owner_id',   r.owner_id,
        'kind',       r.kind,
        'direction',  CASE WHEN r.direction = 'debit' THEN 'credit' ELSE 'debit' END,
        'amount_minor', r.amount_minor,
        'currency',   r.currency
      )
    );
  END LOOP;

  RETURN post_journal('withdrawal_reversal:' || p_request_id::text, v_entries, 'WITHDRAWAL_REVERSED', NULL);
END;
$$;


ALTER FUNCTION "public"."withdrawal_reversal"("p_request_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."withdrawal_reversal"("p_request_id" "uuid") IS 'Money layer: exact mirror of a withdrawal hold journal (payout_clearing → original sources) on reject/cancel. Idempotent per request.';



