    "shop_slug" "text",
    "shop_name_updated_at" timestamp with time zone,
    "positive_reviews" integer DEFAULT 0,
    "banner_url" "text",
    "banner_preset" "text" DEFAULT 'gaming-purple'::"text",
    "inform_status" "text" DEFAULT 'not_required'::"text",
    "referral_code" "text",
    "referred_by" "uuid",
    "loyalty_balance" numeric(10,2) DEFAULT 0 NOT NULL,
    "lifetime_cashback_earned" numeric(10,2) DEFAULT 0 NOT NULL,
    "stripe_connect_account_id" "text",
    "stripe_connect_status" "text" DEFAULT 'not_connected'::"text",
    "stripe_connect_charges_enabled" boolean DEFAULT false,
    "stripe_connect_payouts_enabled" boolean DEFAULT false,
    "stripe_connect_onboarding_url" "text",
    "stripe_connect_connected_at" timestamp with time zone,
    "seller_balance" numeric(12,2) DEFAULT 0.00 NOT NULL,
    "pending_balance" numeric(12,2) DEFAULT 0.00 NOT NULL,
    "lifetime_earnings" numeric(12,2) DEFAULT 0.00 NOT NULL,
    "is_verified" boolean DEFAULT false NOT NULL,
    "is_guest" boolean DEFAULT false,
    "seller_status" "text" DEFAULT 'active'::"text",
    "seller_restriction_reason" "text",
    "seller_restricted_at" timestamp with time zone,
    "seller_restricted_by" "uuid",
    "is_test" boolean DEFAULT false NOT NULL,
    "founding_seller" boolean DEFAULT false NOT NULL,
    CONSTRAINT "banner_url_format" CHECK ((("banner_url" IS NULL) OR ("banner_url" ~* '^https?://.*\.(jpg|jpeg|png|webp|gif)(\?.*)?$'::"text") OR ("banner_url" ~~ 'storage/seller-banners/%'::"text"))),
    CONSTRAINT "paypal_email_format" CHECK ((("paypal_email" IS NULL) OR ("paypal_email" ~* '^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}$'::"text"))),
    CONSTRAINT "profiles_inform_status_check" CHECK (("inform_status" = ANY (ARRAY['not_required'::"text", 'required'::"text", 'submitted'::"text", 'certified'::"text", 'rejected'::"text"]))),
    CONSTRAINT "profiles_kyc_status_check" CHECK ((("kyc_status" IS NULL) OR ("kyc_status" = ANY (ARRAY['pending'::"text", 'approved'::"text", 'rejected'::"text"])))),
    CONSTRAINT "profiles_loyalty_balance_check" CHECK (("loyalty_balance" >= (0)::numeric)),
    CONSTRAINT "profiles_role_check" CHECK (("role" = ANY (ARRAY['user'::"text", 'seller'::"text", 'admin'::"text", 'moderator'::"text", 'support'::"text", 'super_admin'::"text"]))),
    CONSTRAINT "profiles_seller_rating_check" CHECK ((("seller_rating" >= (0)::numeric) AND ("seller_rating" <= (5)::numeric))),
    CONSTRAINT "profiles_seller_status_check" CHECK (("seller_status" = ANY (ARRAY['active'::"text", 'restricted'::"text", 'banned'::"text"]))),
    CONSTRAINT "profiles_seller_tier_check" CHECK (("seller_tier" = ANY (ARRAY['unverified'::"text", 'bronze'::"text", 'silver'::"text", 'gold'::"text", 'platinum'::"text", 'diamond'::"text"]))),
    CONSTRAINT "profiles_shop_layout_check" CHECK ((("shop_layout")::"text" = ANY ((ARRAY['grid'::character varying, 'list'::character varying, 'masonry'::character varying])::"text"[]))),
    CONSTRAINT "profiles_shop_theme_check" CHECK ((("shop_theme")::"text" = ANY ((ARRAY['default'::character varying, 'dark'::character varying, 'light'::character varying, 'custom'::character varying])::"text"[]))),
    CONSTRAINT "profiles_stripe_connect_status_check" CHECK (("stripe_connect_status" = ANY (ARRAY['not_connected'::"text", 'pending'::"text", 'restricted'::"text", 'active'::"text", 'disabled'::"text"]))),
    CONSTRAINT "shop_name_length" CHECK ((("shop_name" IS NULL) OR (("length"("shop_name") >= 3) AND ("length"("shop_name") <= 50)))),
    CONSTRAINT "shop_slug_format" CHECK ((("shop_slug" IS NULL) OR ("shop_slug" ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$'::"text"))),
    CONSTRAINT "shop_slug_length" CHECK ((("shop_slug" IS NULL) OR (("length"("shop_slug") >= 3) AND ("length"("shop_slug") <= 50)))),
    CONSTRAINT "username_length" CHECK ((("char_length"("username") >= 3) AND ("char_length"("username") <= 30)))
);

ALTER TABLE ONLY "public"."profiles" REPLICA IDENTITY FULL;


ALTER TABLE "public"."profiles" OWNER TO "postgres";


COMMENT ON TABLE "public"."profiles" IS 'User profiles with seller capabilities';



COMMENT ON COLUMN "public"."profiles"."seller_tier" IS 'Seller tier level (determines banner customization privileges)';



COMMENT ON COLUMN "public"."profiles"."role" IS 'User role in the system: user, seller, admin, moderator, support, super_admin';



COMMENT ON COLUMN "public"."profiles"."badges" IS 'Visual badges for user profiles: verified, support, moderator, admin, developer';



COMMENT ON COLUMN "public"."profiles"."email" IS 'User email synced from auth.users';



COMMENT ON COLUMN "public"."profiles"."shop_primary_color" IS 'Primary brand color for seller shop (hex format)';



COMMENT ON COLUMN "public"."profiles"."shop_secondary_color" IS 'Secondary brand color for seller shop (hex format)';



COMMENT ON COLUMN "public"."profiles"."shop_banner_url" IS 'URL to custom shop banner image';



COMMENT ON COLUMN "public"."profiles"."shop_banner_position" IS 'Banner image position (center, top, bottom)';



COMMENT ON COLUMN "public"."profiles"."shop_custom_css" IS 'Custom CSS for advanced shop customization';



COMMENT ON COLUMN "public"."profiles"."shop_theme" IS 'Shop theme selection (default, dark, light, custom)';



COMMENT ON COLUMN "public"."profiles"."shop_layout" IS 'Default shop listing layout (grid, list, masonry)';



COMMENT ON COLUMN "public"."profiles"."shop_name" IS 'Display name for seller shop (e.g., "Legendary Gaming")';



COMMENT ON COLUMN "public"."profiles"."shop_slug" IS 'URL-safe slug for seller shop (e.g., "legendary-gaming")';



COMMENT ON COLUMN "public"."profiles"."shop_name_updated_at" IS 'Timestamp of last shop name change (NULL = never changed, allows first-time setup)';



COMMENT ON COLUMN "public"."profiles"."banner_url" IS 'Custom banner image URL (premium sellers only)';



COMMENT ON COLUMN "public"."profiles"."banner_preset" IS 'Preset gradient theme for banner (non-premium sellers)';



COMMENT ON COLUMN "public"."profiles"."stripe_connect_account_id" IS 'Stripe Connect Express account ID (acct_...). NULL if not connected.';



COMMENT ON COLUMN "public"."profiles"."stripe_connect_status" IS 'Connect account status: not_connected|pending|restricted|active|disabled';



COMMENT ON COLUMN "public"."profiles"."seller_balance" IS 'Available balance for withdrawal. Incremented when escrow is released.';



COMMENT ON COLUMN "public"."profiles"."pending_balance" IS 'Funds held in escrow (paid orders not yet completed).';



COMMENT ON COLUMN "public"."profiles"."lifetime_earnings" IS 'Total lifetime seller earnings (all-time released escrow). Never decremented.';



COMMENT ON COLUMN "public"."profiles"."is_verified" IS 'Whether this user has completed identity verification. Managed by admins only.';



COMMENT ON COLUMN "public"."profiles"."is_guest" IS 'TRUE if this account was created via guest checkout and user has not claimed it';



COMMENT ON COLUMN "public"."profiles"."seller_status" IS 'Current seller status: active (normal), restricted (cannot create/publish listings), banned (no seller access)';



COMMENT ON COLUMN "public"."profiles"."seller_restriction_reason" IS 'Admin reason for restriction/ban';



COMMENT ON COLUMN "public"."profiles"."seller_restricted_at" IS 'Timestamp when restriction was applied';



COMMENT ON COLUMN "public"."profiles"."seller_restricted_by" IS 'Admin user ID who applied the restriction';



COMMENT ON COLUMN "public"."profiles"."founding_seller" IS 'When true, this seller is a founding seller: they pay a permanently reduced commission (per-category rate minus FOUNDING_DISCOUNT_PTS, floored at 0 — src/lib/fees) and show a founding-seller badge. Granted manually by an admin via admin/active-sellers. Locked to the account for life.';



CREATE TABLE IF NOT EXISTS "public"."review_edit_history" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "review_id" "uuid" NOT NULL,
    "editor_id" "uuid" NOT NULL,
    "old_rating" integer,
    "new_rating" integer,
    "old_comment" "text",
    "new_comment" "text",
    "old_title" "text",
    "new_title" "text",
    "edited_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "edit_reason" "text",
    "ip_address" "inet",
    "user_agent" "text",
    CONSTRAINT "rating_valid" CHECK (((("old_rating" IS NULL) OR (("old_rating" >= 1) AND ("old_rating" <= 5))) AND (("new_rating" IS NULL) OR (("new_rating" >= 1) AND ("new_rating" <= 5)))))
);


ALTER TABLE "public"."review_edit_history" OWNER TO "postgres";


COMMENT ON TABLE "public"."review_edit_history" IS 'Audit trail of all review edits for moderation and transparency';



CREATE TABLE IF NOT EXISTS "public"."reviews" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "order_id" "uuid" NOT NULL,
    "reviewer_id" "uuid" NOT NULL,
    "seller_id" "uuid" NOT NULL,
    "listing_id" "uuid" NOT NULL,
    "game_id" "uuid",
    "rating" integer NOT NULL,
    "title" "text",
    "comment" "text" NOT NULL,
    "is_positive" boolean GENERATED ALWAYS AS (("rating" >= 4)) STORED,
    "seller_response" "text",
    "seller_responded_at" timestamp with time zone,
    "is_verified_purchase" boolean DEFAULT true,
    "is_visible" boolean DEFAULT true,
    "flagged_for_moderation" boolean DEFAULT false,
    "moderation_reason" "text",
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "edit_count" integer DEFAULT 0,
    "last_edited_at" timestamp with time zone,
    CONSTRAINT "review_comment_length" CHECK ((("char_length"("comment") >= 10) AND ("char_length"("comment") <= 2000))),
    CONSTRAINT "review_edit_count_positive" CHECK (("edit_count" >= 0)),
    CONSTRAINT "review_title_length" CHECK (("char_length"("title") <= 100)),
    CONSTRAINT "reviews_rating_check" CHECK ((("rating" >= 1) AND ("rating" <= 5))),
    CONSTRAINT "seller_response_length" CHECK (("char_length"("seller_response") <= 500))
);


ALTER TABLE "public"."reviews" OWNER TO "postgres";


COMMENT ON TABLE "public"."reviews" IS 'Customer reviews for completed orders';



COMMENT ON COLUMN "public"."reviews"."order_id" IS 'One review per order - enforced by UNIQUE constraint';



COMMENT ON COLUMN "public"."reviews"."is_positive" IS 'Auto-calculated: true if rating >= 4';



COMMENT ON COLUMN "public"."reviews"."is_verified_purchase" IS 'Always true for order-based reviews';



COMMENT ON COLUMN "public"."reviews"."flagged_for_moderation" IS 'Admin moderation flag';



COMMENT ON COLUMN "public"."reviews"."edit_count" IS 'Number of times this review has been edited';



COMMENT ON COLUMN "public"."reviews"."last_edited_at" IS 'Timestamp of the most recent edit';



CREATE OR REPLACE VIEW "public"."admin_review_overview" AS
 SELECT "r"."id",
    "r"."order_id",
    "r"."rating",
    "r"."comment",
    "r"."title",
    "r"."is_positive",
    "r"."is_visible",
    "r"."flagged_for_moderation",
    "r"."moderation_reason",
    "r"."edit_count",
    "r"."last_edited_at",
    "r"."created_at",
    "r"."updated_at",
    "reviewer"."id" AS "reviewer_id",
    "reviewer"."username" AS "reviewer_username",
    "reviewer"."email" AS "reviewer_email",
    "seller"."id" AS "seller_id",
    "seller"."username" AS "seller_username",
    "seller"."shop_name" AS "seller_shop_name",
    "l"."title" AS "listing_title",
    "g"."name" AS "game_name",
    ( SELECT "count"(*) AS "count"
           FROM "public"."review_edit_history"
          WHERE ("review_edit_history"."review_id" = "r"."id")) AS "total_edits",
        CASE
            WHEN ("r"."seller_response" IS NOT NULL) THEN true
            ELSE false
        END AS "has_seller_response"
   FROM (((("public"."reviews" "r"
     LEFT JOIN "public"."profiles" "reviewer" ON (("r"."reviewer_id" = "reviewer"."id")))
     LEFT JOIN "public"."profiles" "seller" ON (("r"."seller_id" = "seller"."id")))
     LEFT JOIN "public"."listings" "l" ON (("r"."listing_id" = "l"."id")))
     LEFT JOIN "public"."games" "g" ON (("r"."game_id" = "g"."id")))
  ORDER BY "r"."created_at" DESC;


ALTER VIEW "public"."admin_review_overview" OWNER TO "postgres";


COMMENT ON VIEW "public"."admin_review_overview" IS 'Comprehensive view of all reviews with related data for admin management';



