);


ALTER TABLE "public"."admin_roles" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."adopt_me_market_raw_listings" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
