    CONSTRAINT "adopt_me_market_raw_listings_variant_check" CHECK (("variant" = ANY (ARRAY['N'::"text", 'F'::"text", 'R'::"text", 'FR'::"text", 'NEON'::"text", 'NFR'::"text", 'MEGA'::"text", 'MFR'::"text"])))
);


ALTER TABLE "public"."adopt_me_market_raw_listings" OWNER TO "postgres";


COMMENT ON TABLE "public"."adopt_me_market_raw_listings" IS 'Raw Adopt Me marketplace listings (one row per offer). Input to the unified correct-prices cron, which computes reputable cheapest/average from the 100+ review sellers here. Service-role only — never shown raw to users.';



CREATE TABLE IF NOT EXISTS "public"."adopt_me_pet_values" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "pet_id" "uuid" NOT NULL,
    "variant" "text" NOT NULL,
    "cash_value_usd" numeric(10,2),
    "trade_value" numeric,
    "listings_tracked" integer DEFAULT 0 NOT NULL,
    "confidence" "text" DEFAULT 'low'::"text" NOT NULL,
    "is_estimated" boolean DEFAULT true NOT NULL,
    "price_change_7d" numeric,
    "last_priced_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "cheapest_usd" numeric(10,2),
    "average_usd" numeric(10,2),
    "reputable_count" integer,
    CONSTRAINT "adopt_me_pet_values_confidence_check" CHECK (("confidence" = ANY (ARRAY['highly_accurate'::"text", 'high'::"text", 'medium'::"text", 'low'::"text"]))),
    CONSTRAINT "adopt_me_pet_values_variant_check" CHECK (("variant" = ANY (ARRAY['N'::"text", 'F'::"text", 'R'::"text", 'FR'::"text", 'NEON'::"text", 'NFR'::"text", 'MEGA'::"text", 'MFR'::"text"])))
);


ALTER TABLE "public"."adopt_me_pet_values" OWNER TO "postgres";


COMMENT ON TABLE "public"."adopt_me_pet_values" IS 'One row per Adopt Me pet per variant (N..MFR). Dual-axis: cash_value_usd (DropMarket USD) + trade_value (community points). is_estimated flags derived vs observed; all rows start estimated until real sales exist.';



COMMENT ON COLUMN "public"."adopt_me_pet_values"."cheapest_usd" IS 'Lowest price a reputable (100+ review) seller offers, cluster-supported. NULL when there is no reputable evidence — never a fabricated floor.';



COMMENT ON COLUMN "public"."adopt_me_pet_values"."average_usd" IS 'Typical reputable price (median of the cheapest reputable listings, spread-capped). The headline "market price" shown to buyers.';



COMMENT ON COLUMN "public"."adopt_me_pet_values"."reputable_count" IS 'How many reputable listings backed cheapest/average this run (transparency).';



CREATE TABLE IF NOT EXISTS "public"."adopt_me_pets" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "slug" "text" NOT NULL,
    "name" "text" NOT NULL,
    "rarity" "text" NOT NULL,
    "obtainability" "text" DEFAULT 'obtainable'::"text" NOT NULL,
    "origin_type" "text",
    "origin_detail" "text",
    "released_at" "date",
    "retired_at" "date",
    "image_url" "text",
    "demand_rank" integer,
    "demand_trend" "text" DEFAULT 'stable'::"text",
    "description" "text",
    "is_active" boolean DEFAULT false NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "has_page" boolean GENERATED ALWAYS AS ((("is_active" = true) AND ("description" IS NOT NULL) AND ("length"("btrim"("description")) >= 200))) STORED,
    CONSTRAINT "adopt_me_pets_demand_trend_check" CHECK (("demand_trend" = ANY (ARRAY['rising'::"text", 'stable'::"text", 'falling'::"text"]))),
    CONSTRAINT "adopt_me_pets_obtainability_check" CHECK (("obtainability" = ANY (ARRAY['obtainable'::"text", 'limited'::"text", 'unobtainable'::"text"]))),
    CONSTRAINT "adopt_me_pets_origin_type_check" CHECK ((("origin_type" IS NULL) OR ("origin_type" = ANY (ARRAY['egg'::"text", 'event'::"text", 'shop'::"text", 'robux'::"text", 'gamepass'::"text", 'minigame'::"text", 'promo'::"text"])))),
    CONSTRAINT "adopt_me_pets_rarity_check" CHECK (("rarity" = ANY (ARRAY['common'::"text", 'uncommon'::"text", 'rare'::"text", 'ultra_rare'::"text", 'legendary'::"text"])))
);


ALTER TABLE "public"."adopt_me_pets" OWNER TO "postgres";


COMMENT ON TABLE "public"."adopt_me_pets" IS 'Adopt Me tradable pets (variant-agnostic). One page per row at /adopt-me/values/{slug}. is_active requires both a price and a description.';



COMMENT ON COLUMN "public"."adopt_me_pets"."has_page" IS 'Generated: true only when the pet is active AND carries a substantive description. Gates the /adopt-me/values/{slug} route so no thin page ships. The value LIST uses is_active alone.';



