CREATE OR REPLACE VIEW "public"."disputes_with_users" AS
 SELECT "d"."id",
    "d"."transaction_id",
    "d"."order_reference",
    "d"."buyer_id",
    "d"."seller_id",
    "d"."reason",
    "d"."title",
    "d"."description",
    "d"."evidence_urls",
    "d"."disputed_amount",
    "d"."resolved_amount",
    "d"."currency",
    "d"."status",
    "d"."priority",
    "d"."assigned_to",
    "d"."assigned_at",
    "d"."resolution_type",
    "d"."resolution_notes",
    "d"."resolved_by",
    "d"."resolved_at",
    "d"."escalated_at",
    "d"."escalated_by",
    "d"."escalation_reason",
    "d"."first_response_at",
    "d"."first_response_deadline",
    "d"."resolution_deadline",
    "d"."created_at",
    "d"."updated_at",
    "bp"."username" AS "buyer_username",
    "bp"."full_name" AS "buyer_name",
    "bp"."avatar_url" AS "buyer_avatar",
    "bp"."email" AS "buyer_email",
    "sp"."username" AS "seller_username",
    "sp"."full_name" AS "seller_name",
    "sp"."avatar_url" AS "seller_avatar",
    "sp"."email" AS "seller_email",
    "ap"."username" AS "assigned_admin_username",
    "ap"."full_name" AS "assigned_admin_name",
    ( SELECT "count"(*) AS "count"
           FROM "public"."dispute_messages" "dm"
          WHERE ("dm"."dispute_id" = "d"."id")) AS "message_count",
    ( SELECT "count"(*) AS "count"
           FROM "public"."dispute_messages" "dm"
          WHERE (("dm"."dispute_id" = "d"."id") AND ("dm"."is_internal" = false))) AS "public_message_count"
   FROM ((("public"."disputes" "d"
     JOIN "public"."profiles" "bp" ON (("d"."buyer_id" = "bp"."id")))
     JOIN "public"."profiles" "sp" ON (("d"."seller_id" = "sp"."id")))
     LEFT JOIN "public"."profiles" "ap" ON (("d"."assigned_to" = "ap"."id")));


ALTER VIEW "public"."disputes_with_users" OWNER TO "postgres";


