CREATE OR REPLACE VIEW "public"."failed_operations" AS
 SELECT "id",
    "created_at",
    "action",
    "table_name",
    "user_email",
    "error_message",
    "request_path",
    "count"(*) OVER (PARTITION BY "user_id", "action" ORDER BY "created_at" RANGE BETWEEN '01:00:00'::interval PRECEDING AND CURRENT ROW) AS "failures_last_hour"
   FROM "public"."audit_logs" "al"
  WHERE (("success" = false) AND ("created_at" >= ("now"() - '7 days'::interval)))
  ORDER BY "created_at" DESC;


ALTER VIEW "public"."failed_operations" OWNER TO "postgres";


COMMENT ON VIEW "public"."failed_operations" IS 'Failed operations in last 7 days with failure rate per user';



