COMMENT ON TABLE "public"."messages" IS 'Messages within conversations';



CREATE OR REPLACE VIEW "public"."moderation_queue" AS
 SELECT "l"."id",
    "l"."seller_id",
    "l"."game_id",
    "l"."category_id",
    "l"."title",
    "l"."description",
    "l"."price",
    "l"."original_price",
    "l"."quantity",
    "l"."min_quantity",
    "l"."delivery_method",
    "l"."delivery_time",
    "l"."delivery_method_type",
    "l"."images",
    "l"."template_data",
    "l"."region",
    "l"."platform",
    "l"."status",
    "l"."currency",
    "l"."views",
    "l"."sales",
    "l"."created_at",
    "l"."updated_at",
    "l"."approved_at",
    "l"."approved_by",
    "l"."rejection_reason",
    "p"."username" AS "seller_username",
    "p"."email" AS "seller_email",
    "p"."seller_tier",
    "p"."total_sales" AS "seller_total_sales",
    "p"."seller_rating",
    "g"."name" AS "game_name",
    "g"."slug" AS "game_slug",
    "c"."name" AS "category_name",
    "c"."slug" AS "category_slug",
    ( SELECT "count"(*) AS "count"
           FROM "public"."listings" "l2"
          WHERE (("l2"."seller_id" = "l"."seller_id") AND ("l2"."status" = ANY (ARRAY['active'::"text", 'sold'::"text", 'archived'::"text"])) AND ("l2"."approved_at" IS NOT NULL))) AS "seller_approved_listings_count"
   FROM ((("public"."listings" "l"
     JOIN "public"."profiles" "p" ON (("l"."seller_id" = "p"."id")))
     JOIN "public"."games" "g" ON (("l"."game_id" = "g"."id")))
     JOIN "public"."categories" "c" ON (("l"."category_id" = "c"."id")))
  WHERE ("l"."status" = 'pending_approval'::"text")
  ORDER BY "l"."created_at";


ALTER VIEW "public"."moderation_queue" OWNER TO "postgres";


