COMMENT ON COLUMN "public"."order_cancellation_requests"."reason" IS 'Buyer''s reason for requesting cancellation';



COMMENT ON COLUMN "public"."order_cancellation_requests"."status" IS 'Request status: pending (awaiting admin review), approved (admin accepted, order cancelled), rejected (admin denied)';



COMMENT ON COLUMN "public"."order_cancellation_requests"."admin_notes" IS 'Optional notes from admin explaining approval/rejection decision';



CREATE TABLE IF NOT EXISTS "public"."payouts" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "seller_id" "uuid" NOT NULL,
