    "currency" "text" DEFAULT 'usd'::"text" NOT NULL,
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "order_id" "uuid",
    "initiated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "completed_at" timestamp with time zone,
    "failed_at" timestamp with time zone,
    "failure_reason" "text",
    "hold_until" timestamp with time zone,
    "is_held" boolean DEFAULT false NOT NULL,
    "notes" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "payouts_amount_check" CHECK (("amount" > (0)::numeric)),
    CONSTRAINT "payouts_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'processing'::"text", 'paid'::"text", 'failed'::"text", 'cancelled'::"text"])))
);


ALTER TABLE "public"."payouts" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."processed_operations" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "idempotency_key" "text" NOT NULL,
    "operation_type" "text" NOT NULL,
    "user_id" "uuid",
    "response_status" integer DEFAULT 200 NOT NULL,
    "response_body" "jsonb",
    "related_order_id" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "expires_at" timestamp with time zone DEFAULT ("now"() + '24:00:00'::interval) NOT NULL
);


ALTER TABLE "public"."processed_operations" OWNER TO "postgres";


COMMENT ON TABLE "public"."processed_operations" IS 'P2.3: Idempotency store. Prevents duplicate payment operations. Keys expire after 24h.';



COMMENT ON COLUMN "public"."processed_operations"."idempotency_key" IS 'UUID generated by the client before initiating a payment. Must be unique per operation_type.';



COMMENT ON COLUMN "public"."processed_operations"."response_body" IS 'Cached response returned to duplicate requests (same idempotency_key + operation_type).';



