CREATE OR REPLACE VIEW "public"."recent_security_events" AS
 SELECT "al"."id",
    "al"."created_at",
    "al"."action",
    "al"."table_name",
    "al"."user_email",
    "al"."user_role",
    "al"."ip_address",
    "al"."success",
    "al"."error_message",
    "p"."username" AS "user_name",
    "p"."seller_tier"
   FROM ("public"."audit_logs" "al"
     LEFT JOIN "public"."profiles" "p" ON (("p"."id" = "al"."user_id")))
  WHERE (("al"."created_at" >= ("now"() - '24:00:00'::interval)) AND (("al"."action")::"text" = ANY ((ARRAY['login_failed'::character varying, 'unauthorized_access'::character varying, 'listing_deleted'::character varying, 'order_created'::character varying, 'order_status_changed'::character varying, 'user_role_changed'::character varying, 'admin_action'::character varying])::"text"[])))
  ORDER BY "al"."created_at" DESC
 LIMIT 1000;


ALTER VIEW "public"."recent_security_events" OWNER TO "postgres";


COMMENT ON VIEW "public"."recent_security_events" IS 'Last 24 hours of security-relevant events for monitoring dashboard';



