    "needs_review" boolean DEFAULT true NOT NULL,
    "is_active" boolean DEFAULT true NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "popularity_rank" integer,
    "is_tradeable" boolean DEFAULT true NOT NULL,
    CONSTRAINT "sab_brainrots_image_status_check" CHECK (("image_status" = ANY (ARRAY['missing'::"text", 'pending'::"text", 'approved'::"text", 'rejected'::"text"]))),
    CONSTRAINT "sab_brainrots_obtainability_check" CHECK (("obtainability" = ANY (ARRAY['obtainable'::"text", 'limited'::"text", 'unobtainable'::"text", 'unknown'::"text"])))
);


