COMMENT ON TABLE "public"."sab_brainrots" IS 'Canonical Steal a Brainrot catalog imported from reviewed sources.';



COMMENT ON COLUMN "public"."sab_brainrots"."is_tradeable" IS 'TRUE = worth crawling (has reputable/trusted sales, or is in Eldorado''s popular feed). Recomputed nightly by the correction cron. The collector crawls only is_tradeable=true.';



CREATE OR REPLACE VIEW "public"."sab_brainrot_catalog" WITH ("security_invoker"='true') AS
 SELECT "id",
    "name",
    "slug",
    "rarity",
    "obtainability",
    "base_income_per_second",
    "ingame_cost",
    "image_path",
    ("name" || ' Steal a Brainrot'::"text") AS "image_alt",
    ('https://cserfvellsliylifjkos.supabase.co/storage/v1/object/public/sab-brainrots/'::"text" || "image_path") AS "image_url",
    "source_url",
    "updated_at"
   FROM "public"."sab_brainrots" "b"
  WHERE (("is_active" = true) AND ("needs_review" = false) AND ("image_status" = 'approved'::"text"));


ALTER VIEW "public"."sab_brainrot_catalog" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."sab_price_snapshots" (
    "id" bigint NOT NULL,
    "brainrot_id" "uuid" NOT NULL,
    "mutation_id" "uuid",
    "market_floor_usd" numeric(12,2),
    "quick_sale_usd" numeric(12,2),
    "typical_sale_usd" numeric(12,2),
    "patient_sale_usd" numeric(12,2),
    "observed_low_usd" numeric(12,2),
    "observed_high_usd" numeric(12,2),
    "active_listing_count" integer DEFAULT 0 NOT NULL,
    "completed_sale_count" integer DEFAULT 0 NOT NULL,
    "unique_seller_count" integer DEFAULT 0 NOT NULL,
    "confidence_score" numeric(5,2),
    "confidence_label" "text" DEFAULT 'insufficient'::"text" NOT NULL,
    "calculation_version" "text" DEFAULT 'v1'::"text" NOT NULL,
    "calculated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "sab_price_snapshots_confidence_label_check" CHECK (("confidence_label" = ANY (ARRAY['high'::"text", 'medium'::"text", 'low'::"text", 'insufficient'::"text"])))
);


ALTER TABLE "public"."sab_price_snapshots" OWNER TO "postgres";


COMMENT ON TABLE "public"."sab_price_snapshots" IS 'Calculated historical values used by value pages and price charts.';



CREATE OR REPLACE VIEW "public"."sab_latest_price_snapshots" WITH ("security_invoker"='true') AS
 WITH "ranked_snapshots" AS (
         SELECT "s"."id",
            "s"."brainrot_id",
            "s"."mutation_id",
            "s"."market_floor_usd",
            "s"."quick_sale_usd",
            "s"."typical_sale_usd",
            "s"."patient_sale_usd",
            "s"."observed_low_usd",
            "s"."observed_high_usd",
            "s"."active_listing_count",
            "s"."completed_sale_count",
            "s"."unique_seller_count",
            "s"."confidence_score",
            "s"."confidence_label",
            "s"."calculation_version",
            "s"."calculated_at",
            "row_number"() OVER (PARTITION BY "s"."brainrot_id", "s"."mutation_id" ORDER BY "s"."calculated_at" DESC, "s"."id" DESC) AS "snapshot_rank"
           FROM "public"."sab_price_snapshots" "s"
        )
 SELECT "id",
    "brainrot_id",
    "mutation_id",
    "market_floor_usd",
    "quick_sale_usd",
    "typical_sale_usd",
    "patient_sale_usd",
    "observed_low_usd",
    "observed_high_usd",
    "active_listing_count",
    "completed_sale_count",
    "unique_seller_count",
    "confidence_score",
    "confidence_label",
    "calculation_version",
    "calculated_at"
   FROM "ranked_snapshots"
  WHERE ("snapshot_rank" = 1);


ALTER VIEW "public"."sab_latest_price_snapshots" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."sab_brainrot_market_catalog" WITH ("security_invoker"='true') AS
 SELECT "b"."id",
    "b"."name",
    "b"."slug",
    "b"."rarity",
    "b"."obtainability",
    "b"."base_income_per_second",
    "b"."ingame_cost",
    "b"."image_path",
    "b"."image_alt",
    "b"."image_url",
    "b"."source_url",
    "b"."updated_at",
    "p"."market_floor_usd" AS "cheapest_active_price_usd",
    "p"."typical_sale_usd" AS "market_value_usd",
    "p"."quick_sale_usd",
    "p"."patient_sale_usd",
    "p"."active_listing_count",
    "p"."completed_sale_count",
    "p"."unique_seller_count",
    COALESCE("p"."confidence_score", (0)::numeric) AS "confidence_score",
    COALESCE("p"."confidence_label", 'insufficient'::"text") AS "confidence_label",
    "p"."calculated_at" AS "price_updated_at",
        CASE
            WHEN ("p"."market_floor_usd" IS NOT NULL) THEN "p"."market_floor_usd"
            WHEN ("p"."typical_sale_usd" IS NOT NULL) THEN "p"."typical_sale_usd"
            ELSE NULL::numeric
        END AS "display_price_usd",
        CASE
            WHEN ("p"."market_floor_usd" IS NOT NULL) THEN 'From'::"text"
            WHEN ("p"."typical_sale_usd" IS NOT NULL) THEN 'Estimated market value'::"text"
            ELSE 'Not enough verified market data'::"text"
        END AS "display_price_label",
        CASE
            WHEN ("p"."market_floor_usd" IS NOT NULL) THEN 'live_listing'::"text"
            WHEN (("p"."typical_sale_usd" IS NOT NULL) AND ("p"."completed_sale_count" >= 3)) THEN 'completed_sales'::"text"
            WHEN ("p"."typical_sale_usd" IS NOT NULL) THEN 'active_listing_estimate'::"text"
            ELSE 'unavailable'::"text"
        END AS "display_price_source"
   FROM ("public"."sab_brainrot_catalog" "b"
     LEFT JOIN "public"."sab_latest_price_snapshots" "p" ON ((("p"."brainrot_id" = "b"."id") AND ("p"."mutation_id" IS NULL))));


ALTER VIEW "public"."sab_brainrot_market_catalog" OWNER TO "postgres";


