ALTER TABLE "public"."sab_brainrot_variants" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."sab_mutations" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "name" "text" NOT NULL,
    "slug" "text" NOT NULL,
    "income_multiplier" numeric(10,4) DEFAULT 1 NOT NULL,
    "mutation_type" "text" DEFAULT 'unknown'::"text" NOT NULL,
    "availability" "text" DEFAULT 'unknown'::"text" NOT NULL,
    "source_url" "text",
    "last_verified_at" timestamp with time zone,
    "is_active" boolean DEFAULT true NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "sab_mutations_availability_check" CHECK (("availability" = ANY (ARRAY['obtainable'::"text", 'event'::"text", 'unobtainable'::"text", 'unknown'::"text"]))),
    CONSTRAINT "sab_mutations_mutation_type_check" CHECK (("mutation_type" = ANY (ARRAY['default'::"text", 'permanent'::"text", 'limited'::"text", 'unknown'::"text"])))
);


ALTER TABLE "public"."sab_mutations" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."sab_brainrot_mutation_calculator" WITH ("security_invoker"='true') AS
 SELECT "b"."id" AS "brainrot_id",
    "b"."name" AS "brainrot_name",
    "b"."slug" AS "brainrot_slug",
    "b"."rarity",
    "b"."obtainability",
    "b"."base_income_per_second",
    "m"."id" AS "mutation_id",
    "m"."name" AS "mutation_name",
    "m"."slug" AS "mutation_slug",
    "m"."income_multiplier",
    "m"."availability" AS "mutation_availability",
    "v"."id" AS "verified_variant_id",
    COALESCE("v"."income_override_per_second", "round"(("b"."base_income_per_second" * "m"."income_multiplier"))) AS "calculated_income_per_second",
    "v"."exists_count",
    COALESCE("v"."is_tradeable", true) AS "is_tradeable",
    ("v"."id" IS NOT NULL) AS "is_verified_variant",
    (("v"."income_override_per_second" IS NOT NULL) OR ("b"."base_income_per_second" IS NOT NULL)) AS "has_known_income",
        CASE
            WHEN ("v"."income_override_per_second" IS NOT NULL) THEN 'verified_override'::"text"
            WHEN ("b"."base_income_per_second" IS NOT NULL) THEN 'calculated'::"text"
            ELSE 'unknown'::"text"
        END AS "income_source"
   FROM (("public"."sab_brainrots" "b"
     CROSS JOIN "public"."sab_mutations" "m")
     LEFT JOIN "public"."sab_brainrot_variants" "v" ON ((("v"."brainrot_id" = "b"."id") AND ("v"."mutation_id" = "m"."id"))))
  WHERE (("b"."is_active" = true) AND ("b"."needs_review" = false) AND ("m"."is_active" = true));


ALTER VIEW "public"."sab_brainrot_mutation_calculator" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."sab_external_market_observations" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "brainrot_id" "uuid" NOT NULL,
    "mutation_id" "uuid" NOT NULL,
    "observation_type" "text" NOT NULL,
    "source_name" "text" NOT NULL,
    "source_url" "text",
    "source_reference" "text",
    "currency" "text" DEFAULT 'USD'::"text" NOT NULL,
    "price_usd" numeric(12,2),
    "price_low_usd" numeric(12,2),
    "price_high_usd" numeric(12,2),
    "sample_size" integer DEFAULT 1 NOT NULL,
    "confidence_score" numeric(4,3) DEFAULT 0.500 NOT NULL,
    "observed_at" timestamp with time zone NOT NULL,
    "expires_at" timestamp with time zone,
    "is_verified" boolean DEFAULT false NOT NULL,
    "is_active" boolean DEFAULT true NOT NULL,
    "notes" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "sab_external_market_observations_confidence_score_check" CHECK ((("confidence_score" >= (0)::numeric) AND ("confidence_score" <= (1)::numeric))),
    CONSTRAINT "sab_external_market_observations_currency_check" CHECK (("currency" = 'USD'::"text")),
    CONSTRAINT "sab_external_market_observations_observation_type_check" CHECK (("observation_type" = ANY (ARRAY['manual_override'::"text", 'completed_sale'::"text", 'market_range'::"text", 'active_listing'::"text", 'manual_estimate'::"text"]))),
    CONSTRAINT "sab_external_market_observations_sample_size_check" CHECK (("sample_size" > 0)),
    CONSTRAINT "sab_external_market_price_present" CHECK ((COALESCE("price_usd", "price_low_usd", "price_high_usd") IS NOT NULL)),
    CONSTRAINT "sab_external_market_prices_positive" CHECK (((("price_usd" IS NULL) OR ("price_usd" > (0)::numeric)) AND (("price_low_usd" IS NULL) OR ("price_low_usd" > (0)::numeric)) AND (("price_high_usd" IS NULL) OR ("price_high_usd" > (0)::numeric)))),
    CONSTRAINT "sab_external_market_range_valid" CHECK ((("price_low_usd" IS NULL) OR ("price_high_usd" IS NULL) OR ("price_low_usd" <= "price_high_usd")))
);


ALTER TABLE "public"."sab_external_market_observations" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."sab_external_variant_price_estimates" WITH ("security_invoker"='true') AS
 WITH "normalized" AS (
         SELECT "observation"."id",
            "observation"."brainrot_id",
            "observation"."mutation_id",
            "observation"."observation_type",
            "observation"."source_name",
            "observation"."source_url",
            "observation"."source_reference",
            "observation"."currency",
            "observation"."price_usd",
            "observation"."price_low_usd",
            "observation"."price_high_usd",
            "observation"."sample_size",
            "observation"."confidence_score",
            "observation"."observed_at",
            "observation"."expires_at",
            "observation"."is_verified",
            "observation"."is_active",
            "observation"."notes",
            "observation"."created_at",
            "observation"."updated_at",
                CASE "observation"."observation_type"
                    WHEN 'manual_override'::"text" THEN 0
                    WHEN 'completed_sale'::"text" THEN 1
                    WHEN 'market_range'::"text" THEN 2
                    WHEN 'active_listing'::"text" THEN 3
                    WHEN 'manual_estimate'::"text" THEN 4
                    ELSE 9
                END AS "evidence_rank",
            COALESCE("observation"."price_usd", (("observation"."price_low_usd" + "observation"."price_high_usd") / (2)::numeric), "observation"."price_low_usd", "observation"."price_high_usd") AS "point_price_usd",
            COALESCE("observation"."price_low_usd", "observation"."price_usd", "observation"."price_high_usd") AS "effective_low_usd",
            COALESCE("observation"."price_high_usd", "observation"."price_usd", "observation"."price_low_usd") AS "effective_high_usd"
           FROM "public"."sab_external_market_observations" "observation"
          WHERE (("observation"."is_active" = true) AND (("observation"."expires_at" IS NULL) OR ("observation"."expires_at" > "now"())) AND (("observation"."observation_type" = 'manual_override'::"text") OR (("observation"."observation_type" = 'completed_sale'::"text") AND ("observation"."observed_at" >= ("now"() - '180 days'::interval))) OR (("observation"."observation_type" = 'market_range'::"text") AND ("observation"."observed_at" >= ("now"() - '60 days'::interval))) OR (("observation"."observation_type" = 'active_listing'::"text") AND ("observation"."observed_at" >= ("now"() - '30 days'::interval))) OR (("observation"."observation_type" = 'manual_estimate'::"text") AND ("observation"."observed_at" >= ("now"() - '30 days'::interval)))))
        ), "ranked" AS (
         SELECT "normalized"."id",
            "normalized"."brainrot_id",
            "normalized"."mutation_id",
            "normalized"."observation_type",
            "normalized"."source_name",
            "normalized"."source_url",
            "normalized"."source_reference",
            "normalized"."currency",
            "normalized"."price_usd",
            "normalized"."price_low_usd",
            "normalized"."price_high_usd",
            "normalized"."sample_size",
            "normalized"."confidence_score",
            "normalized"."observed_at",
            "normalized"."expires_at",
            "normalized"."is_verified",
            "normalized"."is_active",
            "normalized"."notes",
            "normalized"."created_at",
            "normalized"."updated_at",
            "normalized"."evidence_rank",
            "normalized"."point_price_usd",
            "normalized"."effective_low_usd",
            "normalized"."effective_high_usd",
            "min"("normalized"."evidence_rank") OVER (PARTITION BY "normalized"."brainrot_id", "normalized"."mutation_id") AS "best_evidence_rank"
           FROM "normalized"
        ), "best_evidence" AS (
         SELECT "ranked"."id",
            "ranked"."brainrot_id",
            "ranked"."mutation_id",
            "ranked"."observation_type",
            "ranked"."source_name",
            "ranked"."source_url",
            "ranked"."source_reference",
            "ranked"."currency",
            "ranked"."price_usd",
            "ranked"."price_low_usd",
            "ranked"."price_high_usd",
            "ranked"."sample_size",
            "ranked"."confidence_score",
            "ranked"."observed_at",
            "ranked"."expires_at",
            "ranked"."is_verified",
            "ranked"."is_active",
            "ranked"."notes",
            "ranked"."created_at",
            "ranked"."updated_at",
            "ranked"."evidence_rank",
            "ranked"."point_price_usd",
            "ranked"."effective_low_usd",
            "ranked"."effective_high_usd",
            "ranked"."best_evidence_rank"
           FROM "ranked"
          WHERE ("ranked"."evidence_rank" = "ranked"."best_evidence_rank")
        )
 SELECT "brainrot_id",
    "mutation_id",
    ("percentile_cont"((0.5)::double precision) WITHIN GROUP (ORDER BY (("point_price_usd")::double precision)))::numeric(12,2) AS "estimate_usd",
    ("percentile_cont"((0.5)::double precision) WITHIN GROUP (ORDER BY (("effective_low_usd")::double precision)))::numeric(12,2) AS "low_usd",
    ("percentile_cont"((0.5)::double precision) WITHIN GROUP (ORDER BY (("effective_high_usd")::double precision)))::numeric(12,2) AS "high_usd",
    "min"("best_evidence_rank") AS "evidence_rank",
        CASE "min"("best_evidence_rank")
            WHEN 0 THEN 'manual_override'::"text"
            WHEN 1 THEN 'completed_sale'::"text"
            WHEN 2 THEN 'market_range'::"text"
            WHEN 3 THEN 'active_listing'::"text"
            WHEN 4 THEN 'manual_estimate'::"text"
            ELSE 'unknown'::"text"
        END AS "source_type",
    "string_agg"(DISTINCT "source_name", ', '::"text" ORDER BY "source_name") AS "source_names",
    ("count"(*))::integer AS "observation_count",
    (COALESCE("sum"("sample_size"), (0)::bigint))::integer AS "total_sample_size",
    ("count"(DISTINCT "source_name"))::integer AS "source_count",
    ("avg"("confidence_score"))::numeric(4,3) AS "average_confidence_score",
    "max"("observed_at") AS "latest_observed_at",
        CASE
            WHEN ("min"("best_evidence_rank") = 0) THEN 'reviewed'::"text"
            WHEN (("min"("best_evidence_rank") = 1) AND (COALESCE("sum"("sample_size"), (0)::bigint) >= 3) AND ("count"(DISTINCT "source_name") >= 2)) THEN 'high'::"text"
            WHEN (("avg"("confidence_score") >= 0.800) AND (COALESCE("sum"("sample_size"), (0)::bigint) >= 6) AND ("count"(DISTINCT "source_name") >= 2)) THEN 'high'::"text"
            WHEN ("min"("best_evidence_rank") = 1) THEN 'medium'::"text"
            WHEN (("avg"("confidence_score") >= 0.650) AND (COALESCE("sum"("sample_size"), (0)::bigint) >= 3)) THEN 'medium'::"text"
            WHEN ("count"(DISTINCT "source_name") >= 2) THEN 'medium'::"text"
            ELSE 'low'::"text"
        END AS "confidence_label"
   FROM "best_evidence"
  GROUP BY "brainrot_id", "mutation_id";


ALTER VIEW "public"."sab_external_variant_price_estimates" OWNER TO "postgres";


