    "description" "text",
    "currency" "text" DEFAULT 'USD'::"text" NOT NULL,
    "listed_price" numeric(12,2) NOT NULL,
    "shipping_price" numeric(12,2) DEFAULT 0 NOT NULL,
    "quantity" integer DEFAULT 1 NOT NULL,
    "total_price_usd" numeric(12,2) NOT NULL,
    "unit_price_usd" numeric(12,2) GENERATED ALWAYS AS (("total_price_usd" / ("quantity")::numeric)) STORED,
    "seller_reference" "text",
    "seller_rating" numeric(8,3),
    "seller_sales_count" integer,
