    "fetched_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "brainrot_id" "uuid",
    "mutation_id" "uuid",
    "parse_status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "parser_confidence" numeric(4,3),
    "is_bundle" boolean DEFAULT false NOT NULL,
    "is_account_listing" boolean DEFAULT false NOT NULL,
    "is_inventory_listing" boolean DEFAULT false NOT NULL,
    "is_duplicate" boolean DEFAULT false NOT NULL,
    "is_outlier" boolean DEFAULT false NOT NULL,
