    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "sab_market_raw_listings_listed_price_check" CHECK (("listed_price" > (0)::numeric)),
    CONSTRAINT "sab_market_raw_listings_listing_status_check" CHECK (("listing_status" = ANY (ARRAY['active'::"text", 'sold'::"text", 'ended'::"text", 'removed'::"text", 'unknown'::"text"]))),
