    CONSTRAINT "sab_market_raw_listings_parse_status_check" CHECK (("parse_status" = ANY (ARRAY['pending'::"text", 'matched'::"text", 'unmatched'::"text", 'ambiguous'::"text", 'rejected'::"text"]))),
    CONSTRAINT "sab_market_raw_listings_parser_confidence_check" CHECK ((("parser_confidence" IS NULL) OR (("parser_confidence" >= (0)::numeric) AND ("parser_confidence" <= (1)::numeric)))),
    CONSTRAINT "sab_market_raw_listings_quantity_check" CHECK (("quantity" > 0)),
    CONSTRAINT "sab_market_raw_listings_shipping_price_check" CHECK (("shipping_price" >= (0)::numeric)),
    CONSTRAINT "sab_market_raw_listings_total_price_usd_check" CHECK (("total_price_usd" > (0)::numeric))
);


