CREATE OR REPLACE VIEW "public"."sab_market_listing_candidates" WITH ("security_invoker"='true') AS
 SELECT "listing"."id",
    "listing"."source_id",
    "source"."slug" AS "source_slug",
    "source"."name" AS "source_name",
    "source"."source_weight",
    "listing"."external_listing_id",
    "listing"."listing_type",
    "listing"."listing_status",
    "listing"."brainrot_id",
    "listing"."mutation_id",
    "listing"."unit_price_usd",
    "listing"."observed_at",
    "listing"."fetched_at",
    COALESCE("watchlist"."minimum_cash_value_usd", 1.00) AS "minimum_cash_value_usd",
    "source"."market_tier",
        CASE "source"."market_tier"
            WHEN 'primary'::"text" THEN 1
            WHEN 'supporting'::"text" THEN 2
            WHEN 'fallback'::"text" THEN 3
            ELSE 9
        END AS "market_tier_rank"
   FROM (("public"."sab_market_raw_listings" "listing"
     JOIN "public"."sab_market_sources" "source" ON (("source"."id" = "listing"."source_id")))
     LEFT JOIN "public"."sab_market_watchlist" "watchlist" ON ((("watchlist"."brainrot_id" = "listing"."brainrot_id") AND ("watchlist"."mutation_id" = "listing"."mutation_id"))))
  WHERE (("listing"."parse_status" = 'matched'::"text") AND ("listing"."brainrot_id" IS NOT NULL) AND ("listing"."mutation_id" IS NOT NULL) AND (COALESCE("listing"."parser_confidence", (0)::numeric) >= 0.900) AND ("listing"."is_bundle" = false) AND ("listing"."is_account_listing" = false) AND ("listing"."is_inventory_listing" = false) AND ("listing"."is_duplicate" = false) AND ("listing"."is_outlier" = false) AND ("listing"."currency" = 'USD'::"text") AND ("listing"."unit_price_usd" >= COALESCE("watchlist"."minimum_cash_value_usd", 1.00)) AND ("source"."status" <> 'disabled'::"text") AND ((("listing"."listing_type" = 'completed_sale'::"text") AND ("listing"."listing_status" = ANY (ARRAY['sold'::"text", 'ended'::"text"])) AND (COALESCE("listing"."ended_at", "listing"."observed_at") >= ("now"() - '180 days'::interval))) OR (("listing"."listing_type" = 'active_listing'::"text") AND ("listing"."listing_status" = 'active'::"text") AND ("listing"."observed_at" >= ("now"() - '30 days'::interval)))));


ALTER VIEW "public"."sab_market_listing_candidates" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."sab_market_clean_listing_evidence" WITH ("security_invoker"='true') AS
 WITH "bounds" AS (
         SELECT "sab_market_listing_candidates"."source_id",
            "sab_market_listing_candidates"."brainrot_id",
            "sab_market_listing_candidates"."mutation_id",
            "sab_market_listing_candidates"."listing_type",
            "count"(*) AS "evidence_count",
            "percentile_cont"((0.25)::double precision) WITHIN GROUP (ORDER BY (("sab_market_listing_candidates"."unit_price_usd")::double precision)) AS "q1_usd",
            "percentile_cont"((0.50)::double precision) WITHIN GROUP (ORDER BY (("sab_market_listing_candidates"."unit_price_usd")::double precision)) AS "median_usd",
            "percentile_cont"((0.75)::double precision) WITHIN GROUP (ORDER BY (("sab_market_listing_candidates"."unit_price_usd")::double precision)) AS "q3_usd"
           FROM "public"."sab_market_listing_candidates"
          GROUP BY "sab_market_listing_candidates"."source_id", "sab_market_listing_candidates"."brainrot_id", "sab_market_listing_candidates"."mutation_id", "sab_market_listing_candidates"."listing_type"
        )
 SELECT "candidate"."id",
    "candidate"."source_id",
    "candidate"."source_slug",
    "candidate"."source_name",
    "candidate"."source_weight",
    "candidate"."external_listing_id",
    "candidate"."listing_type",
    "candidate"."listing_status",
    "candidate"."brainrot_id",
    "candidate"."mutation_id",
    "candidate"."unit_price_usd",
    "candidate"."observed_at",
    "candidate"."fetched_at",
    "candidate"."minimum_cash_value_usd",
    "bounds"."evidence_count",
    "bounds"."q1_usd",
    "bounds"."median_usd",
    "bounds"."q3_usd",
    "candidate"."market_tier",
    "candidate"."market_tier_rank",
    (("bounds"."q3_usd" - "bounds"."q1_usd") / NULLIF("bounds"."median_usd", (0)::double precision)) AS "relative_iqr"
   FROM ("public"."sab_market_listing_candidates" "candidate"
     JOIN "bounds" ON ((("bounds"."source_id" = "candidate"."source_id") AND ("bounds"."brainrot_id" = "candidate"."brainrot_id") AND ("bounds"."mutation_id" = "candidate"."mutation_id") AND ("bounds"."listing_type" = "candidate"."listing_type"))))
  WHERE (("bounds"."evidence_count" < 4) OR ((("candidate"."unit_price_usd")::double precision >= GREATEST((0.01)::double precision, ("bounds"."q1_usd" - ((1.5)::double precision * GREATEST(("bounds"."q3_usd" - "bounds"."q1_usd"), ("bounds"."median_usd" * (0.15)::double precision)))))) AND (("candidate"."unit_price_usd")::double precision <= ("bounds"."q3_usd" + ((1.5)::double precision * GREATEST(("bounds"."q3_usd" - "bounds"."q1_usd"), ("bounds"."median_usd" * (0.15)::double precision)))))));


ALTER VIEW "public"."sab_market_clean_listing_evidence" OWNER TO "postgres";


