    "cross_source_max_spread_ratio" numeric(6,3) NOT NULL,
    "strong_cluster_max_source_spread_ratio" numeric(6,3) NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "sab_market_pricing_policy_check" CHECK (("supported_active_max_samples" >= "supported_active_min_samples")),
    CONSTRAINT "sab_market_pricing_policy_cross_source_max_spread_ratio_check" CHECK (("cross_source_max_spread_ratio" >= (1)::numeric)),
    CONSTRAINT "sab_market_pricing_policy_cross_source_min_samples_check" CHECK (("cross_source_min_samples" >= 2)),
    CONSTRAINT "sab_market_pricing_policy_id_check" CHECK (("id" = 1)),
    CONSTRAINT "sab_market_pricing_policy_minimum_trade_price_usd_check" CHECK (("minimum_trade_price_usd" > (0)::numeric)),
    CONSTRAINT "sab_market_pricing_policy_strong_active_max_iqr_ratio_check" CHECK ((("strong_active_max_iqr_ratio" > (0)::numeric) AND ("strong_active_max_iqr_ratio" <= (1)::numeric))),
    CONSTRAINT "sab_market_pricing_policy_strong_active_min_samples_check" CHECK (("strong_active_min_samples" >= 3)),
    CONSTRAINT "sab_market_pricing_policy_strong_cluster_max_source_sprea_check" CHECK (("strong_cluster_max_source_spread_ratio" >= (1)::numeric)),
    CONSTRAINT "sab_market_pricing_policy_supported_active_max_iqr_ratio_check" CHECK ((("supported_active_max_iqr_ratio" > (0)::numeric) AND ("supported_active_max_iqr_ratio" <= (1)::numeric))),
    CONSTRAINT "sab_market_pricing_policy_supported_active_min_samples_check" CHECK (("supported_active_min_samples" >= 3))
);


ALTER TABLE "public"."sab_market_pricing_policy" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."sab_market_rejection_patterns" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "category" "text" NOT NULL,
    "pattern" "text" NOT NULL,
    "normalized_pattern" "text" GENERATED ALWAYS AS ("public"."sab_normalize_market_text"("pattern")) STORED,
    "reason" "text" NOT NULL,
    "priority" smallint DEFAULT 50 NOT NULL,
    "is_active" boolean DEFAULT true NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "sab_market_rejection_patterns_category_check" CHECK (("category" = ANY (ARRAY['bundle'::"text", 'account'::"text", 'inventory'::"text", 'ambiguous_mutation'::"text", 'service'::"text", 'unrelated'::"text"])))
);


ALTER TABLE "public"."sab_market_rejection_patterns" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."sab_market_source_variant_estimates" WITH ("security_invoker"='true') AS
 WITH "ranked" AS (
         SELECT "evidence"."id",
            "evidence"."source_id",
            "evidence"."source_slug",
            "evidence"."source_name",
            "evidence"."source_weight",
            "evidence"."external_listing_id",
            "evidence"."listing_type",
            "evidence"."listing_status",
            "evidence"."brainrot_id",
            "evidence"."mutation_id",
            "evidence"."unit_price_usd",
            "evidence"."observed_at",
            "evidence"."fetched_at",
            "evidence"."minimum_cash_value_usd",
            "evidence"."evidence_count",
            "evidence"."q1_usd",
            "evidence"."median_usd",
            "evidence"."q3_usd",
            "evidence"."market_tier",
            "evidence"."market_tier_rank",
            "evidence"."relative_iqr",
                CASE "evidence"."listing_type"
                    WHEN 'completed_sale'::"text" THEN 1
                    WHEN 'active_listing'::"text" THEN 2
                    ELSE 9
                END AS "evidence_rank",
            "min"(
                CASE "evidence"."listing_type"
                    WHEN 'completed_sale'::"text" THEN 1
                    WHEN 'active_listing'::"text" THEN 2
                    ELSE 9
                END) OVER (PARTITION BY "evidence"."source_id", "evidence"."brainrot_id", "evidence"."mutation_id") AS "best_evidence_rank"
           FROM "public"."sab_market_clean_listing_evidence" "evidence"
        ), "best_evidence" AS (
         SELECT "ranked"."id",
            "ranked"."source_id",
            "ranked"."source_slug",
            "ranked"."source_name",
            "ranked"."source_weight",
            "ranked"."external_listing_id",
            "ranked"."listing_type",
            "ranked"."listing_status",
            "ranked"."brainrot_id",
            "ranked"."mutation_id",
            "ranked"."unit_price_usd",
            "ranked"."observed_at",
            "ranked"."fetched_at",
            "ranked"."minimum_cash_value_usd",
            "ranked"."evidence_count",
            "ranked"."q1_usd",
            "ranked"."median_usd",
            "ranked"."q3_usd",
            "ranked"."market_tier",
            "ranked"."market_tier_rank",
            "ranked"."relative_iqr",
            "ranked"."evidence_rank",
            "ranked"."best_evidence_rank"
           FROM "ranked"
          WHERE ("ranked"."evidence_rank" = "ranked"."best_evidence_rank")
        ), "aggregated" AS (
         SELECT "best_evidence"."source_id",
            "best_evidence"."source_slug",
            "best_evidence"."source_name",
            "best_evidence"."source_weight",
            "best_evidence"."brainrot_id",
            "best_evidence"."mutation_id",
                CASE "min"("best_evidence"."evidence_rank")
                    WHEN 1 THEN 'completed_sale'::"text"
                    WHEN 2 THEN 'active_listing'::"text"
                    ELSE 'unknown'::"text"
                END AS "evidence_type",
            ("percentile_cont"((0.50)::double precision) WITHIN GROUP (ORDER BY (("best_evidence"."unit_price_usd")::double precision)))::numeric(12,2) AS "median_usd",
            ("percentile_cont"((0.25)::double precision) WITHIN GROUP (ORDER BY (("best_evidence"."unit_price_usd")::double precision)))::numeric(12,2) AS "low_usd",
            ("percentile_cont"((0.75)::double precision) WITHIN GROUP (ORDER BY (("best_evidence"."unit_price_usd")::double precision)))::numeric(12,2) AS "high_usd",
            ("count"(*))::integer AS "sample_count",
            "max"("best_evidence"."observed_at") AS "latest_observed_at",
            "best_evidence"."market_tier",
            "best_evidence"."market_tier_rank"
           FROM "best_evidence"
          GROUP BY "best_evidence"."source_id", "best_evidence"."source_slug", "best_evidence"."source_name", "best_evidence"."source_weight", "best_evidence"."brainrot_id", "best_evidence"."mutation_id", "best_evidence"."market_tier", "best_evidence"."market_tier_rank"
        )
 SELECT "source_id",
    "source_slug",
    "source_name",
    "source_weight",
    "brainrot_id",
    "mutation_id",
    "evidence_type",
    "median_usd",
    "low_usd",
    "high_usd",
    "sample_count",
    "latest_observed_at",
    "market_tier",
    "market_tier_rank",
    (("high_usd" - "low_usd") / NULLIF("median_usd", (0)::numeric)) AS "cluster_spread_ratio",
    (("evidence_type" = 'active_listing'::"text") AND ("sample_count" >= 10) AND ((("high_usd" - "low_usd") / NULLIF("median_usd", (0)::numeric)) <= 0.35)) AS "is_strong_active_cluster"
   FROM "aggregated";


ALTER VIEW "public"."sab_market_source_variant_estimates" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."sab_market_sync_config" (
    "id" smallint DEFAULT 1 NOT NULL,
    "imports_enabled" boolean DEFAULT false NOT NULL,
    "live_data_start_at" timestamp with time zone,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "sab_market_sync_config_check" CHECK ((("imports_enabled" = false) OR ("live_data_start_at" IS NOT NULL))),
    CONSTRAINT "sab_market_sync_config_id_check" CHECK (("id" = 1))
);


ALTER TABLE "public"."sab_market_sync_config" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."sab_market_variant_price_estimates" WITH ("security_invoker"='true') AS
 WITH "policy" AS (
         SELECT "pricing_policy"."minimum_trade_price_usd",
            "pricing_policy"."strong_active_min_samples",
            "pricing_policy"."strong_active_max_iqr_ratio",
            "pricing_policy"."supported_active_min_samples",
            "pricing_policy"."supported_active_max_samples",
            "pricing_policy"."supported_active_max_iqr_ratio",
            "pricing_policy"."cross_source_min_samples",
            "pricing_policy"."cross_source_max_spread_ratio",
            "pricing_policy"."strong_cluster_max_source_spread_ratio"
           FROM "public"."sab_market_pricing_policy" "pricing_policy"
          WHERE ("pricing_policy"."id" = 1)
        ), "tiered" AS (
         SELECT "source_estimate"."source_id",
            "source_estimate"."source_slug",
            "source_estimate"."source_name",
            "source_estimate"."source_weight",
            "source_estimate"."brainrot_id",
            "source_estimate"."mutation_id",
            "source_estimate"."evidence_type",
            "source_estimate"."median_usd",
            "source_estimate"."low_usd",
            "source_estimate"."high_usd",
            "source_estimate"."sample_count",
            "source_estimate"."latest_observed_at",
            "source_estimate"."market_tier",
            "source_estimate"."market_tier_rank",
            "source_estimate"."cluster_spread_ratio",
            "source_estimate"."is_strong_active_cluster",
            "min"("source_estimate"."market_tier_rank") OVER (PARTITION BY "source_estimate"."brainrot_id", "source_estimate"."mutation_id") AS "selected_tier_rank"
           FROM "public"."sab_market_source_variant_estimates" "source_estimate"
        ), "selected_sources" AS (
         SELECT "tiered"."source_id",
            "tiered"."source_slug",
            "tiered"."source_name",
            "tiered"."source_weight",
            "tiered"."brainrot_id",
            "tiered"."mutation_id",
            "tiered"."evidence_type",
            "tiered"."median_usd",
            "tiered"."low_usd",
            "tiered"."high_usd",
            "tiered"."sample_count",
            "tiered"."latest_observed_at",
            "tiered"."market_tier",
            "tiered"."market_tier_rank",
            "tiered"."cluster_spread_ratio",
            "tiered"."is_strong_active_cluster",
            "tiered"."selected_tier_rank"
           FROM "tiered"
          WHERE ("tiered"."market_tier_rank" = "tiered"."selected_tier_rank")
        ), "summary" AS (
         SELECT "source_estimate"."brainrot_id",
            "source_estimate"."mutation_id",
                CASE "min"("source_estimate"."market_tier_rank")
                    WHEN 1 THEN 'primary'::"text"
                    WHEN 2 THEN 'supporting'::"text"
                    WHEN 3 THEN 'fallback'::"text"
                    ELSE 'unknown'::"text"
                END AS "selected_market_tier",
            ("percentile_cont"((0.50)::double precision) WITHIN GROUP (ORDER BY (("source_estimate"."median_usd")::double precision)))::numeric(12,2) AS "estimate_usd",
            (
                CASE
                    WHEN ("count"(*) = 1) THEN ("min"("source_estimate"."low_usd"))::double precision
                    ELSE "percentile_cont"((0.25)::double precision) WITHIN GROUP (ORDER BY (("source_estimate"."median_usd")::double precision))
                END)::numeric(12,2) AS "low_usd",
            (
                CASE
                    WHEN ("count"(*) = 1) THEN ("max"("source_estimate"."high_usd"))::double precision
                    ELSE "percentile_cont"((0.75)::double precision) WITHIN GROUP (ORDER BY (("source_estimate"."median_usd")::double precision))
                END)::numeric(12,2) AS "high_usd",
            ("count"(*))::integer AS "source_count",
            ("sum"("source_estimate"."sample_count"))::integer AS "total_sample_count",
            (COALESCE("sum"("source_estimate"."sample_count") FILTER (WHERE ("source_estimate"."evidence_type" = 'completed_sale'::"text")), (0)::bigint))::integer AS "completed_sale_sample_count",
            (COALESCE("sum"("source_estimate"."sample_count") FILTER (WHERE ("source_estimate"."evidence_type" = 'active_listing'::"text")), (0)::bigint))::integer AS "active_listing_sample_count",
            ("count"(*) FILTER (WHERE (("source_estimate"."evidence_type" = 'active_listing'::"text") AND ("source_estimate"."sample_count" >= "policy"."strong_active_min_samples") AND ("source_estimate"."cluster_spread_ratio" <= "policy"."strong_active_max_iqr_ratio") AND ("source_estimate"."median_usd" >= "policy"."minimum_trade_price_usd"))))::integer AS "strong_cluster_source_count",
            ("count"(*) FILTER (WHERE (("source_estimate"."evidence_type" = 'active_listing'::"text") AND (("source_estimate"."sample_count" >= "policy"."supported_active_min_samples") AND ("source_estimate"."sample_count" <= "policy"."supported_active_max_samples")) AND ("source_estimate"."cluster_spread_ratio" <= "policy"."supported_active_max_iqr_ratio") AND ("source_estimate"."median_usd" >= "policy"."minimum_trade_price_usd"))))::integer AS "supported_cluster_source_count",
            ("min"("source_estimate"."median_usd"))::numeric(12,2) AS "minimum_source_median_usd",
            ("max"("source_estimate"."median_usd"))::numeric(12,2) AS "maximum_source_median_usd",
            "max"("source_estimate"."latest_observed_at") AS "latest_observed_at",
            "string_agg"("source_estimate"."source_name", ', '::"text" ORDER BY "source_estimate"."source_name") AS "sources_used",
            "policy"."minimum_trade_price_usd",
            "policy"."cross_source_min_samples",
            "policy"."cross_source_max_spread_ratio",
            "policy"."strong_cluster_max_source_spread_ratio"
           FROM ("selected_sources" "source_estimate"
             CROSS JOIN "policy")
          GROUP BY "source_estimate"."brainrot_id", "source_estimate"."mutation_id", "policy"."minimum_trade_price_usd", "policy"."strong_active_min_samples", "policy"."strong_active_max_iqr_ratio", "policy"."supported_active_min_samples", "policy"."supported_active_max_samples", "policy"."supported_active_max_iqr_ratio", "policy"."cross_source_min_samples", "policy"."cross_source_max_spread_ratio", "policy"."strong_cluster_max_source_spread_ratio"
        ), "scored" AS (
         SELECT "summary"."brainrot_id",
            "summary"."mutation_id",
            "summary"."selected_market_tier",
            "summary"."estimate_usd",
            "summary"."low_usd",
            "summary"."high_usd",
            "summary"."source_count",
            "summary"."total_sample_count",
            "summary"."completed_sale_sample_count",
            "summary"."active_listing_sample_count",
            "summary"."strong_cluster_source_count",
            "summary"."supported_cluster_source_count",
            "summary"."minimum_source_median_usd",
            "summary"."maximum_source_median_usd",
            "summary"."latest_observed_at",
            "summary"."sources_used",
            "summary"."minimum_trade_price_usd",
            "summary"."cross_source_min_samples",
            "summary"."cross_source_max_spread_ratio",
            "summary"."strong_cluster_max_source_spread_ratio",
            (("summary"."maximum_source_median_usd" / NULLIF("summary"."minimum_source_median_usd", (0)::numeric)))::numeric(10,3) AS "source_spread_ratio"
           FROM "summary"
        ), "classified" AS (
         SELECT "scored"."brainrot_id",
            "scored"."mutation_id",
            "scored"."selected_market_tier",
            "scored"."estimate_usd",
            "scored"."low_usd",
            "scored"."high_usd",
            "scored"."source_count",
            "scored"."total_sample_count",
            "scored"."completed_sale_sample_count",
            "scored"."active_listing_sample_count",
            "scored"."strong_cluster_source_count",
            "scored"."supported_cluster_source_count",
            "scored"."minimum_source_median_usd",
            "scored"."maximum_source_median_usd",
            "scored"."latest_observed_at",
            "scored"."sources_used",
            "scored"."minimum_trade_price_usd",
            "scored"."cross_source_min_samples",
            "scored"."cross_source_max_spread_ratio",
            "scored"."strong_cluster_max_source_spread_ratio",
            "scored"."source_spread_ratio",
                CASE
                    WHEN (("scored"."selected_market_tier" = 'fallback'::"text") AND ("scored"."completed_sale_sample_count" >= 3)) THEN 'low'::"text"
                    WHEN ("scored"."selected_market_tier" = 'fallback'::"text") THEN 'insufficient'::"text"
                    WHEN (("scored"."completed_sale_sample_count" >= 3) AND ("scored"."source_count" >= 2)) THEN 'high'::"text"
                    WHEN (("scored"."strong_cluster_source_count" >= 2) AND ("scored"."total_sample_count" >= 20) AND ("scored"."source_spread_ratio" <= 1.250)) THEN 'high'::"text"
                    WHEN (("scored"."source_count" >= 3) AND ("scored"."total_sample_count" >= 12) AND ("scored"."source_spread_ratio" <= 1.250)) THEN 'high'::"text"
                    WHEN ("scored"."completed_sale_sample_count" >= 1) THEN 'medium'::"text"
                    WHEN (("scored"."strong_cluster_source_count" >= 1) AND (("scored"."source_count" = 1) OR ("scored"."source_spread_ratio" <= "scored"."strong_cluster_max_source_spread_ratio"))) THEN 'medium'::"text"
                    WHEN (("scored"."source_count" >= 2) AND ("scored"."total_sample_count" >= "scored"."cross_source_min_samples") AND ("scored"."source_spread_ratio" <= "scored"."cross_source_max_spread_ratio")) THEN 'medium'::"text"
                    WHEN (("scored"."supported_cluster_source_count" >= 1) AND (("scored"."source_count" = 1) OR ("scored"."source_spread_ratio" <= "scored"."cross_source_max_spread_ratio"))) THEN 'low'::"text"
                    WHEN ("scored"."total_sample_count" >= 3) THEN 'low'::"text"
                    ELSE 'insufficient'::"text"
                END AS "calculated_confidence_label"
           FROM "scored"
        )
 SELECT "brainrot_id",
    "mutation_id",
    "estimate_usd",
    "low_usd",
    "high_usd",
    "source_count",
    "total_sample_count",
    "completed_sale_sample_count",
    "active_listing_sample_count",
    "source_spread_ratio",
    "sources_used",
    "latest_observed_at",
    "calculated_confidence_label" AS "confidence_label",
    (("estimate_usd" >= "minimum_trade_price_usd") AND ((("selected_market_tier" = 'fallback'::"text") AND ("completed_sale_sample_count" >= 3)) OR (("selected_market_tier" <> 'fallback'::"text") AND (("completed_sale_sample_count" >= 1) OR (("strong_cluster_source_count" >= 1) AND (("source_count" = 1) OR ("source_spread_ratio" <= "strong_cluster_max_source_spread_ratio"))) OR (("supported_cluster_source_count" >= 1) AND (("source_count" = 1) OR ("source_spread_ratio" <= "cross_source_max_spread_ratio"))) OR (("source_count" >= 2) AND ("total_sample_count" >= "cross_source_min_samples") AND ("source_spread_ratio" <= "cross_source_max_spread_ratio")))))) AS "is_trade_ready",
    "selected_market_tier",
    "strong_cluster_source_count",
    "supported_cluster_source_count"
   FROM "classified";


ALTER VIEW "public"."sab_market_variant_price_estimates" OWNER TO "postgres";


