CREATE TABLE IF NOT EXISTS "public"."sab_price_corrections" (
    "brainrot_id" "uuid" NOT NULL,
    "mutation_id" "uuid" NOT NULL,
    "value_usd" numeric(12,2),
    "low_usd" numeric(12,2),
    "high_usd" numeric(12,2),
    "original_value_usd" numeric(12,2),
    "reason" "text" NOT NULL,
    "confidence_label" "text" NOT NULL,
    "anchor_usd" numeric(12,2),
    "cohort_size" integer DEFAULT 0 NOT NULL,
    "sample_count" integer DEFAULT 0 NOT NULL,
    "is_anchored" boolean DEFAULT false NOT NULL,
    "is_publishable" boolean DEFAULT true NOT NULL,
    "computed_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "cheapest_usd" numeric(12,2),
    "average_usd" numeric(12,2),
    CONSTRAINT "sab_price_corrections_publishable_has_value" CHECK (((NOT "is_publishable") OR ("value_usd" IS NOT NULL))),
    CONSTRAINT "sab_price_corrections_reason_check" CHECK (("reason" = ANY (ARRAY['reputable'::"text", 'floor'::"text", 'trusted'::"text", 'thin_sample_within_anchor'::"text", 'thin_sample_anchored'::"text", 'insufficient_evidence'::"text", 'variant_anchored'::"text"])))
);


ALTER TABLE "public"."sab_price_corrections" OWNER TO "postgres";


COMMENT ON TABLE "public"."sab_price_corrections" IS 'Accuracy corrections merged over sab_public_price_catalog. One row per (brainrot, mutation). Written by /api/cron/correct-sab-prices; read through sab_public_price_catalog_corrected.';



