CREATE OR REPLACE VIEW "public"."sab_public_price_catalog" WITH ("security_barrier"='true', "security_invoker"='true') AS
 SELECT "brainrot_id",
    "brainrot_name",
    "brainrot_slug",
    "rarity",
    "image_url",
    "mutation_id",
    "mutation_name",
    "mutation_slug",
    "market_value_usd",
    "market_low_usd",
    "market_high_usd",
    "confidence_label",
    "external_sample_size",
    "source_count",
    "price_updated_at",
    "is_trade_ready",
    "is_public_estimate"
   FROM "public"."sab_public_price_catalog_rows"() "sab_public_price_catalog_rows"("brainrot_id", "brainrot_name", "brainrot_slug", "rarity", "image_url", "mutation_id", "mutation_name", "mutation_slug", "market_value_usd", "market_low_usd", "market_high_usd", "confidence_label", "external_sample_size", "source_count", "price_updated_at", "is_trade_ready", "is_public_estimate");


ALTER VIEW "public"."sab_public_price_catalog" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."sab_public_price_catalog_corrected" WITH ("security_barrier"='true', "security_invoker"='true') AS
 SELECT "catalog"."brainrot_id",
    "catalog"."brainrot_name",
    "catalog"."brainrot_slug",
    "catalog"."rarity",
    "catalog"."image_url",
    "catalog"."mutation_id",
    "catalog"."mutation_name",
    "catalog"."mutation_slug",
    (COALESCE("correction"."value_usd", "catalog"."market_value_usd"))::numeric(12,2) AS "market_value_usd",
    (COALESCE("correction"."low_usd", "catalog"."market_low_usd"))::numeric(12,2) AS "market_low_usd",
    (COALESCE("correction"."high_usd", "catalog"."market_high_usd"))::numeric(12,2) AS "market_high_usd",
    COALESCE("correction"."confidence_label", "catalog"."confidence_label") AS "confidence_label",
    "catalog"."external_sample_size",
    "catalog"."source_count",
    COALESCE("correction"."computed_at", "catalog"."price_updated_at") AS "price_updated_at",
    "catalog"."is_trade_ready",
    "catalog"."is_public_estimate",
    COALESCE("correction"."is_anchored", false) AS "is_anchored",
    "correction"."reason" AS "correction_reason",
    "correction"."anchor_usd",
    COALESCE("correction"."cohort_size", 0) AS "cohort_size",
    "correction"."cheapest_usd",
    "correction"."average_usd"
   FROM ("public"."sab_public_price_catalog" "catalog"
     LEFT JOIN "public"."sab_price_corrections" "correction" ON ((("correction"."brainrot_id" = "catalog"."brainrot_id") AND ("correction"."mutation_id" = "catalog"."mutation_id"))))
  WHERE COALESCE("correction"."is_publishable", true);


ALTER VIEW "public"."sab_public_price_catalog_corrected" OWNER TO "postgres";


COMMENT ON VIEW "public"."sab_public_price_catalog_corrected" IS 'sab_public_price_catalog with accuracy corrections merged over it. Rows whose correction is not publishable are withheld. Prefer this view over sab_public_price_catalog for anything user-facing.';



CREATE TABLE IF NOT EXISTS "public"."sab_source_mappings" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "source_name" "text" NOT NULL,
    "source_item_name" "text" NOT NULL,
    "normalized_source_item_name" "text" NOT NULL,
    "brainrot_id" "uuid",
    "mutation_id" "uuid",
    "mapping_status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "confidence" numeric(5,4),
    "reviewed_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "sab_source_mappings_mapping_status_check" CHECK (("mapping_status" = ANY (ARRAY['pending'::"text", 'approved'::"text", 'rejected'::"text"])))
);


ALTER TABLE "public"."sab_source_mappings" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."sab_trade_price_catalog" WITH ("security_invoker"='true') AS
 SELECT "brainrot"."id" AS "brainrot_id",
    "brainrot"."name" AS "brainrot_name",
    "brainrot"."slug" AS "brainrot_slug",
    "brainrot"."rarity",
    "catalog"."image_url",
    "mutation"."id" AS "mutation_id",
    "mutation"."name" AS "mutation_name",
    "mutation"."slug" AS "mutation_slug",
        CASE
            WHEN (("mutation"."slug" = 'default'::"text") AND ("catalog"."display_price_usd" IS NOT NULL) AND (COALESCE("catalog"."confidence_label", 'insufficient'::"text") <> 'insufficient'::"text")) THEN "catalog"."display_price_usd"
            ELSE "external_price"."estimate_usd"
        END AS "market_value_usd",
        CASE
            WHEN (("mutation"."slug" = 'default'::"text") AND ("catalog"."display_price_usd" IS NOT NULL) AND (COALESCE("catalog"."confidence_label", 'insufficient'::"text") <> 'insufficient'::"text")) THEN COALESCE("catalog"."quick_sale_usd", "catalog"."display_price_usd")
            ELSE "external_price"."low_usd"
        END AS "market_low_usd",
        CASE
            WHEN (("mutation"."slug" = 'default'::"text") AND ("catalog"."display_price_usd" IS NOT NULL) AND (COALESCE("catalog"."confidence_label", 'insufficient'::"text") <> 'insufficient'::"text")) THEN COALESCE("catalog"."patient_sale_usd", "catalog"."display_price_usd")
            ELSE "external_price"."high_usd"
        END AS "market_high_usd",
        CASE
            WHEN (("mutation"."slug" = 'default'::"text") AND ("catalog"."display_price_usd" IS NOT NULL) AND (COALESCE("catalog"."confidence_label", 'insufficient'::"text") <> 'insufficient'::"text")) THEN 'dropmarket_market'::"text"
            ELSE "external_price"."source_type"
        END AS "price_source_type",
        CASE
            WHEN (("mutation"."slug" = 'default'::"text") AND ("catalog"."display_price_usd" IS NOT NULL) AND (COALESCE("catalog"."confidence_label", 'insufficient'::"text") <> 'insufficient'::"text")) THEN 'DropMarket'::"text"
            ELSE "external_price"."source_names"
        END AS "price_source_name",
        CASE
            WHEN (("mutation"."slug" = 'default'::"text") AND ("catalog"."display_price_usd" IS NOT NULL) AND (COALESCE("catalog"."confidence_label", 'insufficient'::"text") <> 'insufficient'::"text")) THEN "catalog"."confidence_label"
            ELSE COALESCE("external_price"."confidence_label", 'insufficient'::"text")
        END AS "confidence_label",
    COALESCE("external_price"."total_sample_size", 0) AS "external_sample_size",
        CASE
            WHEN (("mutation"."slug" = 'default'::"text") AND ("catalog"."display_price_usd" IS NOT NULL) AND (COALESCE("catalog"."confidence_label", 'insufficient'::"text") <> 'insufficient'::"text")) THEN "catalog"."price_updated_at"
            ELSE "external_price"."latest_observed_at"
        END AS "price_updated_at",
    (
        CASE
            WHEN (("mutation"."slug" = 'default'::"text") AND ("catalog"."display_price_usd" IS NOT NULL) AND (COALESCE("catalog"."confidence_label", 'insufficient'::"text") <> 'insufficient'::"text")) THEN "catalog"."display_price_usd"
            ELSE "external_price"."estimate_usd"
        END IS NOT NULL) AS "is_trade_ready"
   FROM ((("public"."sab_brainrots" "brainrot"
     CROSS JOIN "public"."sab_mutations" "mutation")
     LEFT JOIN "public"."sab_brainrot_market_catalog" "catalog" ON (("catalog"."id" = "brainrot"."id")))
     LEFT JOIN "public"."sab_external_variant_price_estimates" "external_price" ON ((("external_price"."brainrot_id" = "brainrot"."id") AND ("external_price"."mutation_id" = "mutation"."id"))));


ALTER VIEW "public"."sab_trade_price_catalog" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."seller_applications" (
    "id" "uuid" DEFAULT "extensions"."uuid_generate_v4"() NOT NULL,
    "user_id" "uuid" NOT NULL,
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "is_18_or_older" boolean NOT NULL,
    "seller_type" "text" NOT NULL,
    "primary_games" "text"[] DEFAULT '{}'::"uuid"[],
    "expected_monthly_volume" "text",
    "referral_code" "text",
    "full_legal_name" "text" NOT NULL,
    "display_name" "text" NOT NULL,
    "country" "text" NOT NULL,
    "state_province" "text",
    "city" "text",
    "phone_number" "text" NOT NULL,
    "phone_verified" boolean DEFAULT false,
    "alternate_email" "text",
    "company_legal_name" "text",
    "business_registration_number" "text",
    "tax_id_vat" "text",
    "company_address" "text",
    "business_type" "text",
    "year_established" integer,
    "business_email" "text",
    "business_phone" "text",
    "profile_bio" "text",
    "business_hours" "text",
    "timezone" "text",
    "languages_spoken" "text"[] DEFAULT '{}'::"text"[],
    "discord_username" "text",
    "twitter_handle" "text",
    "twitch_channel" "text",
    "youtube_channel" "text",
    "refund_policy" "text",
    "delivery_timeframe" "text",
    "terms_of_service" "text",
    "payout_method" "text",
    "bank_account_holder_name" "text",
    "bank_name" "text",
    "bank_account_number_encrypted" "text",
    "bank_routing_code" "text",
    "bank_swift_code" "text",
    "bank_iban" "text",
    "paypal_email" "text",
    "crypto_wallet_address" "text",
    "tax_residency_country" "text",
    "w9_submitted" boolean DEFAULT false,
    "w8ben_submitted" boolean DEFAULT false,
    "accepted_seller_agreement" boolean DEFAULT false,
    "accepted_privacy_policy" boolean DEFAULT false,
    "accepted_anti_fraud_policy" boolean DEFAULT false,
    "accepted_commission_structure" boolean DEFAULT false,
    "accepted_data_processing" boolean DEFAULT false,
    "information_accurate_confirmed" boolean DEFAULT false,
    "submitted_at" timestamp with time zone,
    "reviewed_at" timestamp with time zone,
    "reviewed_by" "uuid",
    "rejection_reason" "text",
    "admin_notes" "text",
    "fraud_score" integer DEFAULT 0,
    "ip_address" "inet",
    "device_fingerprint" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "identity_verified" boolean DEFAULT false,
    "address_verified" boolean DEFAULT false,
    "business_verified" boolean DEFAULT false,
    "tax_verified" boolean DEFAULT false,
    "rejected_at" timestamp with time zone,
    "rejected_by" "uuid",
    "rejection_category" "text",
    "withdrawn_at" timestamp with time zone,
    "can_reapply_at" timestamp with time zone,
    "rejection_count" integer DEFAULT 0,
    "withdrawal_count" integer DEFAULT 0,
    "other_games" "text",
    "profile_picture_path" "text",
    "shop_name" "text",
    "crypto_type" "text",
    "games_categories" "jsonb",
    "selling_experience" "text",
    "payout_currency" "text",
    "seller_signature" "text",
    "seller_signed_at" timestamp with time zone,
    "seller_signature_image" "text",
    CONSTRAINT "seller_applications_business_type_check" CHECK (("business_type" = ANY (ARRAY['llc'::"text", 'corporation'::"text", 'sole_proprietorship'::"text", 'partnership'::"text", 'other'::"text"]))),
    CONSTRAINT "seller_applications_expected_monthly_volume_check" CHECK (("expected_monthly_volume" = ANY (ARRAY['under_500'::"text", '500_2000'::"text", '2000_10000'::"text", 'over_10000'::"text"]))),
    CONSTRAINT "seller_applications_fraud_score_check" CHECK ((("fraud_score" >= 0) AND ("fraud_score" <= 100))),
    CONSTRAINT "seller_applications_payout_method_check" CHECK (("payout_method" = ANY (ARRAY['bank_transfer'::"text", 'paypal'::"text", 'cryptocurrency'::"text"]))),
    CONSTRAINT "seller_applications_rejection_category_check" CHECK (("rejection_category" = ANY (ARRAY['incomplete_documentation'::"text", 'invalid_documents'::"text", 'information_mismatch'::"text", 'suspicious_activity'::"text", 'business_verification_failed'::"text", 'other'::"text"]))),
    CONSTRAINT "seller_applications_seller_type_check" CHECK (("seller_type" = ANY (ARRAY['individual'::"text", 'business'::"text"]))),
    CONSTRAINT "seller_applications_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'approved'::"text", 'rejected'::"text", 'info_requested'::"text", 'under_review'::"text", 'withdrawn'::"text"]))),
    CONSTRAINT "valid_display_name" CHECK (("char_length"("display_name") >= 3)),
    CONSTRAINT "valid_phone" CHECK (("char_length"("phone_number") >= 10))
);

ALTER TABLE ONLY "public"."seller_applications" REPLICA IDENTITY FULL;


ALTER TABLE "public"."seller_applications" OWNER TO "postgres";


COMMENT ON TABLE "public"."seller_applications" IS 'Seller applications with REPLICA IDENTITY FULL for realtime UPDATE broadcasts — drives the reactive Become-a-Seller CTA in use-auth.tsx.';



COMMENT ON COLUMN "public"."seller_applications"."rejection_reason" IS 'Detailed reason for rejection provided by admin';



COMMENT ON COLUMN "public"."seller_applications"."rejected_at" IS 'Timestamp when application was rejected by admin';



COMMENT ON COLUMN "public"."seller_applications"."rejected_by" IS 'Admin who rejected the application';



COMMENT ON COLUMN "public"."seller_applications"."rejection_category" IS 'Category of rejection for analytics';



COMMENT ON COLUMN "public"."seller_applications"."withdrawn_at" IS 'Timestamp when seller withdrew their own application';



COMMENT ON COLUMN "public"."seller_applications"."can_reapply_at" IS 'Earliest timestamp when seller can reapply after rejection';



COMMENT ON COLUMN "public"."seller_applications"."rejection_count" IS 'Number of times this seller has been rejected (for tiered cooldown)';



COMMENT ON COLUMN "public"."seller_applications"."withdrawal_count" IS 'Number of times seller has withdrawn (for anti-spam)';



COMMENT ON COLUMN "public"."seller_applications"."profile_picture_path" IS 'Storage path (profile-pictures bucket) of the store image/logo uploaded during the become-seller wizard';



COMMENT ON COLUMN "public"."seller_applications"."games_categories" IS 'Per-game category selection: [{ gameId, gameSlug, categorySlugs: string[] }]';



COMMENT ON COLUMN "public"."seller_applications"."selling_experience" IS 'Optional: prior marketplace name / store link from Review & Sign step';



COMMENT ON COLUMN "public"."seller_applications"."payout_currency" IS 'Optional payout currency preference (e.g. USD, EUR, USDT)';



COMMENT ON COLUMN "public"."seller_applications"."seller_signature" IS 'Typed-name e-signature for the Seller Agency Agreement';



COMMENT ON COLUMN "public"."seller_applications"."seller_signed_at" IS 'Timestamp the Seller Agency Agreement signature was recorded';



