CREATE OR REPLACE VIEW "public"."seller_dashboard_stats" AS
 SELECT "id" AS "seller_id",
    "username",
    "seller_tier",
    "total_sales",
    "seller_rating",
    ( SELECT "count"(*) AS "count"
           FROM "public"."listings"
          WHERE (("listings"."seller_id" = "p"."id") AND ("listings"."status" = 'active'::"text"))) AS "active_listings",
    ( SELECT "count"(*) AS "count"
           FROM "public"."listings"
          WHERE (("listings"."seller_id" = "p"."id") AND ("listings"."status" = 'paused'::"text"))) AS "paused_listings",
    ( SELECT "count"(*) AS "count"
           FROM "public"."listings"
          WHERE (("listings"."seller_id" = "p"."id") AND ("listings"."status" = 'draft'::"text"))) AS "draft_listings",
    ( SELECT "count"(*) AS "count"
           FROM "public"."listings"
          WHERE (("listings"."seller_id" = "p"."id") AND ("listings"."status" = 'sold'::"text"))) AS "sold_listings",
    ( SELECT "count"(*) AS "count"
           FROM "public"."orders"
          WHERE (("orders"."seller_id" = "p"."id") AND ("orders"."status" = 'pending'::"text"))) AS "pending_orders",
    ( SELECT "count"(*) AS "count"
           FROM "public"."orders"
          WHERE (("orders"."seller_id" = "p"."id") AND ("orders"."status" = 'processing'::"text"))) AS "processing_orders",
    ( SELECT "count"(*) AS "count"
           FROM "public"."orders"
          WHERE (("orders"."seller_id" = "p"."id") AND ("orders"."status" = 'completed'::"text"))) AS "completed_orders",
    ( SELECT "count"(*) AS "count"
           FROM "public"."orders"
          WHERE (("orders"."seller_id" = "p"."id") AND ("orders"."status" = 'disputed'::"text"))) AS "disputed_orders",
    ( SELECT COALESCE("sum"("listings"."views"), (0)::bigint) AS "coalesce"
           FROM "public"."listings"
          WHERE ("listings"."seller_id" = "p"."id")) AS "total_views",
    ( SELECT COALESCE("sum"("listings"."sales"), (0)::bigint) AS "coalesce"
           FROM "public"."listings"
          WHERE ("listings"."seller_id" = "p"."id")) AS "total_listing_sales",
    ( SELECT COALESCE("sum"("orders"."seller_payout"), (0)::numeric) AS "coalesce"
           FROM "public"."orders"
          WHERE (("orders"."seller_id" = "p"."id") AND ("orders"."status" = 'completed'::"text") AND ("date"("orders"."created_at") = CURRENT_DATE))) AS "earnings_today",
    ( SELECT COALESCE("sum"("orders"."seller_payout"), (0)::numeric) AS "coalesce"
           FROM "public"."orders"
          WHERE (("orders"."seller_id" = "p"."id") AND ("orders"."status" = 'completed'::"text") AND ("orders"."created_at" >= (CURRENT_DATE - '7 days'::interval)))) AS "earnings_week",
    ( SELECT COALESCE("sum"("orders"."seller_payout"), (0)::numeric) AS "coalesce"
           FROM "public"."orders"
          WHERE (("orders"."seller_id" = "p"."id") AND ("orders"."status" = 'completed'::"text") AND ("orders"."created_at" >= (CURRENT_DATE - '30 days'::interval)))) AS "earnings_month",
    ( SELECT COALESCE("sum"("orders"."seller_payout"), (0)::numeric) AS "coalesce"
           FROM "public"."orders"
          WHERE (("orders"."seller_id" = "p"."id") AND ("orders"."status" = 'completed'::"text"))) AS "earnings_all_time"
   FROM "public"."profiles" "p"
  WHERE ("seller_tier" IS NOT NULL);


ALTER VIEW "public"."seller_dashboard_stats" OWNER TO "postgres";


COMMENT ON VIEW "public"."seller_dashboard_stats" IS 'Aggregated seller dashboard statistics';



