COMMENT ON COLUMN "public"."seller_tier_config"."auto_approve_bulk" IS 'TRUE ⇒ bulk-uploaded listings from this tier are auto-approved.';



COMMENT ON COLUMN "public"."seller_tier_config"."pre_moderation_listings" IS 'Until the seller has this many approved listings, every new active listing is downgraded to pending_approval. 0 = no pre-moderation.';



