    "country_code" character varying(2),
    "city" character varying(100),
    "device_type" character varying(20),
    "page_path" "text",
    "session_id" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"(),
    CONSTRAINT "shop_visits_device_type_check" CHECK ((("device_type")::"text" = ANY ((ARRAY['desktop'::character varying, 'mobile'::character varying, 'tablet'::character varying, 'unknown'::character varying])::"text"[])))
);


