CREATE OR REPLACE VIEW "public"."shop_analytics_summary" AS
 SELECT "seller_id",
    "count"(DISTINCT "session_id") AS "total_unique_visits",
    "count"(*) AS "total_page_views",
    "count"(DISTINCT "visitor_id") FILTER (WHERE ("visitor_id" IS NOT NULL)) AS "unique_registered_visitors",
    "count"(*) FILTER (WHERE ("visited_at" >= ("now"() - '24:00:00'::interval))) AS "visits_last_24h",
    "count"(*) FILTER (WHERE ("visited_at" >= ("now"() - '7 days'::interval))) AS "visits_last_7d",
    "count"(*) FILTER (WHERE ("visited_at" >= ("now"() - '30 days'::interval))) AS "visits_last_30d",
    "count"(DISTINCT "date"("visited_at")) FILTER (WHERE ("visited_at" >= ("now"() - '30 days'::interval))) AS "active_days_last_30d"
   FROM "public"."shop_visits"
  GROUP BY "seller_id";


ALTER VIEW "public"."shop_analytics_summary" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."trustpilot_stats" AS
 SELECT "count"(*) AS "total_invitations",
    "count"(*) FILTER (WHERE ("review_submitted" = true)) AS "reviews_submitted",
    "count"(*) FILTER (WHERE (("review_submitted" = false) AND ("sent_at" < ("now"() - '14 days'::interval)))) AS "pending_reviews",
    "round"("avg"("review_rating"), 2) AS "average_rating",
    "count"(*) FILTER (WHERE ("review_rating" = 5)) AS "five_star_reviews",
    "count"(*) FILTER (WHERE ("review_rating" >= 4)) AS "positive_reviews"
   FROM "public"."trustpilot_invitations";


ALTER VIEW "public"."trustpilot_stats" OWNER TO "postgres";


COMMENT ON VIEW "public"."trustpilot_stats" IS 'Aggregated statistics for Trustpilot review invitations';



