CREATE OR REPLACE TRIGGER "trg_validate_order_status" BEFORE UPDATE OF "status" ON "public"."orders" FOR EACH ROW EXECUTE FUNCTION "public"."validate_order_status_transition"();



CREATE OR REPLACE TRIGGER "trigger_sync_listing_quantity" AFTER INSERT OR DELETE OR UPDATE ON "public"."instant_delivery_inventory" FOR EACH ROW EXECUTE FUNCTION "public"."sync_listing_quantity_with_inventory"();



CREATE OR REPLACE TRIGGER "trigger_update_review_edit_tracking" BEFORE UPDATE ON "public"."reviews" FOR EACH ROW WHEN ((("old"."rating" IS DISTINCT FROM "new"."rating") OR ("old"."comment" IS DISTINCT FROM "new"."comment") OR ("old"."title" IS DISTINCT FROM "new"."title"))) EXECUTE FUNCTION "public"."update_review_edit_tracking"();



CREATE OR REPLACE TRIGGER "trigger_update_review_timestamp" BEFORE UPDATE ON "public"."reviews" FOR EACH ROW EXECUTE FUNCTION "public"."update_review_timestamp"();



CREATE OR REPLACE TRIGGER "trigger_update_seller_rating_on_delete" AFTER DELETE ON "public"."reviews" FOR EACH ROW EXECUTE FUNCTION "public"."update_seller_rating"();



CREATE OR REPLACE TRIGGER "trigger_update_seller_rating_on_insert" AFTER INSERT ON "public"."reviews" FOR EACH ROW EXECUTE FUNCTION "public"."update_seller_rating"();



CREATE OR REPLACE TRIGGER "trigger_update_seller_rating_on_update" AFTER UPDATE ON "public"."reviews" FOR EACH ROW WHEN ((("old"."rating" IS DISTINCT FROM "new"."rating") OR ("old"."is_visible" IS DISTINCT FROM "new"."is_visible"))) EXECUTE FUNCTION "public"."update_seller_rating"();



CREATE OR REPLACE TRIGGER "trigger_update_wallet_balance" AFTER INSERT ON "public"."wallet_transactions" FOR EACH ROW WHEN (("new"."status" = 'completed'::"text")) EXECUTE FUNCTION "public"."update_wallet_balance"();



CREATE OR REPLACE TRIGGER "trigger_validate_banner_update" BEFORE UPDATE ON "public"."profiles" FOR EACH ROW WHEN ((("old"."banner_url" IS DISTINCT FROM "new"."banner_url") OR ("old"."seller_tier" IS DISTINCT FROM "new"."seller_tier"))) EXECUTE FUNCTION "public"."validate_banner_update"();



CREATE OR REPLACE TRIGGER "update_admin_roles_updated_at" BEFORE UPDATE ON "public"."admin_roles" FOR EACH ROW EXECUTE FUNCTION "public"."update_updated_at_column"();



CREATE OR REPLACE TRIGGER "update_disputes_updated_at" BEFORE UPDATE ON "public"."disputes" FOR EACH ROW EXECUTE FUNCTION "public"."update_updated_at_column"();



CREATE OR REPLACE TRIGGER "update_listing_template_timestamp_trigger" BEFORE UPDATE ON "public"."listing_templates" FOR EACH ROW EXECUTE FUNCTION "public"."update_listing_template_timestamp"();



CREATE OR REPLACE TRIGGER "update_seller_presence_timestamp_trigger" BEFORE UPDATE ON "public"."seller_presence" FOR EACH ROW EXECUTE FUNCTION "public"."update_seller_presence_timestamp"();



CREATE OR REPLACE TRIGGER "update_trustpilot_invitation_timestamp_trigger" BEFORE UPDATE ON "public"."trustpilot_invitations" FOR EACH ROW EXECUTE FUNCTION "public"."update_trustpilot_invitation_timestamp"();



